TURATH_CHUNK(37,[{"num":7400,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ الْعَزِيزِ - وَهُوَ ابْنُ صُهَيْبٍ - قَالَ:  سُئِلَ أَنَسٌ، عَنِ الثُّومِ؟ فَقَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ أَكَلَ مِنْ هَذِهِ الشَّجَرَةِ فَلَا يَقْرَبَنَّا، وَلَا يُصَلِّي مَعَنَا."],"takhrij":"متفق عليه: رواه البخاري في الأطعمة (5451)، ومسلم في المساجد (562) كلاهما من طريق عبد العزيز بن صهيب به. واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب ما جاء في أكل الثوم والبصل والكراث","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5451) and Muslim (562). The wording is from Muslim.","chapter_en":"What Has Been Reported Concerning Eating Garlic, Onion, and Leek","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":27,"content":{"translation":{"en":["ʿAbd al-ʿAziz ibn Suhayb said: Anas was asked about garlic, so he said: The Messenger of Allah ﷺ said: “Whoever eats from this plant must not come near us, nor pray with us.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (5451)، ومسلم (562). واللفظ لمسلم."},{"num":7401,"demo":false,"sanad":"","matn":["عَنْ جابر بْنِ عَبْدِ اللَّهِ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ أَكَلَ ثُومًا أَوْ بَصَلاً فَلْيَعْتَزِلْنَا –أَوْ ليعتزل مَسْجِدَنَا- ولتقعد فِي بَيْتِهِ، وانه أُتِيَ بِقِدْرٍ فِيهِ خَضِرَاتٌ مِنْ بُقُولٍ، فَوَجَدَ لَهَا رِيحًا، فَسَأَلَ فَأُخْبِرَ بِمَا فِيهَا مِنَ الْبُقُولِ، فَقَالَ: قَرِّبُوهَا إِلَى بَعْضِ أَصْحَابِهِ، فَلَمَّا رَآهُ كَرِهَ أَكْلَهَا، قَالَ: كُلْ فَإِنِّي أُنَاجِي مَنْ لاَ تُنَاجِي."],"takhrij":"متفق عليه: رواه البخاري في الصلاة (855)، ومسلم في المساجد (564: 73) –والسياق له- من طريق ابن وهب، أخبرني يونس، عن ابن شهاب، حدثني عطاء بن أبي رباح، أن جابر بن عبد الله قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في أكل الثوم والبصل والكراث","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (855) and Muslim (564:73). The wording is from Muslim.","chapter_en":"What Has Been Reported Concerning Eating Garlic, Onion, and Leek","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":27,"content":{"translation":{"en":["Jabir ibn ʿAbdullah narrated that the Messenger of Allah ﷺ said: “Whoever eats garlic or onion should keep away from us,” or, “keep away from our mosque, and sit in his house.” A pot containing green vegetables was brought to him, and he noticed its smell. He asked about it and was told what vegetables it contained. He said: “Bring it near to some of his Companions.” When he saw that he disliked eating it, he said: “Eat, for I converse privately with one whom you do not converse with.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (855)، ومسلم (564: 73) - والسياق له."},{"num":7402,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  مَنْ أَكَلَ مِنْ هَذِهِ الْبَقْلَةِ الثُّومِ - وَقَالَ مَرَّةً: مَنْ أَكَلَ الْبَصَلَ وَالثُّومَ وَالْكُرَّاثَ - فَلَا يَقْرَبَنَّ مَسْجِدَنَا، فَإِنَّ الْمَلَائِكَةَ تَتَأَذَّى مِمَّا يَتَأَذَّى مِنْهُ بَنُو آدَمَ."],"takhrij":"صحيح: رواه مسلم في المساجد (564: 74) عن محمد بن حاتم، حدثنا يحيى بن سعيد، عن ابن جريج، قال: أخبرني عطاء، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في أكل الثوم والبصل والكراث","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (564:74).","chapter_en":"What Has Been Reported Concerning Eating Garlic, Onion, and Leek","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":27,"content":{"translation":{"en":["Jabir ibn ʿAbdullah narrated from the Prophet ﷺ that he said: “Whoever eats from this herb, garlic” — and he once said: “Whoever eats onion, garlic, and leek” — “must not come near our mosque, for the angels are harmed by what the children of Adam are harmed by.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (564: 74)."},{"num":7403,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ قَالَ:  نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ أَكْلِ الْبَصَلِ وَالْكُرَّاثِ، فَغَلَبَتْنَا الْحَاجَةُ فَأَكَلْنَا مِنْهَا، فَقَالَ: مَنْ أَكَلَ مِنْ هَذِهِ الشَّجَرَةِ الْمُنْتِنَةِ فَلَا يَقْرَبَنَّ مَسْجِدَنَا، فَإِنَّ الْمَلَائِكَةَ تَأَذَّى مِمَّا يَتَأَذَّى مِنْهُ الْإِنْسُ."],"takhrij":"صحيح: رواه مسلم في المساجد ومواضع الصلاة (564: 72) عن أبي بكر بن أبي شيبة، حدثنا كثير بن هشام، عن هشام الدستوائي، عن أبي الزبير فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في أكل الثوم والبصل والكراث","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (564:72).","chapter_en":"What Has Been Reported Concerning Eating Garlic, Onion, and Leek","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":27,"content":{"translation":{"en":["Jabir said: The Messenger of Allah ﷺ forbade eating onion and leek, but need overcame us, so we ate from them. He said: “Whoever eats from this foul-smelling plant must not come near our mosque, for the angels are harmed by what humans are harmed by.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (564: 72)."},{"num":7404,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  مَنْ أَكَلَ مِنْ هَذِهِ الشَّجَرَةِ فَلَا يَقْرَبَنَّ مَسْجِدَنَا، وَلَا يُؤْذِيَنَّا بِرِيحِ الثُّومِ."],"takhrij":"صحيح: رواه مسلم في المساجد (563: 71) من طريق عبد الرزاق، أخبرنا معمر، عن الزهري، عن ابن المسيب، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في أكل الثوم والبصل والكراث","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (563:71).","chapter_en":"What Has Been Reported Concerning Eating Garlic, Onion, and Leek","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":27,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Whoever eats from this plant must not come near our mosque, nor harm us with the smell of garlic.”"]}},"tuhfa":{},"full":1,"rep":[3146],"tks":"صحيح: رواه مسلم (563: 71)."},{"num":7405,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ قَالَ:  لَمْ نَعْدُ أَنْ فُتِحَتْ خَيْبَرُ، فَوَقَعْنَا - أَصْحَابَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي تِلْكَ الْبَقْلَةِ الثُّومِ، وَالنَّاسُ جِيَاعٌ، فَأَكَلْنَا مِنْهَا أَكْلًا شَدِيدًا. ثُمَّ رُحْنَا إِلَى الْمَسْجِدِ، فَوَجَدَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الرِّيحَ، فَقَالَ: مَنْ أَكَلَ مِنْ هَذِهِ الشَّجَرَةِ الْخَبِيثَةِ شَيْئًا فَلَا يَقْرَبَنَّا فِي الْمَسْجِدِ. فَقَالَ النَّاسُ: حُرِّمَتْ! حُرِّمَتْ! فَبَلَغَ ذَاكَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: أَيُّهَا النَّاسُ! إِنَّهُ لَيْسَ بِي تَحْرِيمُ مَا أَحَلَّ اللَّهُ لِي، وَلَكِنَّهَا شَجَرَةٌ أَكْرَهُ رِيحَهَا."],"takhrij":"صحيح: رواه مسلم في المساجد (565) عن عمرو الناقد، حدثنا إسماعيل بن عُلية، عن الجُريري، عن أبي نضرة، عن أبي سعيد فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في أكل الثوم والبصل والكراث","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (565).","chapter_en":"What Has Been Reported Concerning Eating Garlic, Onion, and Leek","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":27,"content":{"translation":{"en":["Abu Saʿid al-Khudri said: No sooner had Khaybar been conquered than we, the Companions of the Messenger of Allah ﷺ, fell upon that herb, garlic, while the people were hungry. We ate a great deal of it, then we went to the mosque. The Messenger of Allah ﷺ noticed the smell and said: “Whoever eats anything from this foul plant must not come near us in the mosque.” The people said: “It has been forbidden, it has been forbidden.” That reached the Prophet ﷺ, so he said: “O people! I do not forbid what Allah has made lawful for me, but it is a plant whose smell I dislike.”"]}},"tuhfa":{},"full":1,"rep":[3148],"tks":"صحيح: رواه مسلم (565)."},{"num":7406,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ:  أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَرَّ عَلَى زَرَّاعَةِ بَصَلٍ هُوَ وَأَصْحَابُهُ. فَنَزَلَ نَاسٌ مِنْهُمْ فَأَكَلُوا مِنْهُ، وَلَمْ يَأْكُلْ آخَرُونَ. فَرُحْنَا إِلَيْهِ، فَدَعَا الَّذِينَ لَمْ يَأْكُلُوا الْبَصَلَ، وَأَخَّرَ الْآخَرِينَ حَتَّى ذَهَبَ رِيحُهَا."],"takhrij":"صحيح: رواه مسلم في المساجد (566) من طريق ابن وهب، أخبرني عمرو، عن بكير الأشج، عن ابن خباب (وهو عبد الله)، عن أبي سعيد الخدري فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في أكل الثوم والبصل والكراث","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (566).","chapter_en":"What Has Been Reported Concerning Eating Garlic, Onion, and Leek","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":27,"content":{"translation":{"en":["Abu Saʿid al-Khudri narrated that the Messenger of Allah ﷺ passed by an onion field with his Companions. Some of them stopped and ate from it, while others did not eat. Then we returned to him. He called those who had not eaten onion and delayed the others until its smell had gone away."]}},"tuhfa":{},"full":1,"dr":1,"rep":[3149],"tks":"صحيح: رواه مسلم (566)."},{"num":7407,"demo":false,"sanad":"","matn":["عن معدان أبي طلحة، أن عمر بن الخطاب خطب يوم الجمعة، فذكر نبي الله صلى الله عليه وسلم، وذكر أبا بكر –وذكر خطبة طويلة- قال في آخرها: ثم إنكم أيها الناس تأكلون شجرتين لاأراهما إلا خبيثتين، هذا البصل والثوم، لقد رأيت رسول الله صلى الله عليه وسلم إذا وجد ريحهما من الرجل أمر به فأخرج إلى البقيع، فمن أكلهما فليُمِتْهما طبخاً."],"takhrij":"صحيح: رواه مسلم في المساجد (567) عن محمد بن المثنى، ثنا يحيى بن سعيد، ثنا هشام، ثنا قتادة، عن سالم بن أبي الجعد، عن معدان بن أبي طلحة فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في أكل الثوم والبصل مطبوخين","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (567).","chapter_en":"What Has Been Reported Concerning Eating Garlic and Onion When Cooked","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":28,"content":{"translation":{"en":["Maʿdan ibn Abi Talhah narrated that ʿUmar ibn al-Khattab delivered a sermon on Friday. He mentioned the Prophet of Allah ﷺ and mentioned Abu Bakr — and he gave a long sermon — and at the end of it he said: “Then, O people, you eat two plants that I only see as foul: this onion and garlic. I saw the Messenger of Allah ﷺ, when he found their smell from a man, order that he be taken out to al-Baqiʿ. So whoever eats them should kill their smell by cooking.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (567)."},{"num":7408,"demo":false,"sanad":"","matn":["عَنْ قرة بن إياس: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ هَاتَيْنِ الشَّجَرَتَيْنِ فَقَالَ: مَنْ أَكَلَهُمَا فَلاَ يَقْرَبَنَّ مَسْجِدَنَا وَقَالَ: إِنْ كُنْتُمْ لاَ بُدَّ آكلوهما فَأَمِيتُوهُمَا طَبْخًا، قَالَ: يَعْنِي الْبَصَلَ وَالثُّومَ."],"takhrij":"حسن: رواه أبو داود (3827)، والنسائي في الكبرى (6646) والترمذي في العلل الكبير (2/765) والبيهقي في الكبرى (3/78) كلهم من طريق خالد بن ميسرة العطار، عن معاوية بن قرة، عن أبيه فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في أكل الثوم والبصل مطبوخين","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3827), al-Nasa’i in al-Kubra (6646), al-Tirmidhi in al-ʿIlal al-Kabir (2/765), and al-Bayhaqi in al-Sunan al-Kubra (3/78).","chapter_en":"What Has Been Reported Concerning Eating Garlic and Onion When Cooked","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":28,"content":{"translation":{"en":["Qurrah ibn Iyas narrated that the Messenger of Allah ﷺ forbade these two plants and said: “Whoever eats them must not come near our mosque.” And he said: “If you must eat them, then kill their smell by cooking.” He said: Meaning onion and garlic."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3827)، والنسائي في الكبرى (6646)، والترمذي في العلل الكبير (2/765)، والبيهقي في الكبرى (3/78)."},{"num":7409,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ سَمُرَةَ، أَنَّ رَجُلاً، نَزَلَ الْحَرَّةَ وَمَعَهُ أَهْلُهُ وَوَلَدُهُ، فَقَالَ رَجُلٌ: إِنَّ نَاقَةً لِي ضَلَّتْ، فَإِنْ وَجَدْتَهَا فَأَمْسِكْهَا. فَوَجَدَهَا فَلَمْ يَجِدْ صَاحِبَهَا فَمَرِضَتْ فَقَالَتِ امْرَأَتُهُ: انْحَرْهَا. فَأَبَى فَنَفَقَتْ، فَقَالَتِ: اسْلُخْهَا حَتَّى نُقَدِّدَ شَحْمَهَا وَلَحْمَهَا وَنَأْكُلَهُ. فَقَالَ: حَتَّى أَسْأَلَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَتَاهُ فَسَأَلَهُ فَقَالَ: هَلْ عِنْدَكَ غِنًى يُغْنِيكَ. قَالَ: لاَ. قَالَ: فَكُلُوهَا. قَالَ فَجَاءَ صَاحِبُهَا، فَأَخْبَرَهُ الْخَبَرَ فَقَالَ: هَلاَّ كُنْتَ نَحَرْتَهَا. قَالَ: اسْتَحْيَيْتُ مِنْكَ."],"takhrij":"حسن: رواه أبو داود (3816)، وأحمد (20993)، وابنه عبد الله (20903) كلهم من طرق عن حماد بن سلمة، ثنا سماك، عن جابر بن سمرة فذكره.","grade":"حسن","chapter_ar":"باب تحريم أكل الميتة وإباحتها للمضطر","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3816), Ahmad (20993), and his son ʿAbdullah (20903).","chapter_en":"The Prohibition of Eating Carrion and Its Permissibility for One Compelled by Necessity","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Jabir ibn Samurah narrated that a man settled in al-Harrah with his family and children. Another man said: “A she-camel of mine has gone missing. If you find it, hold it.” He found it but did not find its owner. It became sick, and his wife said: “Slaughter it.” He refused, and it died. She said: “Skin it so that we may dry its fat and meat and eat it.” He said: “Not until I ask the Messenger of Allah ﷺ.” So he came to him and asked him. He said: “Do you have any wealth that suffices you?” He said: “No.” He said: “Then eat it.” He said: Then its owner came, and he informed him of what had happened. He said: “Why did you not slaughter it?” He said: “I felt shy before you.”"]},"intro":{"ar":["وقال تعالى:","(حُرِّمَتْ عَلَيْكُمُ الْمَيْتَةُ وَالدَّمُ وَلَحْمُ الْخِنزِيرِ وَمَا أُهِلَّ لِغَيْرِ اللَّهِ بِهِ وَالْمُنْخَنِقَةُ وَالْمَوْقُوذَةُ وَالْمُتَرَدِّيَةُ وَالنَّطِيحَةُ وَمَا أَكَلَ السَّبُعُ إِلَّا مَا ذَكَّيْتُمْ وَمَا ذُبِحَ عَلَى النُّصُبِ وَأَن تَسْتَقْسِمُوا بِالْأَزْلَامِ ذَٰلِكُمْ فِسْقٌ الْيَوْمَ يَئِسَ الَّذِينَ كَفَرُوا مِن دِينِكُمْ فَلَا تَخْشَوْهُمْ وَاخْشَوْنِ الْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِي وَرَضِيتُ لَكُمُ الإِسْلَامَ دِيناً فَمَنِ اضْطُرَّ فِي مَخْمَصَةٍ غَيْرَ مُتَجَانِفٍ لِإِثْمٍ فَإِنَّ اللَّهَ غَفُورٌ رَّحِيمٌ) [المائدة: ٣]","والحكمة في ذلك أن أكل المحرمات المذكورة في الآية السابقة وآية البقرة (١٧٣) لا يضر أكلها إن أكلها الإنسان على المعدة الخالية، بخلاف الأكل حالة الشبع."],"en":["And He said:","“Forbidden to you are carrion, blood, the flesh of swine, that which has been dedicated to other than Allah, animals strangled, struck dead, fallen to death, gored to death, and what a predator has eaten — except what you slaughter before it dies — and what is sacrificed on stone altars, and that you seek decision through divining arrows. That is grave disobedience. Today those who disbelieve have despaired of your religion, so do not fear them, but fear Me. Today I have perfected for you your religion, completed My favor upon you, and chosen Islam for you as a religion. But whoever is compelled by severe hunger, not inclining to sin, then indeed Allah is Forgiving, Merciful.” [al-Ma’idah: 3]","The wisdom in this is that eating the forbidden things mentioned in the previous verse and in the verse of al-Baqarah (173) does not harm a person if he eats them on an empty stomach, unlike eating them while already full."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3816)، وأحمد (20993)، وابنه عبد الله (20903)."},{"num":7410,"demo":false,"sanad":"","matn":["عَنْ سَمُرَةَ بْنِ جندب، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يُجْزِئُ مِنَ الضَّرُورَةِ أَوِ الضَّارُورَةِ غَبُوقٌ أَوْ صَبُوحٌ."],"takhrij":"صحيح: رواه الحاكم (7158) من طريق معاذ بن معاذ العنبري، ثنا ابن عون قال: قرأت عند الحسن كتاب سمرة بن جندب إلى بنيه، وفيه: أن رسول الله صلى الله عليه وسلم قال: فذكره.","grade":"صحيح","chapter_ar":"باب متى يحل أكل الميتة؟","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Hakim (7158).","chapter_en":"When Does Eating Carrion Become Permissible?","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":2,"content":{"translation":{"en":["Samurah ibn Jundub narrated that the Messenger of Allah ﷺ said: “A drink or meal in the evening, or a drink or meal in the morning, suffices for necessity.”"]},"buhuth":{"en":["His statement, “necessity,” is another linguistic form of the same word, as mentioned in al-Nihayah. His statement, “ghabuq,” refers to drinking at the end of the day, and “sabhuh” refers to drinking at its beginning. Then the terms came to be used for eating as well: the morning meal is lunch, and the evening meal is dinner."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الحاكم (7158)."},{"num":7411,"demo":false,"sanad":"","matn":["عَنْ أَبِي وَاقِدٍ اللَّيْثِيِّ قَالَ: قَدِمَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمَدِينَةَ وَهُمْ يَجُبّون أَسْنِمَةَ الْإِبِلِ، وَيَقْطَعُونَ أَلْيَاتِ الْغَنَمِ، فَقَالَ: مَا قُطع مِنَ الْبَهِيمَةِ وَهِيَ حَيَّةٌ فَهِيَ مَيْتَةٌ."],"takhrij":"حسن: رواه أبو داود (2858)، والترمذي (1480) واللفظ له، وأحمد (21903)، وابن الجارود (876)، والحاكم (7150) كلهم من طرق عن عبد الرحمن بن عبد الله بن دينار، عن زيد بن أسلم، عن عطاء بن يسار، عن أبي واقد الليثي، فذكره.","grade":"حسن","chapter_ar":"باب النهي عن أكل ما يُقطع من بهيمة الأنعام وهي حية","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2858), al-Tirmidhi (1480), whose wording this is, Ahmad (21903), Ibn al-Jarud (876), and al-Hakim (7597).","chapter_en":"The Prohibition of Eating What Is Cut from Grazing Livestock While It Is Alive","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":3,"content":{"translation":{"en":["Abu Waqid al-Laythi said: The Prophet ﷺ came to Madinah while they were cutting off the humps of camels and cutting off the fat tails of sheep. He said: “Whatever is cut from an animal while it is alive is carrion.”"]},"buhuth":{"en":["His statement, “they were cutting off,” means they were severing them. His statement, “fat tails,” refers to the tail end of the sheep. Every limb cut from an animal while it is alive is not permissible to eat, because it becomes carrion when life leaves it. They used to do this in the pre-Islamic period, so they were forbidden from it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (2858)، والترمذي (1480) واللفظ له، وأحمد (21903)، وابن الجارود (876)، والحاكم (7597)."},{"num":7412,"demo":false,"sanad":"","matn":["عَنْ أَبِي ثَعْلَبَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ أَكْلِ كُلِّ ذِي نَابٍ مِنَ السِّبَاعِ."],"takhrij":"متفق عليه: رواه مالك في الضحايا (2176-رواية أبي مصعب الزهري) عن ابن شهاب، عن أبي إدريس الخولاني، عن أبي ثعلبة الخشني فذكره. ورواه البخاري في الذبائح والصيد (5530) عن عبد الله بن يوسف، أخبرنا مالك به.","grade":"متفق عليه","chapter_ar":"باب تحريم أكل كلِّ ذي ناب من السباع، وكل ذي مخلب من الطير","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik in al-Dahaya (2176, the narration of Abu Musʿab al-Zuhri), al-Bukhari (5530), and Muslim (1932:14).","chapter_en":"The Prohibition of Eating Every Predator with Fangs and Every Bird with Talons","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Abu Thaʿlabah al-Khushani narrated that the Messenger of Allah ﷺ forbade eating every predator with fangs."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (2176-رواية أبي مصعب الزهري)، والبخاري (5530)، ومسلم (14:1932)."},{"num":7413,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَكْلُ كُلِّ ذِي نَابٍ مِنَ السِّبَاعِ حَرَامٌ."],"takhrij":"صحيح: رواه مالك في الصيد (14) عن إسماعيل بن أبي حكيم، عن عبيدة بن سفيان الحضرمي، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب تحريم أكل كلِّ ذي ناب من السباع، وكل ذي مخلب من الطير","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (14) and Muslim (1933:15).","chapter_en":"The Prohibition of Eating Every Predator with Fangs and Every Bird with Talons","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ said: “Eating every predator with fangs is forbidden.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مالك (14)، ومسلم (15:1933)."},{"num":7414,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ:  نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ كُلِّ ذِي نَابٍ مِنَ السِّبَاعِ، وَعَنْ كُلِّ ذِي مِخْلَبٍ مِنَ الطَّيْرِ."],"takhrij":"صحيح: رواه مسلم في الصيد والذبائح (1934: 16) عن عبيد الله بن معاذ العنبري، حدثنا أبي، حدثنا شعبة، عن الحكم (هو ابن عيينة)، عن ميمون بن مهران، عن ابن عباس قال: فذكره.","grade":"صحيح","chapter_ar":"باب تحريم أكل كلِّ ذي ناب من السباع، وكل ذي مخلب من الطير","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1934:16).","chapter_en":"The Prohibition of Eating Every Predator with Fangs and Every Bird with Talons","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Ibn ʿAbbas said: “The Messenger of Allah ﷺ forbade every predator with fangs and every bird with talons.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1934: 16)."},{"num":7415,"demo":false,"sanad":"","matn":["عَنِ الْمِقْدَامِ بْنِ مَعْدِيكَرِبَ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَلاَ لاَ يَحِلُّ ذُو نَابٍ مِنَ السِّبَاعِ، وَلاَ الْحِمَارُ الأَهْلِيُّ، وَلاَ اللُّقَطَةُ مِنْ مَالِ مُعَاهِدٍ إِلاَّ أَنْ يَسْتَغْنِيَ عَنْهَا، وَأَيُّمَا رَجُلٍ ضَافَ قَوْمًا فَلَمْ يَقْرُوهُ، فَإِنَّ لَهُ أَنْ يُعْقِبَهُمْ بِمِثْلِ قِرَاهُ."],"takhrij":"صحيح: رواه أبو داود (3804) عن محمد بن المصفّى الحمصي، ثنا محمد بن حرب، عن الزبيدي، عن مروان بن رؤبة التغلبي، عن عبد الرحمن بن أبي عوف، عن المقدام بن معديكرب فذكره.","grade":"صحيح","chapter_ar":"باب تحريم أكل كلِّ ذي ناب من السباع، وكل ذي مخلب من الطير","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (4604, 3804) and Ahmad (17174).","chapter_en":"The Prohibition of Eating Every Predator with Fangs and Every Bird with Talons","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Al-Miqdam ibn Maʿdikarib narrated from the Messenger of Allah ﷺ that he said: “Indeed, no predator with fangs is lawful, nor the domestic donkey, nor lost property from the wealth of a person under covenant unless its owner has no need of it. And any man who is a guest of a people and they do not host him, then he may take from them the equivalent of his hospitality.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (3804)، (3804)، وأحمد (17174)."},{"num":7416,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَرَّمَ يَوْمَ خَيْبَرَ كُلَّ ذِي نَابٍ مِنَ السِّبَاعِ، وَالْمُجَثَّمَةَ، وَالْحِمَارَ الإِنْسِيَّ."],"takhrij":"حسن: رواه الترمذي (1795)، وأحمد (8789) من طريق زائدة، عن محمد بن عمرو، عن أبي سلمة، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب تحريم أكل كلِّ ذي ناب من السباع، وكل ذي مخلب من الطير","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1795) and Ahmad (8789). Al-Tirmidhi said: “Hasan Sahih.”","chapter_en":"The Prohibition of Eating Every Predator with Fangs and Every Bird with Talons","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Abu Hurayrah said: On the day of Khaybar, the Messenger of Allah ﷺ forbade every predator with fangs, animals tied up and shot, and the domestic donkey."]}},"tuhfa":{},"full":1,"dr":1,"rep":[7439],"tks":"حسن: رواه الترمذي (1795)، وأحمد (8789)، وقال الترمذي: “حسن صحيح”."},{"num":7417,"demo":false,"sanad":"","matn":["عَنِ الْعِرْبَاضِ بْنِ سَارِيَةَ قَالَ: نَزَلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَيْبَرَ، وَكَانَ صَاحِبُ خَيْبَرَ مَارِدًا مُنْكَرًا، فَأَقْبَلَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: يَا مُحَمَّدُ، أَلْكُمْ أَنْ تَذْبَحُوا حُمُرَنَا، وَتَأْكُلُوا تَمْرَنَا، وتَدْخُلُوا بُيُوتَنَا، وَتَضْرِبُوا نِسَاءَنَا؟ فَغَضِبَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: يَا عَبْدَ الرَّحْمَنِ، ارْكَبْ فَرَسَكَ، فَنَادِ فِي النَّاسِ: إِنَّ الْجَنَّةَ لَا تَحِلُّ إِلَّا لِمُؤْمِنٍ، وَأَنِ اجْتَمِعُوا إِلَى الصَّلَاةِ، فَاجْتَمَعُوا، فَصَلَّى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ قَالَ: إِنَّ اللَّهَ لَمْ يَحِلَّ لَكُمْ أَنْ تَدْخُلُوا بُيُوتَ أَهْلِ الْكِتَابِ إِلَّا بِإِذْنٍ، وَلَا أَكَلَ أَمْوَالِهِمْ، وَلَا ضَرَبَ نِسَائِهِمْ، إِذَا أَعْطَوْكُمُ الَّذِي عَلَيْهِمْ، إِلَّا مَا طَابُوا بِهِ نَفْسًا، أَيَحْسَبُ امْرُؤٌ قَدْ شَبِعَ حَتَّى بَطِنَ، وَهُوَ مُتَّكِئٌ عَلَى أَرِيكَتِهِ، لَا يَظُنُّ أَنَّ اللَّهَ حَرَّمَ شَيْئًا إِلَّا مَا فِي هَذَا الْقُرْآنِ؟ أَلَا وَإِنِّي قَدْ وَاللَّهِ حَرَّمْتُ وَأَمَرْتُ، وَوَعَظْتُ بِأَشْيَاءَ، إِنَّهَا لَمِثْلُ الْقُرْآنِ، أَوْ أَكْثَرُ، أَلَا وَإِنَّهُ لَا يَحِلُّ لَكُمْ مِنَ السِّبَاعِ كُلُّ ذِي نَابٍ، وَلَا الْحُمُرُ الْأَهْلِيَّةُ."],"takhrij":"حسن: رواه الطبراني في الأوسط (7222)، وفي الكبير (18/ (645) مختصرا، وابن أبي عاصم في الآحاد والمثاني (1336)، ومحمد بن نصر المروزي في السنة (ص 116) كلهم من طريق أشعث بن شعبة قال: سمعت أرطاة بن المنذر قال: سمعت حكيم بن عمير، عن العرباض بن سارية فذكره.","grade":"حسن","chapter_ar":"باب تحريم أكل كلِّ ذي ناب من السباع، وكل ذي مخلب من الطير","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Awsat (7222), and in al-Kabir (18/645) in abbreviated form, Ibn Abi ʿAsim in al-Ahad wa al-Mathani (1336), and Muhammad ibn Nasr al-Marwazi in al-Sunnah (p. 116).","chapter_en":"The Prohibition of Eating Every Predator with Fangs and Every Bird with Talons","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Al-ʿIrbad ibn Sariyah said: The Prophet ﷺ stopped at Khaybar, and the leader of Khaybar was rebellious and objectionable. He came to the Prophet ﷺ and said: “O Muhammad, is it lawful for you to slaughter our donkeys, eat our dates, enter our houses, and strike our women?” The Prophet ﷺ became angry and said: “O ʿAbd al-Rahman, mount your horse and announce among the people: Paradise is not lawful except for a believer, and gather for the prayer.” So they gathered, and the Prophet ﷺ prayed. Then he said: “Allah has not made it lawful for you to enter the houses of the People of the Book except with permission, nor to eat their wealth, nor to strike their women, as long as they give you what is due from them, except what they willingly give. Does a man think, after becoming full until his belly is filled, while reclining on his couch, that Allah has not forbidden anything except what is in this Qur’an? Indeed, by Allah, I have forbidden, commanded, and admonished regarding things that are like the Qur’an or even more. Indeed, it is not lawful for you to eat every predator with fangs, nor domestic donkeys.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الأوسط (7222)، وفي الكبير (18/645) مختصرا، وابن أبي عاصم في الآحاد والمثاني (1336)، ومحمد بن نصر المروزي في السنة (ص 116)."},{"num":7418,"demo":false,"sanad":"","matn":["عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ: رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ مُتْعَةِ النِّسَاءِ يَوْمَ خَيْبَرَ، وَعَنْ أَكْلِ الْحُمُرِ الإِنْسِيَّةِ."],"takhrij":"متفق عليه: رواه مالك في النكاح (41) عن ابن شهاب، عن عبد الله والحسن ابنيْ محمد بن علي بن أبي طالب، عن أبيهما، عن علي بن أبي طالب فذكره.","grade":"متفق عليه","chapter_ar":"باب تحريم لحوم الحمر الإنسية","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (41), al-Bukhari (5523), and Muslim (1407:22).","chapter_en":"The Prohibition of the Meat of Domestic Donkeys","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":5,"content":{"translation":{"en":["ʿAli ibn Abi Talib narrated that the Messenger of Allah ﷺ forbade temporary marriage with women on the day of Khaybar, and forbade eating the meat of domestic donkeys."]}},"tuhfa":{},"full":1,"dr":1,"rep":[6462],"tks":"متفق عليه: رواه مالك (41)، والبخاري (5523)، ومسلم (22:1407)."},{"num":7419,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن عُمَرَ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ أَكْلِ لُحُومِ الْحُمُرِ الْأَهْلِيَّةِ."],"takhrij":"متفق عليه: رواه البخاري في الذبائح (5521)، ومسلم في الصيد والذبائح (561: 24) كلاهما من طريق عبيد الله، حدثني نافع –وزاد مسلم: وسالم- عن ابن عمر فذكره.","grade":"متفق عليه","chapter_ar":"باب تحريم لحوم الحمر الإنسية","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5521) and Muslim (561:24).","chapter_en":"The Prohibition of the Meat of Domestic Donkeys","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":5,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar narrated that the Messenger of Allah ﷺ forbade eating the meat of domestic donkeys."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (5521)، ومسلم (561: 24)."},{"num":7420,"demo":false,"sanad":"","matn":["عَنْ أَبِي ثَعْلَبَةَ الْخُشَنِيِّ، صَاحِبِ رَسُولِ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  أَنَّهُ قَالَ: حَرَّمَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  لُحُومَ الْحُمُرِ الْأَهْلِيَّةِ."],"takhrij":"متفق عليه: رواه البخاري في الصيد والذبائح (5527)، ومسلم في الصيد والذبائح (1936: 23) كلاهما من طريق يعقوب بن إبراهيم بن سعد، حدثنا أبي، عن صالح، عن ابن شهاب، أن أبا إدريس أخبره، ان ثعلبة قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب تحريم لحوم الحمر الإنسية","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5527) and Muslim (1936:23).","chapter_en":"The Prohibition of the Meat of Domestic Donkeys","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":5,"content":{"translation":{"en":["Abu Thaʿlabah al-Khushani said: The Messenger of Allah ﷺ forbade the meat of domestic donkeys."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (5527)، ومسلم (1936: 23)."},{"num":7421,"demo":false,"sanad":"","matn":["عَنِ الشَّيْبَانِيِّ قَالَ:  سَأَلْتُ عَبْدَ اللَّهِ بْنَ أَبِي أَوْفَى عَنْ لُحُومِ الْحُمُرِ الْأَهْلِيَّةِ، فَقَالَ: أَصَابَتْنَا مَجَاعَةٌ يَوْمَ خَيْبَرَ، وَنَحْنُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَدْ أَصَبْنَا لِلْقَوْمِ حُمُرًا خَارِجَةً مِنَ الْمَدِينَةِ، فَنَحَرْنَاهَا، فَإِنَّ قُدُورَنَا لَتَغْلِي إِذْ نَادَى مُنَادِي رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنِ اكْفَئُوا الْقُدُورَ، وَلَا تَطْعَمُوا مِنْ لُحُومِ الْحُمُرِ شَيْئًا. فَقُلْتُ: حَرَّمَهَا تَحْرِيمَ مَاذَا؟ قَالَ: تَحَدَّثْنَا بَيْنَنَا فَقُلْنَا: حَرَّمَهَا أَلْبَتَّةَ، وَحَرَّمَهَا مِنْ أَجْلِ أَنَّهَا لَمْ تُخَمَّسْ.","وفي رواية: وقال بعضهم: نهى عنها البتة؛ لأنها كانت تأكل العَذِرة."],"takhrij":"متفق عليه: رواه البخاري في فرض الخمس (3155)، ومسلم في الصيد والذبائح (1937: 26) كلاهما من طريق الشيباني به. واللفظ لمسلم، ولفظ البخاري مثله إلا أنه زاد: وسألتُ سعيد بن جبير فقال: \"حرّمها البتة\".","grade":"متفق عليه","chapter_ar":"باب تحريم لحوم الحمر الإنسية","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (3155) and Muslim (1937:26). The wording is from Muslim. The other narration is from al-Bukhari (4220).","chapter_en":"The Prohibition of the Meat of Domestic Donkeys","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":5,"content":{"translation":{"en":["Al-Shaybani said: I asked ʿAbdullah ibn Abi Awfa about the meat of domestic donkeys. He said: Hunger struck us on the day of Khaybar while we were with the Messenger of Allah ﷺ, and we had captured donkeys belonging to the people outside Madinah, so we slaughtered them. Our pots were boiling when the caller of the Messenger of Allah ﷺ called out: “Overturn the pots, and do not eat anything from the meat of donkeys.” I said: “What kind of prohibition did he forbid it with?” He said: We discussed it among ourselves and said: He forbade it absolutely, and he forbade it because it had not been divided as war booty. In another narration: Some of them said: He forbade it absolutely because it used to eat filth."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3155)، ومسلم (1937: 26). واللفظ لمسلم. والرواية الأخرى للبخاري bukhari(4220)."},{"num":7422,"demo":false,"sanad":"","matn":["عَنِ الْبَرَاءِ وَعَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى قَالاَ: أَصَبْنَا حُمْرًا، فَطَبَخْنَاهَا، فَنَادَى مُنَادِي رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اكْفِئُوا الْقُدُورَ.","وفي رواية: نهى النبي صلى الله عليه وسلم عن لحوم الحمر."],"takhrij":"متفق عليه: رواه البخاري في المغازي (4221، 4222)، ومسلم في الصيد والذبائح (1938: 28) كلاهما من طريق شعبة، عن عدي بن ثابت، عن البراء وعبد الله بن أبي أوفى قالا: فذكراه. واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب تحريم لحوم الحمر الإنسية","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (4221) and Muslim (1938:28). The wording is from Muslim. The other narration is from al-Bukhari (5525).","chapter_en":"The Prohibition of the Meat of Domestic Donkeys","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":5,"content":{"translation":{"en":["Al-Bara’ and ʿAbdullah ibn Abi Awfa said: We captured donkeys and cooked them. Then the caller of the Messenger of Allah ﷺ called out: “Overturn the pots.” In another narration: “The Prophet ﷺ forbade the meat of donkeys.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (4221)، ومسلم (1938: 28). واللفظ لمسلم. والرواية الأخرى للبخاري bukhari(5525)."},{"num":7423,"demo":false,"sanad":"","matn":["عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: أَمَرَنَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي غَزْوَةِ خَيْبَرَ أَنْ نُلْقِيَ الْحُمُرَ الأَهْلِيَّةَ نِيئَةً وَنَضِيجَةً، ثُمَّ لَمْ يَأْمُرْنَا بِأَكْلِهِ بَعْدُ."],"takhrij":"متفق عليه: رواه البخاري في المغازي (4226)، ومسلم في الصيد (1938: 31) كلاهما من طريق عاصم، عن عامر الشعبي، عن البراء بن عازب فذكره.","grade":"متفق عليه","chapter_ar":"باب تحريم لحوم الحمر الإنسية","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (4226) and Muslim (1938:31).","chapter_en":"The Prohibition of the Meat of Domestic Donkeys","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":5,"content":{"translation":{"en":["Al-Bara’ ibn ʿAzib said: During the expedition of Khaybar, the Prophet ﷺ ordered us to throw away the domestic donkeys, whether raw or cooked, and he never later ordered us to eat it."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (4226)، ومسلم (1938: 31)."},{"num":7424,"demo":false,"sanad":"","matn":["عن عَمْرِو، قُلْتُ لِجَابِرِ بْنِ زَيْدٍ: يَزْعُمُونَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ حُمُرِ الأَهْلِيَّةِ؟ فَقَالَ: قَدْ كَانَ يَقُولُ ذَاكَ الْحَكَمُ بْنُ عَمْرٍو الْغِفَارِيُّ عِنْدَنَا بِالْبَصْرَةِ، وَلَكِنْ أَبَى ذَاكَ الْبَحْرُ ابْنُ عَبَّاسٍ وَقَرَأَ {قُلْ لاَ أَجِدُ فِيمَا أُوحِيَ إِلَىَّ مُحَرَّمًا}."],"takhrij":"صحيح: رواه البخاري في الذبائح والصيد (5529) عن علي بن عبد الله، حدثنا سفيان، قال عمرو: قلت لجابر بن زيد: فذكره.","grade":"صحيح","chapter_ar":"باب تحريم لحوم الحمر الإنسية","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5529).","chapter_en":"The Prohibition of the Meat of Domestic Donkeys","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":5,"content":{"translation":{"en":["ʿAmr said: I said to Jabir ibn Zayd: “They claim that the Messenger of Allah ﷺ forbade domestic donkeys.” He said: “Al-Hakam ibn ʿAmr al-Ghifari used to say that among us in Basrah, but that ocean of knowledge, Ibn ʿAbbas, refused that and recited: ‘Say: I do not find in what has been revealed to me anything forbidden…’ [al-Anʿam: 145].”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (5529)."},{"num":7425,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: لاَ أَدْرِي أَنَهَى عَنْهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ أَجْلِ أَنَّهُ كَانَ حَمُولَةَ النَّاسِ، فَكَرِهَ أَنْ تَذْهَبَ حَمُولَتُهُمْ، أَوْ حَرَّمَهُ فِي يَوْمِ خَيْبَرَ، لَحْمَ الْحُمُرِ الأَهْلِيَّةِ."],"takhrij":"متفق عليه: رواه البخاري في المغازي (4227)، ومسلم في الصيد والذبائح (1939: 32) كلاهما من طريق عمر بن حفص بن غياث، حدثنا أبي، عن عاصم، عن عامر (هو الشعبي)، عن ابن عباس فذكره.","grade":"متفق عليه","chapter_ar":"باب تحريم لحوم الحمر الإنسية","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (4227) and Muslim (1939:32).","chapter_en":"The Prohibition of the Meat of Domestic Donkeys","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":5,"content":{"translation":{"en":["Ibn ʿAbbas said: I do not know whether the Messenger of Allah ﷺ forbade it because it was the people’s riding and carrying animals, and he disliked that their mounts and pack animals disappear, or whether he forbade the meat of domestic donkeys on the day of Khaybar."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (4227)، ومسلم (1939: 32)."},{"num":7426,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ:  لَمَّا كَانَ يَوْمُ خَيْبَرَ، جَاءَ جَاءٍ فَقَالَ: يَا رَسُولَ اللَّهِ، أُكِلَتِ الْحُمُرُ، ثُمَّ جَاءَ آخَرُ فَقَالَ: يَا رَسُولَ اللَّهِ، أُفْنِيَتِ الْحُمُرُ، فَأَمَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَبَا طَلْحَةَ فَنَادَى: إِنَّ اللَّهَ وَرَسُولَهُ يَنْهَيَانِكُمْ عَنْ لُحُومِ الْحُمُرِ، فَإِنَّهَا رِجْسٌ أَوْ نَجَِسٌ. قَالَ: فَأُكْفِئَتِ الْقُدُورُ بِمَا فِيهَا."],"takhrij":"متفق عليه: رواه البخاري في الذبائح والصيد (5528)، ومسلم في الصيد والذبائح (1940: 35) كلاهما من طريق محمد بن سيرين، عن أنس فذكره.","grade":"متفق عليه","chapter_ar":"باب تحريم لحوم الحمر الإنسية","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5528) and Muslim (1940:35). The context is from Muslim. Muslim also narrated it (1940:34) from Anas with the wording: “When the Messenger of Allah ﷺ conquered Khaybar, we captured donkeys outside the village, so we cooked from them. Then the caller of the Messenger of Allah ﷺ called out…” the hadith.","chapter_en":"The Prohibition of the Meat of Domestic Donkeys","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":5,"content":{"translation":{"en":["Anas ibn Malik said: On the day of Khaybar, someone came and said: “O Messenger of Allah, the donkeys have been eaten.” Then another came and said: “O Messenger of Allah, the donkeys have been exhausted.” So the Messenger of Allah ﷺ ordered Abu Talhah, and he called out: “Allah and His Messenger forbid you from the meat of donkeys, for it is filth or impurity.” He said: So the pots were overturned with what was in them."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5528)، ومسلم (35:1940). والسياق لمسلم. ورواه مسلم أيضا (34:1940) عن أنس فقال: “لما فتح رسول الله ﷺ خيبر أصبنا حمرا خارجا من القرية، فطبخنا منها، فنادى منادي رسول الله ﷺ …” الحديث."},{"num":7427,"demo":false,"sanad":"","matn":["عَنْ سَلَمَةَ بْنِ الْأَكْوَعِ قَالَ:  خَرَجْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى خَيْبَرَ، ثُمَّ إِنَّ اللَّهَ فَتَحَهَا عَلَيْهِمْ، فَلَمَّا أَمْسَى النَّاسُ الْيَوْمَ الَّذِي فُتِحَتْ عَلَيْهِمْ، أَوْقَدُوا نِيرَانًا كَثِيرَةً، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا هَذِهِ النِّيرَانُ؟ عَلَى أَيِّ شَيْءٍ تُوقِدُونَ؟. قَالُوا: عَلَى لَحْمٍ، قَالَ: عَلَى أَيِّ لَحْمٍ؟ قَالُوا: عَلَى لَحْمِ حُمُرٍ إِنْسِيَّةٍ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَهْرِيقُوهَا وَاكْسِرُوهَا. فَقَالَ: رَجُلٌ: يَا رَسُولَ اللَّهِ، أَوْ نُهَرِيقُهَا وَنَغْسِلُهَا؟ قَالَ: أَوْ ذَاكَ."],"takhrij":"متفق عليه: رواه البخاري في المغازي (4196)، ومسلم في الصيد والذبائح (1802: 33) كلاهما من طريق حاتم بن إسماعيل، عن يزيد بن أبي عُبيد، عن سلمة بن الأكوع قال: فذكره. والسياق لمسلم، وهو عند البخاري بسياق أطول.","grade":"متفق عليه","chapter_ar":"باب تحريم لحوم الحمر الإنسية","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (4196) and Muslim (1802:33). The context is from Muslim, and it is with al-Bukhari in a longer context.","chapter_en":"The Prohibition of the Meat of Domestic Donkeys","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":5,"content":{"translation":{"en":["Salamah ibn al-Akwaʿ said: We went out with the Messenger of Allah ﷺ to Khaybar. Then Allah granted him victory over it. When evening came on the day it was conquered, the people lit many fires. The Messenger of Allah ﷺ said: “What are these fires? What are you lighting them for?” They said: “For meat.” He said: “What meat?” They said: “Meat of domestic donkeys.” The Messenger of Allah ﷺ said: “Spill it out and break the pots.” A man said: “O Messenger of Allah, should we spill it out and wash them?” He said: “Or that.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (4196)، ومسلم (1802: 33). والسياق لمسلم، وهو عند البخاري بسياق أطول."},{"num":7428,"demo":false,"sanad":"","matn":["عن أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ: أَصَبْنَا سَبَايَا يَوْمَ حُنَيْنٍ، فَكُنَّا نَعْزِلُ عَنْهُنَّ، نَلْتَمِسُ أَنْ نُفَادِيَهُنَّ مِنْ أَهْلِهِنَّ، فَقَالَ بَعْضُنَا لِبَعْضٍ: تَفْعَلُونَ هَذَا وَفِيكُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ ائْتُوهُ، فَسَلُوهُ، فَأَتَيْنَاهُ، أَوْ ذَكَرْنَا ذَلِكَ لَهُ، قَالَ: مَا مِنْ كُلِّ الْمَاءِ يَكُونُ الْوَلَدُ، إِذَا قَضَى اللَّهُ أَمْرًا كَانَ وَمَرَرْنَا بِالْقُدُورِ، وَهِيَ تَغْلِي، فَقَالَ لَنَا: مَا هَذَا اللَّحْمُ؟ فَقُلْنَا: لَحْمُ حُمُرٍ. فَقَالَ لَنَا: أَهْلِيَّةٍ أَوْ وَحْشِيَّةٍ؟، فَقُلْنَا لَهُ: بَلْ أَهْلِيَّةٍ. قَالَ: فَقَالَ لَنَا: فَاكْفِئُوهَا. قَالَ: فَكَفَأْنَاهَا، وَإِنَّا لَجِيَاعٌ نَشْتَهِيهِ قَالَ: وَكُنَّا نُؤْمَرُ أَنْ نُوكِئَ الْأَسْقِيَةَ."],"takhrij":"حسن: رواه الإمام أحمد (11778) عن أبي نعيم (هو الفضل بن دكين) ثنا يونس، حدثني أبو الوداك، قال: حدثني أبو سعيد فذكره. ورواه ابن أبي شيبة (24821)، وأبو يعلى (1183) من طريق يونس به بقصة الحمر الأهلية.","grade":"حسن","chapter_ar":"باب تحريم لحوم الحمر الإنسية","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Hasan: Narrated by Imam Ahmad (11778), Ibn Abi Shaybah (24821), and Abu Yaʿla (1183), the latter two with the report concerning the domestic donkeys.","chapter_en":"The Prohibition of the Meat of Domestic Donkeys","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":5,"content":{"translation":{"en":["Abu Saʿid al-Khudri said: We captured female prisoners on the day of Hunayn, and we practiced withdrawal with them, hoping to ransom them back to their families. Some of us said to others: “Are you doing this while the Messenger of Allah ﷺ is among you? Go to him and ask him.” So we came to him, or we mentioned that to him. He said: “Not from every emission does a child come. When Allah decrees a matter, it happens.” We passed by pots that were boiling, and he said to us: “What is this meat?” We said: “Donkey meat.” He said to us: “Domestic or wild?” We said to him: “Rather, domestic.” He said to us: “Overturn them.” He said: So we overturned them, though we were hungry and desired it. He said: And we used to be commanded to tie the mouths of water skins."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (11778)، وابن أبي شيبة (24821)، وأبو يعلى (1183) بقصة الحمر الأهلية."},{"num":7429,"demo":false,"sanad":"","matn":["عن ثَعْلَبَةَ بْنِ الْحَكَمِ قَالَ: أَسَرَنِي أَصْحَابُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَنَا يَوْمَئِذٍ شَابٌّ، فَسَمِعْتُهُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنْهَى عَنِ النُّهْبَةِ، وَأَمَرَ بِالْقُدُورِ، فَأُكْفِئَتْ مِنْ لُحُومِ الْحُمُرِ الْأَهْلِيَّةِ."],"takhrij":"حسن: رواه الطبراني في الكبير (1375)، وأبو نعيم في معرفة الصحابة (1382) من طريق شعبة، عن سماك بن حرب، عن ثعلبة بن الحكم فذكره.","grade":"حسن","chapter_ar":"باب تحريم لحوم الحمر الإنسية","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Kabir (1375) and Abu Nuʿaym in Maʿrifat al-Sahabah (1382).","chapter_en":"The Prohibition of the Meat of Domestic Donkeys","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":5,"content":{"translation":{"en":["Thaʿlabah ibn al-Hakam said: The Companions of the Messenger of Allah ﷺ captured me when I was a young man. I was with them when he forbade plunder and ordered the pots to be overturned because of the meat of domestic donkeys."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (1375)، وأبو نعيم في معرفة الصحابة (1382)."},{"num":7430,"demo":false,"sanad":"","matn":["عن كَعْبِ بن مَالِكٍ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْمُتْعَةِ، وَعَنْ لُحُومِ الْحُمُرِ الْأَهْلِيَّةِ."],"takhrij":"حسن: رواه الطبراني في الكبير (19/ح 131) عن محمد بن عبد الله الحضرمي، ثنا واصل بن عبد الأعلى، ثنا محمد بن فضيل، عن منصور بن دينار، عن الزهري، عن عبد الله بن كعب بن مالك، عن أبيه فذكره.","grade":"حسن","chapter_ar":"باب تحريم لحوم الحمر الإنسية","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Kabir (19/68).","chapter_en":"The Prohibition of the Meat of Domestic Donkeys","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":5,"content":{"translation":{"en":["Kaʿb ibn Malik said: The Messenger of Allah ﷺ forbade temporary marriage and the meat of domestic donkeys."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (19/68)."},{"num":7431,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ: ذَبَحْنَا يَوْمَ خَيْبَرَ الْخَيْلَ، وَالْبِغَالَ، وَالْحَمِيرَ، فَنَهَانَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْبِغَالِ، وَالْحَمِيرِ، وَلَمْ يَنْهَنَا عَنِ الْخَيْلِ."],"takhrij":"صحيح: رواه أبوداود (3789)، وأحمد (14840)، وابن حبان (5272)، والحاكم (4/235) من طرق عن حماد بن سلمة، عن أبي الزبير، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن أكل لحوم البغال","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3789), Ahmad (14840), Ibn Hibban (5272), and al-Hakim (4/235).","chapter_en":"The Prohibition of Eating Mule Meat","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":6,"content":{"translation":{"en":["Jabir ibn ʿAbdullah said: On the day of Khaybar, we slaughtered horses, mules, and donkeys. The Messenger of Allah ﷺ forbade us from mules and donkeys, but he did not forbid us from horses."]}},"tuhfa":{},"full":1,"dr":1,"rep":[7329],"tks":"صحيح: رواه أبو داود (3789)، وأحمد (14840)، وابن حبان (5272)، والحاكم (4/235)."},{"num":7432,"demo":false,"sanad":"","matn":["عَنْ عَطَاءٍ، عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ: كُنَّا نَأْكُلُ لُحُومَ الْخَيْلِ. قُلْتُ: فَالْبِغَالُ قَالَ: لاَ."],"takhrij":"صحيح: رواه النسائي (4333)، وابن ماجه (3197) من طريق عبد الكريم الجزري، عن عطاء، عن جابر فذكره. وإسناده صيح، وعطاء هو ابن أبي رباح.","grade":"صحيح","chapter_ar":"باب النهي عن أكل لحوم البغال","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (4333) and Ibn Majah (3197).","chapter_en":"The Prohibition of Eating Mule Meat","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":6,"content":{"translation":{"en":["ʿAta’ narrated from Jabir: We used to eat horse meat. I said: “Mules?” He said: “No.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه النسائي (4333)، وابن ماجه (3197)."},{"num":7433,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ أَكْلِ الْجَلاَّلَةِ وَأَلْبَانِهَا."],"takhrij":"صحيح: رواه أبوداود (3785)، والترمذي (1824)، وابن ماجه (3189) من طرق عن محمد بن إسحاق، عن ابن أبي نجيح، عن مجاهد، عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب كراهية أكل لحوم الجلالة وشرب ألبانها","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3785), al-Tirmidhi (1824), who graded it hasan, and Ibn Majah (3189).","chapter_en":"The Dislike of Eating the Meat of Animals That Feed on Filth and Drinking Their Milk","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":7,"content":{"translation":{"en":["Ibn ʿUmar said: The Messenger of Allah ﷺ forbade eating animals that feed on filth and drinking their milk."]},"buhuth":{"en":["His statement, “animals that feed on filth,” refers to animals that eat dung and excrement. The word originally refers to droppings, then it was borrowed and used for excrement."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (3785)، والترمذي (1824) وحسنه، وابن ماجه (3189)."},{"num":7434,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ لَبَنِ الْجَلاَّلَةِ."],"takhrij":"صحيح: رواه أبوداود (3786)، والترمذي (1825)، وابن ماجه (1825)، والنسائي (4448)، وأحمد (1989، 2161، 2671) وصحّحه ابن حبان (5399) والحاكم (521) كلهم من طريق قتادة، عن عكرمة، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب كراهية أكل لحوم الجلالة وشرب ألبانها","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3786), al-Tirmidhi (1825), al-Nasa’i (4448), and Ahmad (1989, 2161, 2671). It was authenticated by Ibn Hibban (5399) and al-Hakim (2/102).","chapter_en":"The Dislike of Eating the Meat of Animals That Feed on Filth and Drinking Their Milk","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":7,"content":{"translation":{"en":["Ibn ʿAbbas said: The Prophet ﷺ forbade the milk of animals that feed on filth."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (3786)، والترمذي (1825)، والنسائي (4448)، وأحمد (1989، 2161، 2671)، وصححه ابن حبان (5399)، والحاكم (521)."},{"num":7435,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْمُجَثَّمَةِ وَالْجَلَّالَةِ."],"takhrij":"صحيح: رواه الحاكم (2250)، والبيهقي (19682) من طريق حماد بن سلمة، عن أيوب، عن عكرمة، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب كراهية أكل لحوم الجلالة وشرب ألبانها","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Hakim (2250) and al-Bayhaqi (9/333). Al-Bayhaqi added: “and drinking directly from the mouth of a water skin.”","chapter_en":"The Dislike of Eating the Meat of Animals That Feed on Filth and Drinking Their Milk","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":7,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ forbade animals tied up and shot, and animals that feed on filth."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الحاكم (2250)، والبيهقي (19682)، وزاد البيهقي: “وأن يشرب من في السقاء”."},{"num":7436,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن عمرو قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ خَيْبَرَ عَنْ لُحُومِ الْحُمُرِ الأَهْلِيَّةِ، وَعَنِ الْجَلاَّلَةِ، عَنْ رُكُوبِهَا، وَأَكْلِ لَحْمِهَا."],"takhrij":"حسن: رواه أبو داود (3811)، وأحمد (7039)، والحاكم (2498) من طرق عن وهيب، حدثنا ابن طاوس، عن عمرو بن شعيب، عن أبيه، عن جده فذكره. وإسناده حسن من أجل عمرو بن شعيب، فإنه حسن الحديث.","grade":"حسن","chapter_ar":"باب كراهية أكل لحوم الجلالة وشرب ألبانها","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3811), Ahmad (7039), and al-Hakim (2498).","chapter_en":"The Dislike of Eating the Meat of Animals That Feed on Filth and Drinking Their Milk","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":7,"content":{"translation":{"en":["ʿAbdullah ibn ʿAmr said: On the day of Khaybar, the Messenger of Allah ﷺ forbade the meat of domestic donkeys, and he forbade animals that feed on filth: riding them and eating their meat."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3811)، وأحمد (7039)، والحاكم (2498)."},{"num":7437,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْجَلَّالَةِ أَنْ يُؤْكَلَ لَحْمُهَا، أَوْ يُشْرَبَ لَبَنُهَا."],"takhrij":"حسن: رواه ابن أبي شيبة (24604) عن شبابة (هو ابن سوّار)، ثنا مغيرة بن مسلم، عن أبي الزبير، عن جابر فذكره.","grade":"حسن","chapter_ar":"باب كراهية أكل لحوم الجلالة وشرب ألبانها","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Abi Shaybah (8/147).","chapter_en":"The Dislike of Eating the Meat of Animals That Feed on Filth and Drinking Their Milk","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":7,"content":{"translation":{"en":["Jabir said: The Messenger of Allah ﷺ forbade eating the meat of animals that feed on filth or drinking their milk."]},"buhuth":{"en":["Ibn Hibban said: An animal that feeds on filth is one whose feed is mostly filth. If most of its feed is pure and good things, then it is not considered an animal that feeds on filth. Al-Ihsan (12/221).","Al-Khattabi said: “People differed regarding eating the meat and milk of animals that feed on filth. Abu Hanifah and his companions, al-Shafiʿi, and Ahmad ibn Hanbal disliked that and said: It should not be eaten until it is confined for some days and fed other feed. When its meat becomes good, then there is no harm in eating it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن أبي شيبة (24604)."},{"num":7438,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: إن النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ الْمُجَثَّمَةِ، ولبن الجلاّلة، وَعَنِ الشُّرْبِ مِنْ فِي السِّقَاءِ."],"takhrij":"صحيح: رواه الترمذي (1825)، والنسائي (4448)، وأحمد (2162، 2671)، وابن حبان (5399) كلهم من طريق قتادة، عن عكرمة؟، عن ابن عباس فذكره. ورواه أبو داود من هذا الوجه مختصرا في النهي عن الجلالة، وقد سبق.","grade":"صحيح","chapter_ar":"باب النهي عن أكل المجثَّمة","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (1825), al-Nasa’i (4448), Ahmad (2671, 2162), and Ibn Hibban (5399). Al-Tirmidhi said: “Hasan Sahih.”","chapter_en":"The Prohibition of Eating Animals Tied Up and Shot","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":8,"content":{"translation":{"en":["Ibn ʿAbbas said: The Prophet ﷺ forbade animals tied up and shot, the milk of animals that feed on filth, and drinking directly from the mouth of a water skin."]},"buhuth":{"en":["His statement, “he forbade animals tied up and shot,” refers to any animal set up and shot until it is killed. This usage is common regarding birds, rabbits, and similar animals that crouch or remain attached to the ground, as mentioned in al-Nihayah. If it dies in that manner, eating it is forbidden."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (1825)، والنسائي (4448)، وأحمد (2671، 2162)، وابن حبان (5399). وقال الترمذي: “حديث حسن صحيح”."},{"num":7439,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَرَّمَ يَوْمَ خَيْبَرَ كُلَّ ذِي نَابٍ مِنَ السِّبَاعِ، وَالْمُجَثَّمَةَ، وَالْحِمَارَ الإِنْسِيَّ."],"takhrij":"صحيح: رواه الترمذي (1795)، وأحمد (8789) من طريق زائدة، عن عمرو بن محمد، عن أبي سلمة، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن أكل المجثَّمة","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (1795) and Ahmad (8789). Al-Tirmidhi said: “Hasan Sahih.”","chapter_en":"The Prohibition of Eating Animals Tied Up and Shot","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":8,"content":{"translation":{"en":["Abu Hurayrah narrated that on the day of Khaybar, the Messenger of Allah ﷺ forbade every predator with fangs, animals tied up and shot, and the domestic donkey."]}},"tuhfa":{},"full":1,"dr":1,"rep":[7416],"tks":"صحيح: رواه الترمذي (1795)، وأحمد (8789)، وقال الترمذي: “حسن صحيح”."},{"num":7440,"demo":false,"sanad":"","matn":["عَنْ أَبِي ثَعْلَبَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لاَ تَحِلُّ النُّهْبَى، وَلاَ يَحِلُّ مِنَ السِّبَاعِ كُلُّ ذِي نَابٍ وَلاَ تَحِلُّ الْمُجْثَّمَةُ."],"takhrij":"حسن: رواه النسائي (4326) واللفظ له، وأحمد (17741)، والطبراني في \"الكبير\" (22/216) كلّهم من طريق بقية بن الوليد، عن بحير بن سعد، عن خالد بن معدان، عن جبير بن نفير، عن أبي ثعلبة، فذكره. وسياق أحمد والطبراني أطول.","grade":"حسن","chapter_ar":"باب النهي عن أكل المجثَّمة","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (4326), Ahmad (17741), and al-Tabarani in al-Kabir (22/216).","chapter_en":"The Prohibition of Eating Animals Tied Up and Shot","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":8,"content":{"translation":{"en":["Abu Thaʿlabah al-Khushani said: The Messenger of Allah ﷺ said: “Plunder is not lawful, every predator with fangs is not lawful, and an animal tied up and shot is not lawful.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (4326)، وأحمد (17741)، والطبراني في الكبير (22/216)."},{"num":7441,"demo":false,"sanad":"","matn":["عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللَّهُ عَنْهُمْ أَنَّهُ قَالَ: أَصَبْتُ شَارِفًا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي مَغْنَمٍ يَوْمَ بَدْرٍ، قَالَ: وَأَعْطَانِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شَارِفًا أُخْرَى، فَأَنَخْتُهُمَا يَوْمًا عِنْدَ بَابِ رَجُلٍ مِنَ الأَنْصَارِ، وَأَنَا أُرِيدُ أَنْ أَحْمِلَ عَلَيْهِمَا إِذْخِرًا لأَبِيعَهُ، وَمَعِي صَائِغٌ مِنْ بَنِي قَيْنُقَاعَ، فَأَسْتَعِينَ بِهِ عَلَى وَلِيمَةِ فَاطِمَةَ، وَحَمْزَةُ بْنُ عَبْدِ الْمُطَّلِبِ يَشْرَبُ فِي ذَلِكَ الْبَيْتِ، مَعَهُ قَيْنَةٌ، فَقَالَتْ: أَلاَ يَا حَمْزَ لِلشُّرُفِ النِّوَاءِ. فَثَارَ إِلَيْهِمَا حَمْزَةُ بِالسَّيْفِ، فَجَبَّ أَسْنِمَتَهُمَا، وَبَقَرَ خَوَاصِرَهُمَا، ثُمَّ أَخَذَ مِنْ أَكْبَادِهِمَا. قُلْتُ لاِبْنِ شِهَابٍ وَمِنَ السَّنَامِ قَالَ قَدْ جَبَّ أَسْنِمَتَهُمَا فَذَهَبَ بِهَا. قَالَ ابْنُ شِهَابٍ قَالَ عَلِيٌّ رَضِيَ اللَّهُ عَنْهُ فَنَظَرْتُ إِلَى مَنْظَرٍ أَفْظَعَنِي فَأَتَيْتُ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَعِنْدَهُ زَيْدُ بْنُ حَارِثَةَ فَأَخْبَرْتُهُ الْخَبَرَ فَخَرَجَ وَمَعَهُ زَيْدٌ، فَانْطَلَقْتُ مَعَهُ، فَدَخَلَ عَلَى حَمْزَةَ فَتَغَيَّظَ عَلَيْهِ فَرَفَعَ حَمْزَةُ بَصَرَهُ وَقَالَ هَلْ أَنْتُمْ إِلاَّ عَبِيدٌ لآبَائِي فَرَجَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُقَهْقِرُ حَتَّى خَرَجَ عَنْهُمْ، وَذَلِكَ قَبْلَ تَحْرِيمِ الْخَمْرِ."],"takhrij":"متفق عليه: رواه البخاري في المساقاة (2375)، ومسلم في الأشربة (1979: 1) كلاهما من طريق ابن جريج، حدثني ابن شهاب، عن علي بن حسين بن علي، عن أبيه حسين بن علي، عن علي بن أبي طالب فذكره.","grade":"متفق عليه","chapter_ar":"باب التدرج في تحريم الخمر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2375) and Muslim (1979:1).","chapter_en":"The Gradual Prohibition of Wine","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["ʿAli ibn Abi Talib said: I received an old she-camel along with the Messenger of Allah ﷺ from the spoils on the day of Badr. He said: The Messenger of Allah ﷺ also gave me another old she-camel. One day, I made them kneel at the door of a man from the Helpers, intending to carry sweet rush on them to sell it. With me was a goldsmith from Banu Qaynuqaʿ, so that I could use him to help with the wedding feast of Fatimah. Hamzah ibn ʿAbd al-Muttalib was drinking in that house, and there was a singing girl with him. She said: “O Hamzah, go to the fat old she-camels.” Hamzah rushed to the two camels with a sword, cut off their humps, slit open their flanks, and took from their livers. I said to Ibn Shihab: “And from the hump?” He said: He had cut off their humps and taken them away. Ibn Shihab said: ʿAli said: I looked at a sight that horrified me, so I came to the Prophet of Allah ﷺ while Zayd ibn Harithah was with him, and I informed him of what had happened. He went out with Zayd, and I went with him. He entered upon Hamzah and became angry with him. Hamzah raised his gaze and said: “Are you anything but slaves of my fathers?” The Messenger of Allah ﷺ withdrew, walking backward, until he left them. This was before wine was prohibited."]},"buhuth":{"en":["The word “old she-camel” means an aged she-camel. The phrase “fat old she-camels” refers to plump old she-camels. There was no sin on Hamzah for what he did because he was intoxicated, but he was still liable to compensate for what he destroyed, even if he was intoxicated or insane. In the book of ʿUmar ibn Shabbah, it is mentioned that the Prophet ﷺ made Hamzah pay compensation for the two camels."]},"intro":{"ar":["قال الله تعالى:","(يَسْأَلُونَكَ عَنِ الْخَمْرِ وَالْمَيْسِرِ قُلْ فِيهِمَا إثْمٌ كَبِيرٌ وَمَنَافِعُ لِلنَّاسِ وَإثْمُهُمَا أَكْبَرُ مِن نَفْعِهِمَا) [سورة البقرة: ٢١٩]","وقال تعالى:","(يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَقْرَبُوا الصَّلَاةَ وَأَنْتُمْ سُكَارَىٰ حَتَّىٰ تَعْلَمُوا مَا تَقُولُونَ) [سورة النساء: ٤٣]"],"en":["Allah the Exalted said:","“They ask you about wine and gambling. Say: In them is great sin and benefits for people, but their sin is greater than their benefit.” [Surah al-Baqarah: 219]","And He said:","“O you who believe, do not approach prayer while you are intoxicated until you know what you are saying.” [Surah al-Nisa’: 43]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2375)، ومسلم (1979: 1)."},{"num":7442,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ:  سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ بِالْمَدِينَةِ قَالَ: يَا أَيُّهَا النَّاسُ، إِنَّ اللَّهَ تَعَالَى يُعَرِّضُ بِالْخَمْرِ، وَلَعَلَّ اللَّهَ سَيُنْزِلُ فِيهَا أَمْرًا، فَمَنْ كَانَ عِنْدَهُ مِنْهَا شَيْءٌ، فَلْيَبِعْهُ وَلْيَنْتَفِعْ بِهِ. قَالَ: فَمَا لَبِثْنَا إِلَّا يَسِيرًا، حَتَّى قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ اللَّهَ تَعَالَى حَرَّمَ الْخَمْرَ، فَمَنْ أَدْرَكَتْهُ هَذِهِ الْآيَةُ، وَعِنْدَهُ مِنْهَا شَيْءٌ، فَلَا يَشْرَبْ، وَلَا يَبِعْ. قَالَ: فَاسْتَقْبَلَ النَّاسُ بِمَا كَانَ عِنْدَهُ مِنْهَا فِي طَرِيقِ الْمَدِينَةِ فَسَفَكُوهَا."],"takhrij":"صحيح: رواه مسلم في المساقاة (1578: 67) عن عبيد الله بن عمر القواريري، حدثنا عبد الأعلى بن عبد الأعلى أبو همام، حدثنا سعيد الجريري، عن أبي نضرة، عن أبي سعيد الخدري قال: فذكره.","grade":"صحيح","chapter_ar":"باب التدرج في تحريم الخمر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1578:67).","chapter_en":"The Gradual Prohibition of Wine","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Abu Saʿid al-Khudri said: I heard the Messenger of Allah ﷺ delivering a sermon in Madinah. He said: “O people! Allah the Exalted is alluding to wine, and perhaps Allah will soon reveal a ruling concerning it. Whoever has some of it should sell it and benefit from it.” He said: We remained only a short while until the Prophet ﷺ said: “Allah the Exalted has forbidden wine. Whoever this verse reaches while he has any of it should neither drink it nor sell it.” He said: The people then came out with whatever wine they had into the roads of Madinah and poured it away."]}},"tuhfa":{},"full":1,"rep":[5785],"tks":"صحيح: رواه مسلم (1578: 67)."},{"num":7443,"demo":false,"sanad":"","matn":["عَنْ عُمَرَ بْنِ الْخَطَّابِ، قَالَ: لَمَّا نَزَلَ تَحْرِيمُ الْخَمْرِ، قَالَ عُمَرُ: اللَّهُمَّ بَيِّنْ لَنَا فِي الْخَمْرِ بَيَانًا شِفَاءً، فَنَزَلَتِ الآيَةُ الَّتِي فِي الْبَقَرَةِ: ﴿يَسْأَلُونَكَ عَنِ الْخَمْرِ وَالْمَيْسِرِ قُلْ فِيهِمَا إِثْمٌ كَبِيرٌ﴾ [سورة البقرة: 219] } الآيَةَ قَالَ: فَدُعِيَ عُمَرُ، فَقُرِئَتْ عَلَيْهِ قَالَ: اللَّهُمَّ بَيِّنْ لَنَا فِي الْخَمْرِ بَيَانًا شِفَاءً فَنَزَلَتِ الآيَةُ الَّتِي فِي النِّسَاءِ ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا لاَ تَقْرَبُوا الصَّلاَةَ وَأَنْتُمْ سُكَارَى﴾ [سورة النساء: 43] } فَكَانَ مُنَادِي رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا أُقِيمَتِ الصَّلاَةُ، يُنَادِي: أَلاَ لاَ يَقْرَبَنَّ الصَّلاَةَ سَكْرَانُ، فَدُعِيَ عُمَرُ فَقُرِئَتْ عَلَيْهِ، فَقَالَ: اللَّهُمَّ بَيِّنْ لَنَا فِي الْخَمْرِ بَيَانًا شِفَاءً، فَنَزَلَتْ هَذِهِ الآيَةُ { فَهَلْ أَنْتُمْ مُنْتَهُونَ } قَالَ عُمَرُ: انْتَهَيْنَا."],"takhrij":"صحيح: رواه أبو داود (3670)، والترمذي (3049)، والنسائي (5540)، وأحمد (378)، والحاكم (4/143)، والضياء المقدسي في المختارة (256) كلهم من طرق عن إسرائيل بن يونس بن أبي إسحاق السبيعي، عن أبي إسحاق، عن أبي ميسرة عمرو بن شرحبيل، عن عمر فذكره.","grade":"صحيح","chapter_ar":"باب التدرج في تحريم الخمر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3670), al-Tirmidhi (3049), al-Nasa’i (5540), Ahmad (378), al-Hakim (4/143), and al-Diya’ al-Maqdisi in al-Mukhtarah (256).","chapter_en":"The Gradual Prohibition of Wine","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["ʿUmar ibn al-Khattab said: When the prohibition of wine was revealed, ʿUmar said: “O Allah, give us a clear and decisive explanation concerning wine.” Then the verse in al-Baqarah was revealed: “They ask you about wine and gambling. Say: In them is sin…” the verse. He said: ʿUmar was called and it was recited to him. He said: “O Allah, give us a clear and decisive explanation concerning wine.” Then the verse in al-Nisa’ was revealed: “O you who believe, do not approach prayer while you are intoxicated.” When the caller of the Messenger of Allah ﷺ announced the establishment of prayer, he would call out: “Let no intoxicated person come near the prayer.” Then ʿUmar was called and it was recited to him. He said: “O Allah, give us a clear and decisive explanation concerning wine.” Then this verse was revealed: “So will you then desist?” [Surah al-Ma’idah: 91] ʿUmar said: “We have desisted.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (3670)، والترمذي (3049)، والنسائي (5540)، وأحمد (378)، والحاكم (4/143)، والضياء المقدسي في المختارة (256)."},{"num":7444,"demo":false,"sanad":"","matn":["عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ، أَنَّ رَجُلاً، مِنَ الأَنْصَارِ دَعَاهُ، وَعَبْدَ الرَّحْمَنِ بْنَ عَوْفٍ فَسَقَاهُمَا قَبْلَ أَنْ تُحَرَّمَ الْخَمْرُ، فَأَمَّهُمْ عَلِيٌّ فِي الْمَغْرِبِ، فَقَرَأَ ﴿قُلْ يَا أَيُّهَا الْكَافِرُونَ﴾ فَخَلَطَ فِيهَا فَنَزَلَتْ: ﴿لَا تَقْرَبُوا الصَّلَاةَ وَأَنْتُمْ سُكَارَى حَتَّى تَعْلَمُوا مَا تَقُولُونَ﴾. [سورة النساء: 43]."],"takhrij":"صحيح: رواه أبو داود (3671)، والترمذي (3026)، والحاكم (2/207) كلهم من طريق عطاء بن السائب، عن أبي عبد الرحمن السلمي، عن علي بن أبي طالب فذكره.","grade":"صحيح","chapter_ar":"باب التدرج في تحريم الخمر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3671), al-Tirmidhi (3026), and al-Hakim (2/207).","chapter_en":"The Gradual Prohibition of Wine","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["ʿAli ibn Abi Talib narrated that a man from the Helpers invited him and ʿAbd al-Rahman ibn ʿAwf and served them drink before wine was prohibited. ʿAli led them in the sunset prayer and recited: “Say: O disbelievers,” but mixed up the recitation. Then this was revealed: “Do not approach prayer while you are intoxicated until you know what you are saying.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (3671)، والترمذي (3026)، والحاكم (2/207)."},{"num":7445,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: كُنْتُ أَسْقِي أَبَا عُبَيْدَةَ بْنَ الْجَرَّاحِ، وَأَبَا طَلْحَةَ الأَنْصَارِيَّ، وأبي بْنَ كَعْبٍ شَرَابًا مِنْ فَضِيخٍ وتمر، قَالَ: فَجَاءَهُمْ آتٍ فَقَالَ: إِنَّ الْخَمْرَ قَدْ حُرِّمَتْ، فَقَالَ أَبُو طَلْحَةَ: يَا أَنَسُ! قمْ إِلَى هَذِهِ الْجِرَارِ فَاكْسِرْهَا، قَالَ: فَقُمْتُ إِلَى مِهْرَاسٍ لَنَا فَضَرَبْتُهَا بِأَسْفَلِهِ حَتَّى تَكَسَّرَتْ."],"takhrij":"متفق عليه: رواه مالك في الأشربة (13) عن إسحاق بن عبد الله بن أبي طلحة، عن أنس بن مالك فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في تحريم الخمر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (13), al-Bukhari (5582), and Muslim (1980:9).","chapter_en":"What Has Been Reported Concerning the Prohibition of Wine","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Anas ibn Malik said: I was serving Abu ʿUbaydah ibn al-Jarrah, Abu Talhah al-Ansari, and Ubayy ibn Kaʿb a drink made from unripe dates and dates. He said: Then someone came to them and said: “Wine has been prohibited.” Abu Talhah said: “O Anas, go to these jars and break them.” He said: So I went to a mortar we had and struck them with its lower part until they broke."]},"intro":{"ar":["قال اللّٰه تعالى:","(يَا أَيُّهَا الَّذِينَ آمَنُوا إِنَّمَا الْخَمْرُ وَالْمَيْسِرُ وَالْأَنْصَابُ وَالْأَزْلَامُ رِجْسٌ مِنْ عَمَلِ الشَّيْطَانِ فَاجْتَنِبُوهُ لَعَلَّكُمْ تُفْلِحُونَ ۝ إِنَّمَا يُرِيدُ الشَّيْطَانُ أَنْ يُوقِعَ بَيْنَكُمُ الْعَدَاوَةَ وَالْبَغْضَاءَ فِي الْخَمْرِ وَالْمَيْسِرِ وَيَصُدَّكُمْ عَنْ ذِكْرِ اللَّهِ وَعَنِ الصَّلَاةِ فَهَلْ أَنْتُمْ مُنْتَهُونَ) [المائدة: ٩٠-٩١]"],"en":["Allah the Exalted said:","“O you who believe, wine, gambling, stone altars, and divining arrows are only filth from the work of Satan, so avoid it so that you may succeed. Satan only wants to cause enmity and hatred between you through wine and gambling and to prevent you from the remembrance of Allah and from prayer. So will you then desist?” [al-Ma’idah: 90–91]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (13)، والبخاري (5582)، ومسلم (9:1980)."},{"num":7446,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ الرَّحْمَنِ بْنِ وَعْلَةَ السَّبَئِيِّ (مِنْ أَهْلِ مِصْرَ)  أَنَّهُ سَأَلَ عَبْدَ اللَّهِ بْنَ عَبَّاسٍ عَمَّا يُعْصَرُ مِنَ الْعِنَبِ، فَقَالَ ابْنُ عَبَّاسٍ: إِنَّ رَجُلًا أَهْدَى لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَاوِيَةَ خَمْرٍ، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: هَلْ عَلِمْتَ أَنَّ اللَّهَ قَدْ حَرَّمَهَا؟ قَالَ: لَا. فَسَارَّ إِنْسَانًا، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: بِمَ سَارَرْتَهُ؟ فَقَالَ: أَمَرْتُهُ بِبَيْعِهَا، فَقَالَ: إِنَّ الَّذِي حَرَّمَ شُرْبَهَا حَرَّمَ بَيْعَهَا. قَالَ: فَفَتَحَ الْمَزَادَةَ حَتَّى ذَهَبَ مَا فِيهَا."],"takhrij":"صحيح: رواه مسلم في المساقاة والمزارعة (1579: 68) عن سويد بن سعيد، حدثنا حفص بن ميسرة، عن زيد بن أسلم، عن عبد الرحمن بن وعلة فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في تحريم الخمر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1579:68).","chapter_en":"What Has Been Reported Concerning the Prohibition of Wine","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["ʿAbd al-Rahman ibn Waʿlah, a man from Egypt, asked ʿAbdullah ibn ʿAbbas about what is pressed from grapes. Ibn ʿAbbas said: A man gifted the Messenger of Allah ﷺ a container of wine. The Messenger of Allah ﷺ said to him: “Did you know that Allah has forbidden it?” He said: “No.” Then he whispered to another person. The Messenger of Allah ﷺ said to him: “What did you whisper to him?” He said: “I told him to sell it.” He said: “The One who forbade drinking it also forbade selling it.” He said: So he opened the container until everything in it flowed away."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1579: 68)."},{"num":7447,"demo":false,"sanad":"","matn":["عن سَعْدِ بن أَبِي وَقَّاصٍ قَالَ: أَتَيْتُ عَلَى نَفَرٍ مِنَ الْأَنْصَارِ وَالْمُهَاجِرِينَ، فَقَالُوا: تَعَالَ نُطْعِمْكَ وَنَسْقِيكَ خَمْرًا - وَذَلِكَ قَبْلَ أَنْ تُحَرَّمَ الْخَمْرُ، قَالَ: فَأَتَيْتُهُمْ فِي حَشٍّ، - وَالْحَشُّ: الْبُسْتَانُ - فَإِذَا رَأْسُ جَزُورٍ مَشْوِيٌّ عِنْدَهُمْ، وَزِقٌّ مِنْ خَمْرٍ. قَالَ: فَأَكَلْتُ وَشَرِبْتُ مَعَهُمْ. قَالَ: فَذَكَرْتُ الْأَنْصَارَ وَالْمُهَاجِرِينَ عِنْدَهُمْ، فَقُلْتُ: الْمُهَاجِرُونَ خَيْرٌ مِنَ الْأَنْصَارِ! قَالَ: فَأَخَذَ رَجُلٌ أَحَدَ لَحْيَيِ الرَّأْسِ، فَضَرَبَنِي بِهِ فَجَرَحَ بِأَنْفِي، فَأَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَخْبَرْتُهُ، فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ فِيَّ - يَعْنِي نَفْسَهُ شَأْنَ الْخَمْرِ: ﴿إِنَّمَا الْخَمْرُ وَالْمَيْسِرُ وَالأَنْصَابُ وَالأَزْلامُ رِجْسٌ مِنْ عَمَلِ الشَّيْطَانِ."],"takhrij":"صحيح: رواه مسلم في فضائل الصحابة (1748) من طريق الحسن بن موسى، ثنا وهير، ثنا سماك بن حرب، ثنا مصعب بن سعد، عن أبيه فذكره في حديث طويل.","grade":"صحيح","chapter_ar":"باب ما جاء في تحريم الخمر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim in the Virtues of the Companions (1748) through al-Hasan ibn Musa, from Zuhayr, from Simak ibn Harb, from Musʿab ibn Saʿd, from his father, who mentioned it in a long hadith.","chapter_en":"What Has Been Reported Concerning the Prohibition of Wine","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Saʿd ibn Abi Waqqas said: “… I came upon a group of the Helpers and the Emigrants, and they said: ‘Come, we will feed you and give you wine to drink.’ This was before wine was prohibited. He said: I came to them in a garden, and there was the roasted head of a slaughtered camel with them and a skin of wine. He said: I ate and drank with them. He said: I mentioned the Helpers and the Emigrants in their presence, and I said: ‘The Emigrants are better than the Helpers.’ He said: A man took one of the jawbones of the head and struck me with it, wounding my nose. I came to the Messenger of Allah ﷺ and informed him. Then Allah, the Mighty and Majestic, revealed concerning me — meaning himself — regarding wine: ‘Wine, gambling, stone altars, and divining arrows are only filth from the work of Satan.’”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1748)."},{"num":7448,"demo":false,"sanad":"","matn":["عن ابن عباس قال: يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَقْرَبُوا الصَّلَاةَ وَأَنْتُمْ سُكَارَى و يَسْأَلُونَكَ عَنِ الْخَمْرِ وَالْمَيْسِرِ قُلْ فِيهِمَا إِثْمٌ كَبِيرٌ وَمَنَافِعُ لِلنَّاسِ نسختهما التي في المائدة إِنَّمَا الْخَمْرُ وَالْمَيْسِرُ وَالْأَنْصَابُ."],"takhrij":"حسن: رواه أبو داود (3672) عن أحمد بن محمد المروزي، ثنا علي بن حسين، عن أبيه، عن يزيد النحوي، عن عكرمة، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في تحريم الخمر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3672).","chapter_en":"What Has Been Reported Concerning the Prohibition of Wine","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Ibn ʿAbbas said: The verses “O you who believe, do not approach prayer while you are intoxicated” and “They ask you about wine and gambling. Say: In them is great sin and benefits for people” were abrogated by the verse in al-Ma’idah: “Wine, gambling, and stone altars…”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3672)."},{"num":7449,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: لَمَّا حُرِّمَتِ الْخَمْرِ مَشَى أَصْحَابُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعْضُهُمْ إِلَى بَعْضٍ وَقَالُوا: حُرِّمَتِ الْخَمْرُ وَجُعِلَتْ عِدْلًا لِلشِّرْكِ."],"takhrij":"حسن: رواه الطبراني في الكبير (12399)، والحاكم (7227) كلاهما من طريق أبي شهاب الحناط، ثنا الحسن بن عمرو الفقيمي، عن طلحة بن مصرّف، عن سعيد بن جبير، عن ابن عباس فذكره. وإسناده حسن، من أجل أبي شهاب الحناط واسمه عبد ربه بن نافع الكناني فإنه حسن الحديث.","grade":"حسن","chapter_ar":"باب ما جاء في تحريم الخمر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Kabir (12399) and al-Hakim (7227).","chapter_en":"What Has Been Reported Concerning the Prohibition of Wine","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Ibn ʿAbbas said: When wine was prohibited, the Companions of the Messenger of Allah ﷺ went to one another and said: “Wine has been prohibited and has been made equal to associating partners with Allah.”"]},"buhuth":{"en":["Their statement, “made equal to associating partners with Allah,” refers to the saying of Allah the Exalted: “O you who believe, wine, gambling, stone altars, and divining arrows are only filth from the work of Satan.” [al-Ma’idah: 90]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (12399)، والحاكم (7227). وقولهم: “وجعلت عدلا للشرك” يعنون قوله تعالى: (يا أيها الذين آمنوا إنما الخمر والميسر والأنصاب والأزلام رجس من عمل الشيطان) [المائدة: 90]."},{"num":7450,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ عَامَ الْفَتْحِ، وَهُوَ بِمَكَّةَ إِنَّ اللَّهَ وَرَسُولَهُ حَرَّمَ بَيْعَ الْخَمْرِ، وَالْمَيْتَةِ، وَالْخِنْزِيرِ، وَالأَصْنَامِ."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2236)، ومسلم في المساقاة (1581) كلاهما عن قتيبة بن سعيد، حدثنا ليث، عن يزيد بن أبي حبيب، عن عطاء بن أبي رباح، عن جابر بن عبد الله فذكره مطولا.","grade":"متفق عليه","chapter_ar":"باب تأكيد تحريم الخمر يوم فتح مكة","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2236) and Muslim (1581).","chapter_en":"The Confirmation of the Prohibition of Wine on the Day of the Conquest of Makkah","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Jabir ibn ʿAbdullah heard the Messenger of Allah ﷺ say in the year of the conquest while he was in Makkah: “Allah and His Messenger have forbidden the sale of wine, carrion, swine, and idols.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2236)، ومسلم (1581)."},{"num":7451,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ كُنْتُ سَاقِيَ الْقَوْمِ فِي مَنْزِلِ أَبِي طَلْحَةَ، وَكَانَ خَمْرُهُمْ يَوْمَئِذٍ الْفَضِيخَ، فَأَمَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُنَادِيًا يُنَادِي: أَلاَ إِنَّ الْخَمْرَ قَدْ حُرِّمَتْ. قَالَ: فَقَالَ لِي أَبُو طَلْحَةَ: اخْرُجْ فَأَهْرِقْهَا، فَخَرَجْتُ فَهَرَقْتُهَا، فَجَرَتْ فِي سِكَكِ الْمَدِينَةِ، فَقَالَ بَعْضُ الْقَوْمِ: قَدْ قُتِلَ قَوْمٌ، وَهْىَ فِي بُطُونِهِمْ. فَأَنْزَلَ اللَّهُ ﴿لَيْسَ عَلَى الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ جُنَاحٌ فِيمَا طَعِمُوا﴾. [سورة المائدة: 93]} الآيَةَ."],"takhrij":"متفق عليه: رواه البخاري في المظالم (2464)، ومسلم في الأشربة (1980: 3) كلاهما من طريق حماد بن زيد، عن ثابت، عن أنس فذكره.","grade":"متفق عليه","chapter_ar":"باب العفو عن الذين شربوا الخمر وماتوا قبل تحريمها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2464) and Muslim (1980:3).","chapter_en":"Pardon for Those Who Drank Wine and Died Before Its Prohibition","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Anas said: I was the one serving drink to the people in the house of Abu Talhah, and their wine that day was made from unripe dates. The Messenger of Allah ﷺ ordered a caller to announce: “Indeed, wine has been prohibited.” He said: Abu Talhah said to me: “Go out and pour it away.” So I went out and poured it away, and it flowed through the streets of Madinah. Some people said: “Some people were killed while it was in their bellies.” Then Allah revealed: “There is no blame upon those who believed and did righteous deeds for what they consumed.” [al-Ma’idah: 93]"]}},"tuhfa":{},"full":1,"rep":[12283],"tks":"متفق عليه: رواه البخاري (2464)، ومسلم (1980: 3)."},{"num":7452,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ قَالَ: اصْطَبَحَ نَاسٌ الْخَمْرُ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثُمَّ قَتَلُوا شُهَدَاءَ يَوْمِ أُحُدٍ، فَقَالَتِ الْيَهُودُ: فَقَدْ مَاتَ بَعْضُ الَّذِينَ قُتِلُوا وَهِيَ فِي بُطُونِهِمْ، فَأَنْزَلَ اللَّهُ تَعَالَى: ﴿لَيْسَ عَلَى الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ جُنَاحٌ فِيمَا طَعِمُوا﴾. [المائدة: ٩٣]."],"takhrij":"صحيح: رواه البزار –كما في تفسير ابن كثير (3/186)- عن  أحمد بن عبيدة، ثنا سفيان، عن عمرو بن دينار، سمع جابرا فذكره.","grade":"صحيح","chapter_ar":"باب العفو عن الذين شربوا الخمر وماتوا قبل تحريمها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bazzar, as in Tafsir Ibn Kathir (3/186).","chapter_en":"Pardon for Those Who Drank Wine and Died Before Its Prohibition","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Jabir ibn ʿAbdullah said: Some of the Companions of the Prophet ﷺ drank wine in the morning and then were killed as martyrs on the day of Uhud. The Jews said: “Some of those who were killed died while it was in their bellies.” Then Allah the Exalted revealed: “There is no blame upon those who believed and did righteous deeds for what they consumed.” [al-Ma’idah: 93]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البزار - كما في تفسير ابن كثير (3/186)."},{"num":7453,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: نَزَلَ تَحْرِيمُ الْخَمْرِ فِي قَبِيلَتَيْنِ مِنْ قَبَائِلِ الْأَنْصَارِ، شَرِبُوا حَتَّى إِذَا نَهِلُوا، عَبَثَ بَعْضُهُمْ بِبَعْضٍ، فَلَمَّا صَحَوْا جَعَلَ الرَّجُلُ يَرَى الْأَثَرَ بِوَجْهِهِ وَبِرَأْسِهِ وَبِلِحْيَتِهِ، فَيَقُولُ: قَدْ فَعَلَ بِي هَذَا أَخِي - وَكَانُوا إِخْوَةً لَيْسَ فِي قُلُوبِهِمْ ضَغَائِنُ، - وَاللهِ لَوْ كَانَ رَبِّي رَؤُوفًا رَحِيمًا، مَا فَعَلَ بِي هَذَا، فَوَقَعَتْ فِي قُلُوبِهِمُ الضَّغَائِنُ، فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ﴿إِنَّمَا الْخَمْرُ وَالْمَيْسِرُ﴾ [المائدة: ٩٠] إِلَى قَوْلِهِ: ﴿فَهَلْ أَنْتُمْ مُنْتَهُونَ﴾ [المائدة: ٩١] فَقَالَ نَاسٌ: هِيَ رِجْسٌ وَهِيَ فِي بَطْنِ فُلَانٍ قُتِلَ يَوْمَ بَدْرٍ، وَفُلَانٍ قُتِلَ يَوْمَ أُحُدٍ، فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ﴿لَيْسَ عَلَى الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ جُنَاحٌ فِيمَا طَعِمُوا إِذَا مَا اتَّقَوْا وَآمَنُوا وَعَمِلُوا الصَّالِحَاتِ﴾"],"takhrij":"حسن: رواه النسائي في السنن الكبرى (11151)، والحاكم (7219)، والطبراني في الكبير (12459)، والضياء في المختارة (370) كلهم من طريق ربيعة بن كلثوم بن جبير، عن أبيه عن سعيد بن جبير، عن عبد الله بن عباس فذكره.","grade":"حسن","chapter_ar":"باب العفو عن الذين شربوا الخمر وماتوا قبل تحريمها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i in al-Sunan al-Kubra (11151), al-Hakim (2/141–142), al-Tabarani in al-Kabir (12/56), and al-Diya’ in al-Mukhtarah (10/341).","chapter_en":"Pardon for Those Who Drank Wine and Died Before Its Prohibition","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Ibn ʿAbbas said: The prohibition of wine was revealed concerning two tribes from the Helpers who drank until, when they had drunk their fill, some of them began mistreating others. When they sobered up, a man would see marks on his face, head, or beard and say: “My brother did this to me.” They had been brothers with no grudges in their hearts. “By Allah, if he had been kind and merciful to me, he would not have done this to me.” So grudges fell into their hearts. Then Allah, the Mighty and Majestic, revealed: “Wine and gambling…” until His saying: “So will you then desist?” Some people said: “It is filth, and it was in the stomach of so-and-so who was killed on the day of Badr, and so-and-so who was killed on the day of Uhud.” Then Allah, the Mighty and Majestic, revealed: “There is no blame upon those who believed and did righteous deeds for what they consumed, so long as they were mindful, believed, and did righteous deeds.” [al-Ma’idah: 93]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي في السنن الكبرى (11151)، والحاكم (7219)، والطبراني في الكبير (12459)، والضياء في المختارة (370)."},{"num":7454,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ شَرِبَ الْخَمْرَ فِي الدُّنْيَا، ثُمَّ لَمْ يَتُبْ مِنْهَا، حُرِمَهَا فِي الآخِرَةِ."],"takhrij":"متفق عليه: رواه مالك في الأشربة (11) عن نافع، عن عبد الله بن عمر فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الترهيب من شرب الخمر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (11), al-Bukhari (5575), and Muslim (2003:76).","chapter_en":"What Has Been Reported Concerning the Warning Against Drinking Wine","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Ibn ʿUmar narrated that the Messenger of Allah ﷺ said: “Whoever drinks wine in this world and then does not repent from it will be deprived of it in the Hereafter.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[7004],"tks":"متفق عليه: رواه مالك (11)، والبخاري (5575)، ومسلم (76:2003)."},{"num":7455,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ:  أَنَّ رَجُلًا قَدِمَ مِنْ جَيْشَانَ، وَجَيْشَانُ مِنَ الْيَمَنِ، فَسَأَلَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ شَرَابٍ، يَشْرَبُونَهُ بِأَرْضِهِمْ مِنَ الذُّرَةِ يُقَالُ لَهُ: الْمِزْرُ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَوَمُسْكِرٌ هُوَ؟. قَالَ: نَعَمْ، قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: كُلُّ مُسْكِرٍ حَرَامٌ، إِنَّ عَلَى اللَّهِ عَزَّ وَجَلَّ عَهْدًا لِمَنْ يَشْرَبُ الْمُسْكِرَ أَنْ يَسْقِيَهُ مِنْ طِينَةِ الْخَبَالِ. قَالُوا: يَا رَسُولَ اللَّهِ، وَمَا طِينَةُ الْخَبَالِ؟ قَالَ: عَرَقُ أَهْلِ النَّارِ، أَوْ عُصَارَةُ أَهْلِ النَّارِ."],"takhrij":"صحيح: رواه مسلم في الأشربة (2002) عن قتيبة بن سعيد، حدثنا عبد العزيز الدراوردي، عن عُمارة بن غزية، عن أبي الزبير، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الترهيب من شرب الخمر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2002).","chapter_en":"What Has Been Reported Concerning the Warning Against Drinking Wine","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Jabir narrated that a man came from Jayshan — and Jayshan is in Yemen — and asked the Prophet ﷺ about a drink they made in their land from millet, called mizr. The Prophet ﷺ said: “Is it intoxicating?” He said: “Yes.” The Messenger of Allah ﷺ said: “Every intoxicant is forbidden. Allah, the Mighty and Majestic, has made a covenant concerning whoever drinks intoxicants that He will give him to drink from the mud of corruption.” They said: “O Messenger of Allah, what is the mud of corruption?” He said: “The sweat of the people of the Fire, or the discharge of the people of the Fire.”"]}},"tuhfa":{},"full":1,"rep":[7005,16466],"tks":"صحيح: رواه مسلم (2002)."},{"num":7456,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ شَرِبَ الْخَمْرَ وَسَكِرَ لَمْ تُقْبَلْ لَهُ صَلاَةٌ أَرْبَعِينَ صَبَاحًا. وَإِنْ مَاتَ دَخَلَ النَّارَ. فَإِنْ تَابَ تَابَ اللَّهُ عَلَيْهِ. وَإِنْ عَادَ فَشَرِبَ فَسَكِرَ لَمْ تُقْبَلْ لَهُ صَلاَةٌ أَرْبَعِينَ صَبَاحًا. فَإِنْ مَاتَ دَخَلَ النَّارَ. فَإِنْ تَابَ تَابَ اللَّهُ عَلَيْهِ. وَإِنْ عَادَ فَشَرِبَ فَسَكِرَ لَمْ تُقْبَلْ لَهُ صَلاَةٌ أَرْبَعِينَ صَبَاحًا. فَإِنْ مَاتَ دَخَلَ النَّارَ. فَإِنْ تَابَ تَابَ اللَّهُ عَلَيْهِ. وَإِنْ عَادَ كَانَ حَقًّا عَلَى اللَّهِ أَنْ يَسْقِيَهُ مِنْ رَدْغَةِ الْخَبَالِ يَوْمَ الْقِيَامَةِ. قَالُوا: يَا رَسُولَ اللَّهِ وَمَا رَدْغَةُ الْخَبَالِ؟ قَالَ: عُصَارَةُ أَهْلِ النَّارِ."],"takhrij":"صحيح: رواه ابن ماجه (4377)، وصحّحه ابن حبان (5357) كلاهما من طريق الوليد بن مسلم، ثنا الأوزاعي، عن ربيعة بن يزيد، عن عبد الله بن الديلمي، عن عبد الله بن عمرو فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الترهيب من شرب الخمر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Majah (3377), and authenticated by Ibn Hibban (5357).","chapter_en":"What Has Been Reported Concerning the Warning Against Drinking Wine","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["ʿAbdullah ibn ʿAmr ibn al-ʿAs said: The Messenger of Allah ﷺ said: “Whoever drinks wine and becomes intoxicated, his prayer will not be accepted for forty mornings. If he dies, he will enter the Fire. If he repents, Allah will accept his repentance. If he returns and drinks and becomes intoxicated, his prayer will not be accepted for forty mornings. If he dies, he will enter the Fire. If he repents, Allah will accept his repentance. If he returns and drinks and becomes intoxicated, his prayer will not be accepted for forty mornings. If he dies, he will enter the Fire. If he repents, Allah will accept his repentance. If he returns again, it will be binding upon Allah to give him drink from the mire of corruption on the Day of Resurrection.” They said: “O Messenger of Allah, what is the mire of corruption?” He said: “The discharge of the people of the Fire.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[7006],"tks":"صحيح: رواه ابن ماجه (4377)، وصححه ابن حبان (5357)."},{"num":7457,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو قَالَ: قَالَ رَسُولُ اللَّهِصَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  -: مَنْ مَاتَ مِنْ أُمَّتِي وَهُوَ يَشْرَبُ الْخَمْرَ، حَرَّمَهَا اللَّهُ عَلَيْهِ فِي الاَخرة، وَمَنْ مَاتَ مِنْ أُمَّتِي وَهُوَ يَلْبَسُ الْحَرِيرَ حَرَّمَ اللَّهُ عَلَيْهِ لُبْسَهُ فِي الْآخِرَةِ."],"takhrij":"صحيح: رواه أبو يعلى الموصلي –كما في إتحاف الخيرة المهرة للبوصيري (5480)- من طريق عبد الأعلى بن عبد الأعلى، عن سعيد الجريري، عن ميمون بن أستاذ، عن عبد الله بن عمرو فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الترهيب من شرب الخمر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Yaʿla al-Mawsili, as in Ithaf al-Khiyarah al-Maharah by al-Busiri (5480).","chapter_en":"What Has Been Reported Concerning the Warning Against Drinking Wine","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["ʿAbdullah ibn ʿAmr ibn al-ʿAs said: The Messenger of Allah ﷺ said: “Whoever from my nation dies while drinking wine, Allah will forbid it to him in the Hereafter. And whoever from my nation dies while wearing silk, Allah will forbid him from wearing it in the Hereafter.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو يعلى الموصلي - كما في إتحاف الخيرة المهرة للبوصيري (5480)."},{"num":7458,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: مَنْ تَرَكَ الصَّلَاةَ سُكْرًا مَرَّةً وَاحِدَةً، فَكَأَنَّمَا كَانَتْ لَهُ الدُّنْيَا وَمَا عَلَيْهَا فَسُلِبَهَا، وَمَنْ تَرَكَ الصَّلَاةَ سُكْرًا أَرْبَعَ مَرَّاتٍ، كَانَ حَقًّا عَلَى اللَّهِ عَزَّ وَجَلَّ أَنْ يَسْقِيَهُ مِنْ طِينَةِ الْخَبَالِ، قِيلَ: وَمَا طِينَةُ الْخَبَالِ يَا رَسُولَ اللَّهِ؟ قَالَ: عُصَارَةُ أَهْلِ جَهَنَّمَ."],"takhrij":"حسن: رواه أحمد (6659) والحاكم (7233)، والبيهقي في السنن (1/389، 8/287)، وفي شعب الإيمان (5193) كلهم من طريق ابن وهب، حدثني عمرو بن الحارث، عن عمرو بن شعيب، عن أبيه، عن عبد الله بن عمرو فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الترهيب من شرب الخمر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (6659), al-Hakim (7233), al-Bayhaqi (8/287, 1/389), and in Shuʿab al-Iman (5193).","chapter_en":"What Has Been Reported Concerning the Warning Against Drinking Wine","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["ʿAbdullah ibn ʿAmr ibn al-ʿAs narrated from the Messenger of Allah ﷺ that he said: “Whoever misses prayer because of intoxication one time, it is as though he had the world and everything in it, then it was taken away from him. Whoever misses prayer because of intoxication four times, it becomes binding upon Allah, the Mighty and Majestic, to give him drink from the mud of corruption.” It was said: “What is the mud of corruption, O Messenger of Allah?” He said: “The discharge of the people of Hell.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[16467],"tks":"حسن: رواه أحمد (6659)، والحاكم (7233)، والبيهقي (8/287، 1/389)، وفي شعب الإيمان (5193)."},{"num":7459,"demo":false,"sanad":"","matn":["عن طلق بن عَلِيٍّأَنَّهُ كَانَ عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَالِسًا، فَجَاءَ صُحَارُ عَبَدِ الْقَيْسِ فَقَالَ: يَا رَسُولَ اللَّهِ، مَا تَرَى فِي شَرَابٍ نَصْنَعُهُ بِأَرْضِنَا مِنْ ثِمَارِنَا؟ فَأَعْرَضَ عَنْهُ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، حَتَّى سَأَلَهُ ثَلَاثَ مَرَّاتٍ، حَتَّى صَلَّى، وَلَمَّا قَضَى صَلَاتَهُ، قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنِ السَّائِلُ عَنِ الْمُسْكِرِ؟ لَا تَشْرَبْهُ، وَلَا تَسْقِهِ أَخَاكَ الْمُسْلِمَ، فَوَالَّذِي نَفْسِي بِيَدِهِ، - أَوْ فَوَالَّذِي يُحْلَفُ بِهِ، - لَا يَشْرَبُهُ رَجُلٌ ابْتِغَاءَ لَذَّةِ سُكْرِهِ، فَيَسْقِيهِ اللَّهُ الْخَمْرَ يَوْمَ الْقِيَامَةِ."],"takhrij":"حسن: رواه أحمد في مسنده -الملحق المستدرك- (24009: 32)، وابن أبي شيبة في المصنف (23743)، والطبراني في الكبير (8259) كلهم من طريق ملازم بن عمرو، ثنا سِراج بن عقبة، عن عمته خلدة بنت طلق، عن أبيها طلق بن علي فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الترهيب من شرب الخمر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad in his Musnad, the supplementary appendix (24009:32), Ibn Abi Shaybah (7/460), and al-Tabarani in al-Kabir (8259).","chapter_en":"What Has Been Reported Concerning the Warning Against Drinking Wine","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Talq ibn ʿAli was sitting with the Messenger of Allah ﷺ when Suhar of ʿAbd al-Qays came and said: “O Messenger of Allah, what do you say about a drink we make in our land from our fruits?” The Prophet of Allah ﷺ turned away from him until he asked him three times. Then he stood and prayed. When he finished his prayer, the Prophet ﷺ said: “Where is the one who asked about the intoxicant? Do not drink it, and do not give it to your Muslim brother to drink. By the One in Whose Hand is my soul — or by the One by Whom oaths are sworn — no man drinks it seeking the pleasure of its intoxication and then is given wine by Allah on the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد في مسنده - الملحق المستدرك - (24009:32)، وابن أبي شيبة (23743)، والطبراني في الكبير (8259)."},{"num":7460,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عُمَرَ أَنَّ أَبَا بَكْرٍ الصِّدِّيقَ وَعُمَرَ بْنَ الْخَطَّابِ وَنَاسًا مِنْ أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَلَسُوا بَعْدَ وَفَاةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، فَذَكَرُوا أَعْظَمَ الْكَبَائِرِ، فَلَمْ يَكُنْ عِنْدَهُمْ فِيهَا علمٌ، فَأَرْسَلُونِي إِلَى عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ أَسْأَلَهُ عَنْ ذَلِكَ، فَأَخْبَرَنِي: أَنَّ أَعْظَمَ الْكَبَائِرِ شُرْبَ الْخَمْرِ، فَأَتَيْتُهُمْ فَأَخْبَرْتُهُمْ، فَأَنْكَرُوا ذَلِكَ، وَوَثَبُوا إِلَيْهِ جَمِيعًا، فَأَخْبَرَهُمْ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ مَلِكًا مِنْ بَنِي إِسْرَائِيلَ أجبر رَجُلًا، فَخَيَّرَهُ بَيْنَ أَنْ يَشْرَبَ الْخَمْرَ، أَوْ يَقْتُلَ صَبِيًّا، أَوْ يَزْنِيَ، أَوْ يَأْكُلَ لَحْمَ الْخِنْزِيرِ، أَوْ يَقْتُلُوهُ إِنْ أَبَى، فَاخْتَارَ أَنَّهُ يَشْرَبُ الْخَمْرَ، وَأَنَّهُ لَمَّا شَرِبَ لَمْ يَمْتَنِعْ مِنْ شَيْءٍ أرادوهُ مِنْهُ، وَأَنَّ رَسُولَ اللَّهِ قَالَ لَنَا حِينَئِذٍ: مَا مِنْ أَحَدٍ يَشْرَبُهَا فَتُقْبَلُ لَهُ صَلَاةٌ أَرْبَعِينَ لَيْلَةً وَلَا يَمُوتُ وَفِي مَثَانَتِهِ مِنْهَا شَيْءٌ إِلَّا حُرِّمَتْ عَلَيْهِ الْجَنَّةُ، وَإِنْ مَاتَ فِي الْأَرْبَعِينَ مَاتَ مِيتَةً جَاهِلِيَّةً."],"takhrij":"حسن: رواه الطبراني في الاوسط (363) عن أحمد بن رشدين، ثنا سعيد بن أبي مريم، أخبرنا عبد العزيز بن محمد الدراوردي، ثنا داود بن صالح، عن سالم بن عبد الله بن عمر قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الترهيب من شرب الخمر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Awsat (363).","chapter_en":"What Has Been Reported Concerning the Warning Against Drinking Wine","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar narrated that Abu Bakr al-Siddiq, ʿUmar ibn al-Khattab, and some of the Companions of the Messenger of Allah ﷺ sat together after the death of the Messenger of Allah ﷺ and discussed the greatest major sins. They did not have knowledge concerning it, so they sent me to ʿAbdullah ibn ʿAmr ibn al-ʿAs to ask him about it. He informed me that the greatest of the major sins is drinking wine. I came to them and informed them, but they rejected that and all rushed to him. He informed them that the Messenger of Allah ﷺ said: “A king from the Children of Israel forced a man and gave him a choice between drinking wine, killing a child, committing fornication, eating pork, or being killed if he refused. He chose to drink wine, and when he drank, he did not refrain from anything they wanted from him.” And the Messenger of Allah ﷺ said to us at that time: “No one drinks it and then has his prayer accepted for forty nights; and no one dies while there is any of it in his bladder except that Paradise is forbidden to him. If he dies during the forty days, he dies a death of pre-Islamic ignorance.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الأوسط (363)."},{"num":7461,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عُمَرَ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ شَرِبَ الْخَمْرَ لَمْ تُقْبَلْ لَهُ صَلَاةٌ أَرْبَعِينَ لَيْلَةً، فَإِنْ تَابَ، تَابَ اللَّهُ عَلَيْهِ، وإن شَرِبَهَا الثانية لَمْ تُقْبَلْ لَهُ صَلَاةٌ أَرْبَعِينَ لَيْلَةً، فَإِنْ تَابَ، تَابَ اللَّهُ عَلَيْهِ، فَإِنْ شَرِبَهَا الثالثة لَمْ تُقْبَلْ لَهُ صَلَاةٌ أَرْبَعِينَ لَيْلَةً، فَإِنْ تَابَ، تَابَ اللَّهُ عَلَيْهِ، فَإِنْ شَرِبَهَا الرَّابِعَةَ لَمْ تُقْبَلْ لَهُ صَلَاةٌ أَرْبَعِينَ لَيْلَةً فَإِنْ تَابَ لَمْ يَتُبِ اللَّهُ عَلَيْهِ، وَكَانَ حَقًّا عَلَى اللَّهِ أَنْ يَسْقِيَهُ مِنْ طِينَةِ الْخَبَالِ. قِيلَ: وَمَا طِينَةُ الْخَبَالِ؟ قَالَ: صَدِيدُ أَهْلِ النَّارِ."],"takhrij":"صحيح: رواه البيهقي في الشعب (5191) واللفظ له، والطبراني في الكبير (12/392) كلاهما من طريق حماد بن زيد، حدثنا عطاء بن السائب، عن عبد الله بن عبيد بن عمير، أن ابن عمر قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الترهيب من شرب الخمر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bayhaqi in al-Shuʿab (5191), and the wording is his, and by al-Tabarani in al-Kabir (12/392).","chapter_en":"What Has Been Reported Concerning the Warning Against Drinking Wine","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Ibn ʿUmar said: I heard the Messenger of Allah ﷺ say: “Whoever drinks wine, his prayer will not be accepted for forty nights. If he repents, Allah will accept his repentance. If he drinks it a second time, his prayer will not be accepted for forty nights. If he repents, Allah will accept his repentance. If he drinks it a third time, his prayer will not be accepted for forty nights. If he repents, Allah will accept his repentance. If he drinks it a fourth time, his prayer will not be accepted for forty nights; and if he repents, Allah will not accept his repentance. It will be binding upon Allah to give him drink from the mud of corruption.” It was said: “What is the mud of corruption?” He said: “The pus of the people of the Fire.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البيهقي في الشعب (5191) واللفظ له، والطبراني في الكبير (12/392)."},{"num":7462,"demo":false,"sanad":"","matn":["عَنْ أَبِي الدَّرْدَاءِ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لاَ يَدْخُلُ الْجَنَّةَ مُدْمِنُ خَمْرٍ."],"takhrij":"حسن: رواه ابن ماجه (3376) عن هشام بن عمار، ثنا سليمان بن عتبة، قال: حدثني يونس بن ميسرة بن حلبس، عن أبي إدريس، عن أبي الدرداء فذكره.","grade":"حسن","chapter_ar":"باب ما جاء من الوعيد في مُدمن الخمر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (3376), and Ahmad (27484) also narrated it and added:","chapter_en":"What Has Been Reported of Threat Concerning the One Addicted to Wine","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["Abu al-Darda’ narrated from the Prophet ﷺ that he said: “One who is addicted to wine will not enter Paradise.”"]},"buhuth":{"en":["“Nor one who is undutiful to parents, nor one who denies divine decree.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (3376)، ورواه أحمد (27484)، وزاد:."},{"num":7463,"demo":false,"sanad":"","matn":["عَنْ أَبِي الدَّرْدَاءِ، قَالَ: أَوْصَانِي خَلِيلِي: صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ تَشْرَبِ الْخَمْرَ، فَإِنَّهَا مِفْتَاحُ كُلِّ شَرٍّ."],"takhrij":"حسن: رواه ابن ماجه (3371) من طريق راشد أبي محمد الحماني، عن شهر بن حوشب، عن أم الدرداء، عن أبي الدرداء قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في أن الخمر مفتاح كل شرّ","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (3371) and al-Bukhari in al-Adab al-Mufrad (18).","chapter_en":"What Has Been Reported That Wine Is the Key to Every Evil","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Abu al-Darda’ said: My close friend advised me: “Do not drink wine, for it is the key to every evil.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (3371)، والبخاري في الأدب المفرد (18)."},{"num":7464,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اجْتَنِبُوا الْخَمْرَ فَإِنَّهَا مِفْتَاحُ كُلِّ شَرٍّ."],"takhrij":"حسن: رواه الحاكم (7231) وعنه البيهقي في شعب الإيمان (5199) من طريق نعيم بن حماد، ثنا عبد العزيز بن محمد الدراوردي، عن عمرو بن أبي عمرو، عن عكرمة، عن ابن عباس قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في أن الخمر مفتاح كل شرّ","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Hakim (7231) and al-Bayhaqi in Shuʿab al-Iman (5199).","chapter_en":"What Has Been Reported That Wine Is the Key to Every Evil","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Ibn ʿAbbas said: The Messenger of Allah ﷺ said: “Avoid wine, for it is the key to every evil.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الحاكم (7231) والبيهقي في شعب الإيمان (5199)."},{"num":7465,"demo":false,"sanad":"","matn":["عن أَبِي عَامِرٍ –أَوْ أَبِي مَالِكٍ- أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: لَيَكُونَنَّ مِنْ أُمَّتِي أَقْوَامٌ يَسْتَحِلُّونَ الْحِرَ وَالْحَرِيرَ وَالْخَمْرَ وَالْمَعَازِفَ، وَلَيَنْزِلَنَّ أَقْوَامٌ إِلَى جَنْبِ عَلَمٍ يَرُوحُ عَلَيْهِمْ بِسَارِحَةٍ لَهُمْ، يَأْتِيهِمْ ـ يَعْنِي الْفَقِيرَ ـ لِحَاجَةٍ فَيَقُولُوا: ارْجِعْ إِلَيْنَا غَدًا. فَيُبَيِّتُهُمُ اللَّهُ، وَيَضَعُ الْعَلَمَ، وَيَمْسَخُ آخَرِينَ قِرَدَةً وَخَنَازِيرَ إِلَى يَوْمِ الْقِيَامَةِ."],"takhrij":"صحيح: رواه البخاري في الأشربة (5590) قال: وقال هشام بن عمار، حدثنا صدقة بن خالد، حدثنا عبد الرحمن بن يزيد بن جابر، حدثنا عطية بن قيس الكلأبي، حدثنا عبد الرحمن بن غنم الأشعري قال: حدثني أبو عامر-أو أبو مالك- الأشعري والله ما كذبني سمع النبي صلى الله عليه وسلم يقول: فذكره.","grade":"صحيح","chapter_ar":"باب فيمن يستحل الخمر ويسميها بغير اسمها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5590) and Ibn Hibban (6754).","chapter_en":"Concerning Those Who Declare Wine Lawful and Call It by Another Name","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Abu ʿAmir — or Abu Malik — heard the Prophet ﷺ say: “There will surely be people from my nation who will declare lawful unlawful sexual relations, silk, wine, and musical instruments. Some people will settle beside a mountain, and their shepherd will come to them in the evening with their grazing animals. A poor person will come to them for a need, and they will say: ‘Come back to us tomorrow.’ Then Allah will destroy them during the night, bring down the mountain, and transform others into monkeys and swine until the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[15491,15918],"tks":"صحيح: رواه البخاري (5590)، وابن حبان (6754)."},{"num":7466,"demo":false,"sanad":"","matn":["عَنْ رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، عَنْ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يشرب ناسٌ مِنْ أُمَّتِي الْخَمْرَ يُسَمُّونَهَا بِغَيْرِ اسْمِهَا."],"takhrij":"صحيح: رواه النسائي (5658)، وأحمد (18073) من طريق شعبة، عن أبي بكر بن حفص، قال: سمعت ابن محيريز يحدث عن رجل من أصحاب النبي صلى الله عليه وسلم فذكره. وإسناده صحيح، وابن محيريز هو: عبد الله بن محيريز بن جنادة.","grade":"صحيح","chapter_ar":"باب فيمن يستحل الخمر ويسميها بغير اسمها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (5658) and Ahmad (18073).","chapter_en":"Concerning Those Who Declare Wine Lawful and Call It by Another Name","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["A man from the Companions of the Prophet ﷺ narrated from the Prophet ﷺ that he said: “People from my nation will drink wine, calling it by a name other than its name.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه النسائي (5658)، وأحمد (18073)."},{"num":7467,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَقُولُ: إِنَّأَوَّلَ مَا يُكْفَأُ قَالَ زَيْدٌ: يَعْنِي: فِي الْإِسْلَامَ كَمَا يُكْفَأُ الْإِنَاءُ يَعْنِي: الْخَمْرِ، فَقِيلَ: كَيْفَ يَا رَسُولَ اللَّهِ وَقَدْ بَيَّنَ اللَّهُ فِيهَا مَا بَيَّنَ؟ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يُسَمُّونَهَا بِغَيْرِ اسْمِهَا فَيَسْتَحِلُّونَهَا."],"takhrij":"حسن: رواه الدارمي (2145) عن زيد بن يحيى، ثنا محمد بن راشد، عن أبي وهب الكلاعي، عن القاسم بن محمد، عن عائشة فذكرته.","grade":"حسن","chapter_ar":"باب فيمن يستحل الخمر ويسميها بغير اسمها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Darimi (2145).","chapter_en":"Concerning Those Who Declare Wine Lawful and Call It by Another Name","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["ʿA’ishah said: I heard the Messenger of Allah ﷺ say: “The first thing to be overturned — meaning in Islam — as a vessel is overturned, is wine.” It was said: “How, O Messenger of Allah, when Allah has made clear about it what He has made clear?” The Messenger of Allah ﷺ said: “They will call it by a name other than its name and thereby declare it lawful.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الدارمي (2145)."},{"num":7468,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عَبَّاسٍ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ أُمَّتِي يَشْرَبُونَ الْخَمْرَ فِي آخِرِ الزَّمَانِ يُسَمُّونَهَا بِغَيْرِ اسْمِهَا."],"takhrij":"حسن: رواه الطبراني في الكبير (11228) عن الحسن بن العباس الرازي، ثنا إسماعيل بن توبة القزويني، ثنا عفان بن سيار، ثنا أبو عامر الخزّاز، عن ابن أبي مليكة، عن ابن عباس قال: فذكره.","grade":"حسن","chapter_ar":"باب فيمن يستحل الخمر ويسميها بغير اسمها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Kabir (11/118).","chapter_en":"Concerning Those Who Declare Wine Lawful and Call It by Another Name","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Ibn ʿAbbas narrated that the Messenger of Allah ﷺ said: “My nation will drink wine near the end of time, calling it by a name other than its name.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (11228)."},{"num":7469,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  الْخَمْرُ مِنْ هَاتَيْنِ الشَّجَرَتَيْنِ، النَّخْلَةِ، وَالْعِنَبَةِ."],"takhrij":"صحيح: رواه مسلم في الأشربة (1985: 13) عن زهير بن حرب، ثنا إسماعيل بن إبراهيم، أخبرنا الحجاج بن أبي عثمان، حدثني يحيى بن أبي كثير، أن أبا كثير حدثه، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب تفسير الخمر التي نزل تحريمها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1985:13).","chapter_en":"Explanation of the Wine Concerning Which the Prohibition Was Revealed","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ said: “Wine is from these two trees: the palm tree and the grapevine.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1985: 13)."},{"num":7470,"demo":false,"sanad":"","matn":["عَنْ أنس قَالَ: كُنْتُ قَائِمًا عَلَى الحي أَسْقِيهِمْ -عُمُومَتِي وَأَنَا أَصْغَرُهُمُ- الْفَضِيخَ، فَقِيلَ: حُرِّمَتِ الْخَمْرُ، فَقَالُوا: أَكْفِئْهَا فَكَفَأْتُهَا، قُلْتُ لأَنَسٍ: مَا شَرَابُهُمْ؟ قَالَ: رُطب وَبُسْرٌ. فَقَالَ أَبُو بَكْرِ بْنُ أَنَسٍ: وَكَانَتْ خَمْرَهُمْ، فَلَمْ يُنْكِرْ أَنَسٌ. وَحَدَّثَنِي بَعْضُ أَصْحَابِي: أَنَّهُ سَمِعَ أنس بْنُ مَالِكٍ يَقُولُ: كَانَتْ خَمْرَهُمْ يَوْمَئِذٍ."],"takhrij":"متفق عليه: رواه البخاري في الأشربة (5583)، ومسلم في الأشربة (1980: 6) كلاهما من طريق المعتمر بن سليمان، عن أبيه، قال: سمعت أنسا قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب تفسير الخمر التي نزل تحريمها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5583) and Muslim (1980:6).","chapter_en":"Explanation of the Wine Concerning Which the Prohibition Was Revealed","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Anas said: I was standing over the people, serving them drink — my paternal uncles, while I was the youngest of them — serving them a drink made from unripe dates. It was said: “Wine has been prohibited.” They said: “Overturn it,” so I overturned it. I said to Anas: “What was their drink?” He said: “Fresh dates and unripe dates.” Abu Bakr ibn Anas said: “And that was their wine,” and Anas did not object. One of my companions narrated to me that he heard Anas ibn Malik say: “That was their wine on that day.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (5583)، ومسلم (1980: 6)."},{"num":7471,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، قَالَ: حُرِّمَتْ عَلَيْنَا الْخَمْرُ حِينَ حُرِّمَتْ، وَمَا نَجِدُ ـ يَعْنِي بِالْمَدِينَةِ ـ خَمْرَ الأَعْنَابِ إِلاَّ قَلِيلاً، وَعَامَّةُ خَمْرِنَا الْبُسْرُ وَالتَّمْرُ."],"takhrij":"متفق عليه: رواه البخاري في الأشربة (5580) من طريق يونس، عن ثابت البناني، عن أنس فذكره. ورواه مسلم في الأشربة (1980: 3) من طريق حماد بن زيد، أخبرنا ثابت به، وفيه قصة تحريم الخمر، لكن جاء بلفظ: \"وما شرابهم إلا الفضيخ: البسر والتمر\"، ولم يذكر العنب.","grade":"متفق عليه","chapter_ar":"باب تفسير الخمر التي نزل تحريمها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5580) and Muslim (1980:3).","chapter_en":"Explanation of the Wine Concerning Which the Prohibition Was Revealed","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Anas said: Wine was prohibited to us when it was prohibited, and we did not find — meaning in Madinah — much grape wine. Most of our wine was from unripe dates and dates."]},"buhuth":{"en":["His statement, “most of our wine was from unripe dates”: unripe dates are one of the stages of dates. First it is spathe, then early green fruit, then immature dates, then unripe dates, then fresh dates, then dried dates."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5580)، ومسلم (1980: 3)."},{"num":7472,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ يَقُولُ:  لَقَدْ أَنْزَلَ اللَّهُ الْآيَةَ الَّتِي حَرَّمَ اللَّهُ فِيهَا الْخَمْرَ، وَمَا بِالْمَدِينَةِ شَرَابٌ يُشْرَبُ إِلَّا مِنْ تَمْرٍ."],"takhrij":"صحيح: رواه مسلم في الأشربة (1982) عن محمد بن المثنى، ثنا أبو بكر الحنفي، ثنا عبد الحميد بن جعفر، حدثني أبي أنه سمع أنس بن مالك يقول: فذكره.","grade":"صحيح","chapter_ar":"باب تفسير الخمر التي نزل تحريمها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1982).","chapter_en":"Explanation of the Wine Concerning Which the Prohibition Was Revealed","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Anas said: Allah revealed the verse in which Allah prohibited wine, and in Madinah there was no drink being consumed except that which was made from dates."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1982)."},{"num":7473,"demo":false,"sanad":"","matn":["عَنْ نَافِعٍ، عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: لَقَدْ حُرِّمَتِ الْخَمْرُ، وَمَا بِالْمَدِينَةِ مِنْهَا شَىْءٌ."],"takhrij":"صحيح: رواه البخاري في الأشربة (5579) عن الحسن بن صباح، حدثنا محمد بن سابق، حدثنا مالك بن مغول، عن نافع، عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب تفسير الخمر التي نزل تحريمها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5579).","chapter_en":"Explanation of the Wine Concerning Which the Prohibition Was Revealed","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Ibn ʿUmar said: Wine was prohibited while there was none of it in Madinah."]},"buhuth":{"en":["His statement, “there was none of it in Madinah,” means grapes."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (5579). وقوله: “وما بالمدينة منها شيء” يعني العنب."},{"num":7474,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: خَطَبَ عُمَرُ عَلَى مِنْبَرِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنَّهُ قَدْ نَزَلَ تَحْرِيمُ الْخَمْرِ، وَهْىَ مِنْ خَمْسَةِ أَشْيَاءَ، الْعِنَبِ، وَالتَّمْرِ، وَالْحِنْطَةِ، وَالشَّعِيرِ، وَالْعَسَلِ، وَالْخَمْرُ مَا خَامَرَ الْعَقْلَ، وَثَلاَثٌ وَدِدْتُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمْ يُفَارِقْنَا حَتَّى يَعْهَدَ إِلَيْنَا عَهْدًا الْجَدُّ وَالْكَلاَلَةُ وَأَبْوَابٌ مِنْ أَبْوَابِ الرِّبَا.","قَالَ: قُلْتُ: يَا أَبَا عَمْرٍو: فَشَىْءٌ يُصْنَعُ بِالسِّنْدِ مِنَ الأرز؟ قَالَ: ذَاكَ لَمْ يَكُنْ عَلَى عَهْدِ النَّبِيِّ صلى الله عليه وسلم، أَوْ قَالَ: عَلَى عَهْدِ عُمَرَ.","وفي رواية: \"الزبيب\" مكان \"العنب\"."],"takhrij":"متفق عليه: رواه البخاري في الأشربة (5588)، ومسلم في التفسير (3032: 32) كلاهما من طريق أبي حيان التيمي، عن الشعبي، عن ابن عمر قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب تفسير الخمر التي نزل تحريمها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5588) and Muslim (3032:32).","chapter_en":"Explanation of the Wine Concerning Which the Prohibition Was Revealed","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Ibn ʿUmar said: ʿUmar delivered a sermon on the pulpit of the Messenger of Allah ﷺ and said: The prohibition of wine has been revealed, and it is from five things: grapes, dates, wheat, barley, and honey. Wine is whatever clouds the mind. There are three matters concerning which I wished the Messenger of Allah ﷺ had not left us until he had given us a clear instruction: the grandfather, the inheritance of one who leaves neither parent nor child, and some categories of usury. He said: I said: “O Abu ʿAmr, what about something made in Sind from rice?” He said: “That did not exist during the time of the Prophet ﷺ,” or he said: “during the time of ʿUmar.” In another narration: “raisins” appears instead of “grapes.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5588)، ومسلم (3032: 32)."},{"num":7475,"demo":false,"sanad":"","matn":["عَنِ النُّعْمَانِ بْنِ بَشِيرٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ مِنَ الْعِنَبِ خَمْرًا، وَإِنَّ مِنَ التَّمْرِ خَمْرًا، وَإِنَّ مِنَ الْعَسَلِ خَمْرًا، وَإِنَّ مِنَ الْبُرِّ خَمْرًا، وَإِنَّ مِنَ الشَّعِيرِ خَمْرًا."],"takhrij":"حسن: رواه أبو داود (3676)، والترمذي (1872، 1873)، وأحمد (18350) كلهم من طرق عن إسرائيل، عن إبراهيم بن المهاجر، عن عامر الشعبي، عن النعمان بن بشير قال: فذكره.","grade":"حسن","chapter_ar":"باب تفسير الخمر التي نزل تحريمها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3676), al-Tirmidhi (1873, 1872), Ahmad (18350), and Abu Dawud (3677).","chapter_en":"Explanation of the Wine Concerning Which the Prohibition Was Revealed","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Al-Nuʿman ibn Bashir said: The Messenger of Allah ﷺ said: “From grapes there is wine, from dates there is wine, from honey there is wine, from wheat there is wine, and from barley there is wine.”"]},"buhuth":{"en":["As for the meaning of the hadith, it is not that wine only comes from these five specific things. Rather, they were mentioned specifically because they were known at that time. So everything with the same meaning, such as millet, barley-like grains, fruit, and juice, takes the same ruling. Al-Khattabi stated this."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3676)، والترمذي (1873، 1872)، وأحمد (18350)، وأبو داود (3677)."},{"num":7476,"demo":false,"sanad":"","matn":["عن علي بن أَبِي طَالِبٍ نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ خَاتِمِ الذَّهَبِ، وَعَنِ الْقَسِّيِّ، وَعَنِ الْمِيثَرَةِ، وَعَنِ الْجَعَةِ."],"takhrij":"حسن: رواه الترمذي (2808)، وأبوداود (4051)، والنسائي (5169)، وابن ماجه (3654)، وابن أبي شيبة (8/110)، وأحمد (1102) كلهم من حديث أبي الأحوص، عن أبي إسحاق، عن هبيرة، عن علي قال: فذكره.","grade":"حسن","chapter_ar":"باب تفسير الخمر التي نزل تحريمها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (2808), Abu Dawud (4051), al-Nasa’i (8/165), Ibn Majah (3654), Ibn Abi Shaybah (8/110), and Ahmad (1102).","chapter_en":"Explanation of the Wine Concerning Which the Prohibition Was Revealed","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["ʿAli ibn Abi Talib said: The Messenger of Allah ﷺ forbade a gold ring, qassi garments, the maytharah, and jiʿah."]},"buhuth":{"en":["His statement, “maytharah,” with kasrah on the letter mim and fathah on the letter tha’, refers to a stuffed cushion placed over the saddle of a camel beneath the rider. It was the habit of arrogant people, but if it is intended to provide comfort for the weak, then there is no harm in that. His statement, “jiʿah,” with kasrah on the letter jim and sukun on the letter ʿayn, is an intoxicating drink made from barley."]}},"tuhfa":{},"full":1,"dr":1,"rep":[15517],"tks":"حسن: رواه الترمذي (2808)، وأبو داود (4051)، والنسائي (5169)، وابن ماجه (3654)، وابن أبي شيبة (8/110)، وأحمد (1102)."},{"num":7477,"demo":false,"sanad":"","matn":["عَنْ مَعْقِلَ بْنَ يَسَارٍ قَالَ: حُرِّمَتِ الْخَمْرُ وَنَحْنُ نَشْرَبُ الْفَضِيخَ، فَجَعَلْتُ أُهْرِيقُهَا وَأَقُولُ هَذَا آخِرُ الْعَهْدِ بِالْخَمْرِ."],"takhrij":"حسن: رواه أحمد في الأشربة (184) والطبراني في الكبير (20/ح 505)كلاهما من طريق جامع بن مطر الحبطي، ثنا معاوية بن قرة، قال: قال معقل بن يسار فذكره.","grade":"حسن","chapter_ar":"باب تفسير الخمر التي نزل تحريمها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad in al-Ashribah (184) and al-Tabarani in al-Kabir (20/218). The wording is from al-Tabarani.","chapter_en":"Explanation of the Wine Concerning Which the Prohibition Was Revealed","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Maʿqil ibn Yasar said: Wine was prohibited while we were drinking a drink made from unripe dates. I began pouring it away and saying: “This is the last time with wine.”"]},"buhuth":{"en":["His statement, “the drink made from unripe dates,” refers to a drink made from unripe dates without being heated by fire."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد في الأشربة (184)، والطبراني في الكبير (20/ح 505). واللفظ للطبراني."},{"num":7478,"demo":false,"sanad":"","matn":["عن أَبِي عبد اللَّهِ الجسري قَالَ: سَأَلْتُ مَعْقِلَ بْنَ يَسَارٍ عَنِ الشَّرَابِ، فَقَالَ: كُنَّا بِالْمَدِينَةِ، وَكَانَتْ كَثِيرَةَ التَّمْرِ، فَحَرَّمَ عَلَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْفَضِيخَ، وَأَتَاهُ رَجُلٌ فَسَأَلَهُ عَنْ أُمٍّ لَهُ عَجُوزٍ كَبِيرَةٍ، أَيَسْقِيهَا النَّبِيذَ، فَإِنَّهَا لَا تَأْكُلُ الطَّعَامَ؟ فَنَهَاهُ مَعْقِلٌ."],"takhrij":"صحيح: رواه أحمد (20299)، والطبراني في الكبير (20/217، 224) كلاهما من طريق المثنى بن عوف، ثنا أبو عبد الله الجسري به فذكره.","grade":"صحيح","chapter_ar":"باب تفسير الخمر التي نزل تحريمها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (20299) and al-Tabarani in al-Kabir (20/217, 224).","chapter_en":"Explanation of the Wine Concerning Which the Prohibition Was Revealed","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Abu ʿAbdullah al-Jusari said: I asked Maʿqil ibn Yasar about drink. He said: We were in Madinah, and it had many dates, so the Messenger of Allah ﷺ forbade us from the drink made from unripe dates. A man came to him and asked him about an elderly mother of his: should he give her date drink to drink, since she did not eat food? Maʿqil forbade him from that."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (20299)، والطبراني في الكبير (20/217، 224)."},{"num":7479,"demo":false,"sanad":"","matn":["عَنْ أُمِّ حَبِيبَةَ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَنَّ نَاسًا مِنْ أَهْلِ الْيَمَنِ قَدِمُوا عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَعَلَّمَهُمُ الصَّلَاةَ وَالسُّنَنَ وَالْفَرَائِضَ، فَقَالُوا: يَا رَسُولَ اللَّهِ، إِنَّ لَنَا شَرَابًا نَصْنَعُهُ مِنَ الْقَمْحِ وَالشَّعِيرِ، فَقَالَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الْغُبَيْرَاءُ؟ قَالُوا: نَعَمْ، قَالَ: لَا تَطْعَمُوهُ، فَلَمَّا كَانَ بَعْدَ يَوْمَيْنِ ذَكَرُوهُمَا لَهُ أَيْضًا، فَقَالَ: الْغُبَيْرَاءُ؟ قَالُوا: نَعَمْ، قَالَ: لَا تَطْعَمُوهُ، فَلَمَّا أَرَادُوا أَنْ يَنْطَلِقُوا سَأَلُوهُ عَنْهُ، فَقَالَ: الْغُبَيْرَاءُ؟ قَالُوا: نَعَمْ، قَالَ: فَلَا تَطْعَمُوهُ."],"takhrij":"حسن: رواه ابن حبان (5367) عن ابن قتيبة، ثنا يزيد بن مَوْهب، ثنا ابن وهب، أخبرني عمرو بن الحارث، أن أبا السمح حدثه، أن عمر بن الحكم حدثه، عن أم حبيبة فذكرته.","grade":"حسن","chapter_ar":"باب تفسير الخمر التي نزل تحريمها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Hibban (5367).","chapter_en":"Explanation of the Wine Concerning Which the Prohibition Was Revealed","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Umm Habibah, the wife of the Prophet ﷺ, narrated that some people from Yemen came to the Messenger of Allah ﷺ, and he taught them the prayer, the prophetic practices, and the obligations. They said: “O Messenger of Allah, we have a drink that we make from wheat and barley.” He said: “Al-Ghubayra’?” They said: “Yes.” He said: “Do not consume it.” After two days, they mentioned the two to him again, and he said: “Al-Ghubayra’?” They said: “Yes.” He said: “Do not consume it.” When they wanted to depart, they asked him about it again, and he said: “Al-Ghubayra’?” They said: “Yes.” He said: “Then do not consume it.”"]},"buhuth":{"en":["His statement, “al-Ghubayra’,” with the letter ghayn pronounced with dammah, refers to a type of wine made from millet, and it was among the wines of Abyssinia. Malik said: I asked Zayd ibn Aslam about it, and he said: “It is intoxicating drink.” In another wording: “It is al-sukarkah.” Al-Ashribah (10)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن حبان (5367). وقوله: “الغبيراء”: بضم الغين، وهو نوع من الخمر يتخذ من الذرة، وهي من خمر الحبشة. قال مالك: سألت زيد بن أسلم عنه فقال: أسكركة، وفي لفظ: هي السكركة. الأشربة (10)."},{"num":7480,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عَبَّاسٍ قَالَ: كَانَتْ خمرتنا يَوْمَئِذٍ الْفَضِيخَ، وَحُرِّمَتْ يَوْمَ حُرِّمَتْ وَمَا هِيَ إِلَّا فَضِيخُكُمْ."],"takhrij":"حسن: رواه الطبراني في الكبير (11985) عن موسى بن هارون، ثنا أحمد بن حنبل، ثنا يحيى بن سعيد، عن عثمان الشحّام، عن عكرمة، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب تفسير الخمر التي نزل تحريمها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Kabir (11/351).","chapter_en":"Explanation of the Wine Concerning Which the Prohibition Was Revealed","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Ibn ʿAbbas said: Our wine on that day was the drink made from unripe dates, and it was prohibited on the day it was prohibited, and it was nothing but your drink made from unripe dates."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (11985)."},{"num":7481,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ أَبِي الْهُذَيْلِ قَالَ: كَانَ عَبْدُ اللَّهِ يَحْلِفُ بِاللَّهِ إِنَّ الَّتِي أَمَرَ بِهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ حُرِّمَتِ الْخَمْرُ أَنْ تُكسر دَنَانُهُ، وَأَنْ تكفأ لمن التَّمْرِ وَالزَّبِيبِ."],"takhrij":"صحيح: رواه الدارقطني (4652)، وأحمد بن منيع في مسنده –كما في المطالب العالية (1825)- من طريق حسين بن محمد، ثنا شيبان، عن أشعث بن أبي الشعثاء، عن عبد الله بن أبي الهذيل فذكره.","grade":"صحيح","chapter_ar":"باب تفسير الخمر التي نزل تحريمها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Daraqutni (4652) and Ahmad ibn Maniʿ in his Musnad, as in al-Matalib al-ʿAliyah (1825).","chapter_en":"Explanation of the Wine Concerning Which the Prohibition Was Revealed","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["ʿAbdullah ibn Abi al-Hudhayl said: ʿAbdullah used to swear by Allah that what the Messenger of Allah ﷺ commanded when wine was prohibited was that its large jars be broken and that what was made from dates and raisins be poured out."]},"buhuth":{"en":["His statement, “large jars,” is the plural of a large vessel.","Every intoxicant is forbidden, whatever type it may be, because it is the wine forbidden in the Qur’an, the Sunnah, and consensus. This is the view of the people of the Hijaz among the Companions and Followers, and among the jurists it was held by the leading scholars of legal verdicts in the regions: Malik, al-Layth, al-Shafiʿi, Ahmad, al-Awzaʿi, Abu Thawr, Ishaq, Dawud, and others. This is what the authentic reports from the Prophet ﷺ testify to, what the Arabic language testifies to regarding the meaning of wine, and what the Companions understood when the Qur’an was revealed prohibiting it. For more, see al-Minnah al-Kubra (7/355–356)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الدارقطني (4652)، وأحمد بن منيع في مسنده - كما في المطالب العالية (1825)."},{"num":7482,"demo":false,"sanad":"","matn":["عن عَائِشَةَ قَالَتْ: سُئِلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْبِتْعِ؟ فَقَالَ: كُلُّ شَرَابٍ أَسْكَرَ فَهْوَ حَرَامٌ."],"takhrij":"متفق عليه: رواه مالك في الأشربة (9) عن ابن شهاب، عن أبي سلمة بن عبدالرحمن، عن عائشة فذكرته.","grade":"متفق عليه","chapter_ar":"باب كل مسكر خمر وكل خمر حرام","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (9), al-Bukhari (5585), and Muslim (2001:67).","chapter_en":"Every Intoxicant Is Wine, and Every Wine Is Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["ʿA’ishah said: The Messenger of Allah ﷺ was asked about a honey-based drink. He said: “Every drink that intoxicates is forbidden.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (9)، والبخاري (5585)، ومسلم (67:2001)."},{"num":7483,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى قَالَ:  بَعَثَنِي النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَا وَمُعَاذَ بْنَ جَبَلٍ إِلَى الْيَمَنِ، فَقُلْتُ: يَا رَسُولَ اللَّهِ، إِنَّ شَرَابًا يُصْنَعُ بِأَرْضِنَا يُقَالُ لَهُ: الْمِزْرُ مِنَ الشَّعِيرِ، وَشَرَابٌ يُقَالُ لَهُ: الْبِتْعُ مِنَ الْعَسَلِ؟ فَقَالَ: كُلُّ مُسْكِرٍ حَرَامٌ."],"takhrij":"متفق عليه: رواه البخاري في المغازي (4343)، ومسلم في الأشربة (1733: 70) كلاهما من طريق سعيد بن أبي بُردة، عن أبيه، عن أبي موسى قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب كل مسكر خمر وكل خمر حرام","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (4343) and Muslim (1733:70). The wording is from Muslim.","chapter_en":"Every Intoxicant Is Wine, and Every Wine Is Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Abu Musa al-Ashʿari said: The Prophet ﷺ sent me and Muʿadh ibn Jabal to Yemen. I said: “O Messenger of Allah, a drink is made in our land called mizr from barley, and another drink called bitʿ from honey.” He said: “Every intoxicant is forbidden.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[9291],"tks":"متفق عليه: رواه البخاري (4343)، ومسلم (1733: 70). واللفظ لمسلم."},{"num":7484,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  كُلُّ مُسْكِرٍ خَمْرٌ، وَكُلُّ مُسْكِرٍ حَرَامٌ، وَمَنْ شَرِبَ الْخَمْرَ فِي الدُّنْيَا، فَمَاتَ وَهُوَ يُدْمِنُهَا لَمْ يَتُبْ، لَمْ يَشْرَبْهَا فِي الْآخِرَةِ."],"takhrij":"متفق عليه: رواه مسلم في الأشربة (2003: 73) من طريق أيوب، عن نافع، عن ابن عمر قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب كل مسكر خمر وكل خمر حرام","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2003:73) and al-Bukhari (5575).","chapter_en":"Every Intoxicant Is Wine, and Every Wine Is Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Ibn ʿUmar said: The Messenger of Allah ﷺ said: “Every intoxicant is wine, and every intoxicant is forbidden. Whoever drinks wine in this world and dies while being addicted to it, without repenting, will not drink it in the Hereafter.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[11997],"tks":"متفق عليه: رواه مسلم (2003: 73)، والبخاري (5575)."},{"num":7485,"demo":false,"sanad":"","matn":["عَنْ بُرَيْدَةَ بْنِ الحصيب أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: نَهَيْتُكُمْ عَنِ الظُّرُوفِ، وَإِنَّ الظُّرُوفَ – أَوْ ظَرْفًا - لَا يُحلُّ شَيْئًا وَ لَا يُحَرِّمُهُ، وَكُلُّ مُسْكِرٍ حَرَامٌ."],"takhrij":"صحيح: رواه مسلم في الأشربة (977: 64) عن حجاج بن الشاعر، حدثنا ضحاك بن مخلد، عن سفيان، عن علقمة بن مرثد، عن ابن بريدة، عن أبيه فذكره.","grade":"صحيح","chapter_ar":"باب كل مسكر خمر وكل خمر حرام","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (977:64).","chapter_en":"Every Intoxicant Is Wine, and Every Wine Is Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Buraydah ibn al-Husayb narrated that the Messenger of Allah ﷺ said: “I had forbidden you from certain containers, but containers do not make anything lawful or unlawful. Every intoxicant is forbidden.”"]}},"tuhfa":{},"full":1,"rep":[7545],"tks":"صحيح: رواه مسلم (977: 64)."},{"num":7486,"demo":false,"sanad":"","matn":["سَأَلْتُ ابْنَ عَبَّاسٍ عَنِ الْبَاذَقِ،. فَقَالَ: سَبَقَ مُحَمَّدٌ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْبَاذَقَ، فَمَا أَسْكَرَ فَهْوَ حَرَامٌ. قَالَ: الشَّرَابُ الْحَلاَلُ الطَّيِّبُ. قَالَ: لَيْسَ بَعْدَ الْحَلاَلِ الطَّيِّبِ إِلاَّ الْحَرَامُ الْخَبِيثُ."],"takhrij":"صحيح: رواه البخاري في الأشربة (5598) عن محمد بن كثير، أخبرنا سفيان، عن أبي الجويرية قال: سألت ابن عباس عن الباذق فقال: فذكره.","grade":"صحيح","chapter_ar":"باب كل مسكر خمر وكل خمر حرام","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5598).","chapter_en":"Every Intoxicant Is Wine, and Every Wine Is Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Ibn ʿAbbas was asked about badhiq. He said: Muhammad ﷺ already judged before badhiq appeared: whatever intoxicates is forbidden. It was said: “What about lawful, good drink?” He said: “After lawful, good drink, there is nothing except forbidden, filthy drink.”"]},"buhuth":{"en":["Badhiq is when grape juice is cooked until it becomes like the coating used on camels, and it becomes intoxicating."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (5598). والباذق هو: إذا طبخ عصير العنب حتى يصير مثل طلاء الإبل فيكون مسكرا."},{"num":7487,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُنْبَذَ فِي النَّقِيرِ، وَالْمُزَفَّتِ، وَالدُّبَّاءِ، وَالْحَنْتَمَةِ، وَقَالَ: كُلُّ مُسْكِرٍ حَرَامٌ."],"takhrij":"حسن: رواه النسائي (5588، 5589)، وابن ماجه (3401)، وأحمد (9539، 10510)، وصحّحه ابن حبان (5408) كلهم من طرق عن محمد بن عمرو، ثنا أبو سلمة، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب كل مسكر خمر وكل خمر حرام","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (5588, 5589), Ibn Majah (3401), Ahmad (9539, 10510), and authenticated by Ibn Hibban (5408).","chapter_en":"Every Intoxicant Is Wine, and Every Wine Is Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ forbade making date infusion in hollowed palm trunks, pitch-coated vessels, gourds, and green jars, and he said: “Every intoxicant is forbidden.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (5588، 5589)، وابن ماجه (3401)، وأحمد (9539، 10510)، وصححه ابن حبان (5408)."},{"num":7488,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ قَالَ سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: كُلُّ مُسْكِرٍ حَرَامٌ، وكل مُسْكِرٍ خمر."],"takhrij":"حسن: رواه الترمذي (1864)، والنسائي (5587)، وابن ماجه (3390)، وأحمد (4644)، وصحّحه ابن حبان (5369) كلهم من طرق عن محمد بن عمرو، ثنا أبو سلمة، عن ابن عمر قال: فذكره.","grade":"حسن","chapter_ar":"باب كل مسكر خمر وكل خمر حرام","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1864), al-Nasa’i (5587), Ibn Majah (3390), Ahmad (4644), and authenticated by Ibn Hibban (5369).","chapter_en":"Every Intoxicant Is Wine, and Every Wine Is Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Ibn ʿUmar said: I heard the Prophet ﷺ say: “Every intoxicant is forbidden, and every intoxicant is wine.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (1864)، والنسائي (5587)، وابن ماجه (3390)، وأحمد (4644)، وصححه ابن حبان (5369)."},{"num":7489,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ: خَطَبَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرَ آيَةَ الْخَمْرِ، فَقَالَ رَجُلٌ: يَا رَسُولَ اللَّهِ أَرَأَيْتَ الْمِزْرَ؟ قَالَ: وَمَا الْمِزْرُ. قَالَ: حَبَّةٌ تُصْنَعُ بِالْيَمَنِ. فَقَالَ: تُسْكِرُ. قَالَ: نَعَمْ. قَالَ: كُلُّ مُسْكِرٍ حَرَامٌ."],"takhrij":"صحيح: رواه النسائي (5605) عن أبي بكر بن علي، ثنا نصر بن علي، أخبرني أبي، ثنا إبراهيم بن نافع، عن ابن طاوس، عن أبيه، عن ابن عمر قال: فذكره.","grade":"صحيح","chapter_ar":"باب كل مسكر خمر وكل خمر حرام","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (5605).","chapter_en":"Every Intoxicant Is Wine, and Every Wine Is Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Ibn ʿUmar said: The Messenger of Allah ﷺ delivered a sermon and mentioned the verse of wine. A man said: “What do you think about mizr?” He said: “What is mizr?” He said: “A drink made from grain in Yemen.” He said: “Does it intoxicate?” He said: “Yes.” He said: “Every intoxicant is forbidden.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (5605)."},{"num":7490,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى الأشعري قَالَ: بَعَثَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَا وَمُعَاذٌ إِلَى الْيَمَنِ، فَقَالَ مُعَاذٌ: إِنَّكَ تَبْعَثُنَا إِلَى أَرْضٍ كَثِيرٌ شَرَابُ أَهْلِهَا، فَمَا أَشْرَبُ؟ قَالَ: اشْرَبْ وَلاَ تَشْرَبْ مُسْكِرًا."],"takhrij":"صحيح: رواه النسائي (5596) عن أحمد بن عبد الله بن علي، ثنا عبد الرحمن، عن إسرائيل، عن أبي إسحاق، عن أبي بردة، عن أبيه قال: فذكره.","grade":"صحيح","chapter_ar":"باب كل مسكر خمر وكل خمر حرام","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (5596).","chapter_en":"Every Intoxicant Is Wine, and Every Wine Is Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Abu Musa al-Ashʿari said: The Messenger of Allah ﷺ sent me and Muʿadh to Yemen. Muʿadh said: “You are sending us to a land whose people have many drinks, so what should I drink?” He said: “Drink, but do not drink anything intoxicating.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (5596)."},{"num":7491,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سُئِلَ عَنْ شَرَابٍ بِالْيَمَنِ، يُقَالَ لَهُ: الْبِتْعُ وَالْمِزْرُ، فَقَالَ: مَا أَسْكَرَ فَهُوَ حَرَامٌ."],"takhrij":"حسن: رواه أبو يعلى (3971) عن محمد بن إسماعيل بن أبي سمينة البصري، ثنا عبد الله بن إدريس، عن المختار بن فُلفُل، عن أنس بن مالك قال: فذكره. وسيأتي مفصلا في باب ترخيص النبي صلى الله عليه وسلم في الأوعية.","grade":"حسن","chapter_ar":"باب كل مسكر خمر وكل خمر حرام","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Yaʿla (3971).","chapter_en":"Every Intoxicant Is Wine, and Every Wine Is Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Anas ibn Malik narrated that the Messenger of Allah ﷺ was asked about a drink in Yemen called bitʿ and mizr. He said: “Whatever intoxicates is forbidden.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو يعلى (3971)."},{"num":7492,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ، أَنَّهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: كُلُّ مُسْكِرٍ حَرَامٌ."],"takhrij":"حسن: رواه أحمد (6738) عن محمد بن عبد الله بن الزبير، حدثنا أبان بن عبد الله، عن عمرو بن شعيب، عن أبيه، عن جده قال: فذكره.","grade":"حسن","chapter_ar":"باب كل مسكر خمر وكل خمر حرام","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (6738).","chapter_en":"Every Intoxicant Is Wine, and Every Wine Is Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["ʿAbdullah ibn ʿAmr ibn al-ʿAs said: The Messenger of Allah ﷺ said: “Every intoxicant is forbidden.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (6738)."},{"num":7493,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ بن الشِّخِّيرِ عَنْ أَبِيهِ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْأَشْرِبَةِ، فَقِيلَ: إِنَّهُ لَا بُدَّ مِنْهَا، فَقَالَ: اشْرَبُوا مَا لَا يُسَفِّهُ أَحْلَامَكُمْ، وَلَا يُذْهِبُ أَمْوَالَكُمْ."],"takhrij":"حسن: رواه الطبراني ومن طريق الضياء في المختارة (642) عن عبدان بن أحمد، ثنا الحسين بن مهدي، ثنا عبد الرزاق، عن الثوري، عن الجريري، عن يزيد بن عبد الله، عن أبيه قال: فذكره.","grade":"حسن","chapter_ar":"باب كل مسكر خمر وكل خمر حرام","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani, and through him by al-Diya’ in al-Mukhtarah (9, no. 642).","chapter_en":"Every Intoxicant Is Wine, and Every Wine Is Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["ʿAbdullah ibn al-Shikhkhir said: The Messenger of Allah ﷺ forbade certain drinks. It was said: “But they are necessary.” He said: “Drink what does not corrupt your minds and does not cause your wealth to go away.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني، ومن طريقه الضياء في المختارة (642)."},{"num":7494,"demo":false,"sanad":"","matn":["عَنْ أُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَتْ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ كُلِّ مُسْكِرٍ وَمُفَتِّرٍ."],"takhrij":"حسن: رواه أبوداود (3686)، وأحمد (26634) كلاهما من طريق الحكم بن عتيبة، عن شهر بن حوشب قال: سمعت أم سلمة فذكرته.","grade":"حسن","chapter_ar":"باب كل مسكر خمر وكل خمر حرام","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3686) and Ahmad (26634).","chapter_en":"Every Intoxicant Is Wine, and Every Wine Is Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Umm Salamah said: The Messenger of Allah ﷺ forbade every intoxicant and every substance that causes bodily weakness."]},"buhuth":{"en":["His statement, “that causes bodily weakness,” refers to something which, when drunk, warms the body and produces slackness, meaning weakness and loss of vigor."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3686)، وأحمد (26634)."},{"num":7495,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا أَسْكَرَ كَثِيرُهُ فَقَلِيلُهُ حَرَامٌ."],"takhrij":"حسن: رواه أبوداود (3681)، والترمذي (1865)، وابن ماجه (3393)، وأحمد (14703)، وصحّحه ابن حبان (5382) كلهم من طريق داود بن بكر بن أبي الفرات، عن محمد بن المنكدر، عن جابر بن عبد الله قال: فذكره.","grade":"حسن","chapter_ar":"باب ما أسكر كثيره فقليله حرام","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3681), al-Tirmidhi (1865), who graded it hasan, Ibn Majah (3393), Ahmad (14703), and authenticated by Ibn Hibban (5382).","chapter_en":"Whatever Intoxicates in Large Amounts, a Small Amount of It Is Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["Jabir ibn ʿAbdullah said: The Messenger of Allah ﷺ said: “Whatever intoxicates in large amounts, a small amount of it is forbidden.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3681)، والترمذي (1865) وحسنه، وابن ماجه (3393)، وأحمد (14703)، وصححه ابن حبان (5382)."},{"num":7496,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، رَضِيَ اللَّهُ عَنْهَا قَالَتْ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: كُلُّ مُسْكِرٍ حَرَامٌ، وَمَا أَسْكَرَ مِنْهُ الْفَرْقُ فَمِلْءُ الْكَفِّ مِنْهُ حَرَامٌ.","وفي لفظ: الحسوة منه حرام."],"takhrij":"حسن: رواه أبوداود (3687)، والترمذي (1866)، وأحمد (24423) كلهم من طريق أبي عثمان الأنصاري، قال: حدثني القاسم بن محمد بن أبي بكر، أن عائشة قالت: فذكرته.","grade":"حسن","chapter_ar":"باب ما أسكر كثيره فقليله حرام","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3687), al-Tirmidhi (1866), who graded it hasan, and Ahmad (24423).","chapter_en":"Whatever Intoxicates in Large Amounts, a Small Amount of It Is Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["ʿA’ishah said: I heard the Messenger of Allah ﷺ say: “Every intoxicant is forbidden, and if a faraq of it intoxicates, then a handful of it is forbidden.” In another wording: “A sip of it is forbidden.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3687)، والترمذي (1866) وحسنه، وأحمد (24423)."},{"num":7497,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن عمرو، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَا أَسْكَرَ كَثِيرُهُ فَقَلِيلُهُ حَرَامٌ."],"takhrij":"حسن: رواه النسائي (5607)، وابن ماجه (3394)، وأحمد (6674) كلهم من طريق عبيد الله بن عمر، عن عمرو بن شعيب، عن أبيه، عن جده.","grade":"حسن","chapter_ar":"باب ما أسكر كثيره فقليله حرام","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (5607), Ibn Majah (3394), and Ahmad (6674).","chapter_en":"Whatever Intoxicates in Large Amounts, a Small Amount of It Is Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["ʿAbdullah ibn ʿAmr narrated from the Prophet ﷺ that he said: “Whatever intoxicates in large amounts, a small amount of it is forbidden.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (5607)، وابن ماجه (3394)، وأحمد (6674)."},{"num":7498,"demo":false,"sanad":"","matn":["عَنْ سَعْدِ بن أَبِي وَقَّاصٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَنْهَاكُمْ عَنْ قَلِيلِ مَا أَسْكَرَ كَثِيرُهُ."],"takhrij":"حسن: رواه النسائي (5608، 5609)، وأحمد في الأشربة (9)، وأبو يعـلى (694)، وصحّحه ابن حبان (53701)، والضياء في المختارة (975، 976، 977)كلهم من طرق عن الضحاك بن عثمان، عن بُكير بن عبد الله بن الأشج، عن عامر بن سعد، عن أبيه فذكره.","grade":"حسن","chapter_ar":"باب ما أسكر كثيره فقليله حرام","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (5608, 5609), Ahmad (9), Abu Yaʿla (694), and authenticated by Ibn Hibban (5370).","chapter_en":"Whatever Intoxicates in Large Amounts, a Small Amount of It Is Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["Saʿd ibn Abi Waqqas narrated from the Prophet ﷺ that he said: “I forbid you from a small amount of that which intoxicates in large amounts.”"]},"buhuth":{"en":["Abu ʿAbd al-Rahman al-Nasa’i said after these hadiths: “In this is evidence for the prohibition of intoxicants, both small and large amounts. It is not as those who deceive themselves say, that they forbid the last drink but permit what came before it, which is drunk from the faraq before it. There is no disagreement among the people of knowledge that intoxication as a whole does not occur from the final drink alone, apart from the first and the second before it. And success is from Allah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (5608، 5609)، وأحمد (9)، وأبو يعلى (694)، وصححه ابن حبان (53701)."},{"num":7499,"demo":false,"sanad":"","matn":["7499 - عَنْ ابْنِ عُمَرَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : كُلُّ مُسْكِرٍ حَرَامٌ، مَا أَسْكَرَ كَثِيرُهُ فَقَلِيلُهُ حَرَامٌ."],"takhrij":"حسن: رواه أحمد (5648)، وأبو يعلى (5466)، والبيهقي (76) كلهم من طريق أبي معشر، عن موسى بن عقبة، عن سالم بن عبد الله، عن أبيه، فذكره. واقتصر أبو يعلى على الشطر الأول.","grade":"حسن","chapter_ar":"باب ما أسكر كثيره فقليله حرام","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (5648), Abu Yaʿla (5466), al-Bayhaqi (8/296), and al-Bazzar (2917, Kashf al-Astar).","chapter_en":"Whatever Intoxicates in Large Amounts, a Small Amount of It Is Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["Ibn ʿUmar said: The Messenger of Allah ﷺ said: “Every intoxicant is forbidden. Whatever intoxicates in large amounts, a small amount of it is forbidden.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (5648)، وأبو يعلى (5466)، والبيهقي (76)، والبزار (2917 - كشف الأستار)."},{"num":7500,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: قَدِمَ وَفْدُ عَبْدِ الْقَيْسِ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالُوا: إِنَّا مِنْ هَذَا الْحَىِّ مِنْ رَبِيعَةَ، وَلَسْنَا نَصِلُ إِلَيْكَ إِلاَّ فِي الشَّهْرِ الْحَرَامِ، فَمُرْنَا بِشَىْءٍ نَأْخُذْهُ عَنْكَ، وَنَدْعُو إِلَيْهِ مَنْ وَرَاءَنَا. فَقَالَ: آمُرُكُمْ بِأَرْبَعٍ، وَأَنْهَاكُمْ عَنْ أَرْبَعٍ: الإِيمَانِ بِاللَّهِ، ـ ثُمَّ فَسَّرَهَا لَهُمْ شَهَادَةُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ، وَأَنِّي رَسُولُ اللَّهِ، وَإِقَامُ الصَّلاَةِ، وَإِيتَاءُ الزَّكَاةِ، وَأَنْ تُؤَدُّوا إِلَىَّ خُمُسَ مَا غَنِمْتُمْ، وَأَنْهَى عَنِ الدُّبَّاءِ، وَالْحَنْتَمِ، وَالْمُقَيَّرِ، وَالنَّقِيرِ.","وَفِي رِوَايَةٍ: \"الْمُزَفَّتِ\" بَدَلَ \"الْمُقَيَّرِ\"."],"takhrij":"متفق عليه: رواه البخاري في مواقيت الصلاة (523)، ومسلم في الأشربة (17: 39) كلاهما من طريق عباد بن عباد، عن أبي جمرة، عن ابن عباس.","grade":"متفق عليه","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (523) and Muslim (17:39). The wording is from al-Bukhari.","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Ibn ʿAbbas said: The delegation of ʿAbd al-Qays came to the Messenger of Allah ﷺ and said: “We are from this tribe of Rabiʿah, and we cannot reach you except in the sacred month, so command us with something that we may take from you and call those behind us to.” He said: “I command you with four and forbid you from four: belief in Allah.” Then he explained it to them: “To testify that there is no deity except Allah and that I am the Messenger of Allah, to establish prayer, to give alms, and to give me one fifth of what you acquire as spoils. And I forbid you from gourds, green jars, pitch-coated vessels, and hollowed palm trunks.” In another narration: “pitch-coated vessels (al-muzaffat)” appears in place of “tar-coated vessels (al-muqayyar).”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (523)، ومسلم (17: 39). واللفظ للبخاري."},{"num":7501,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، أَنَّ وَفْدَ عَبْدِ الْقَيْسِ أَتَوْا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فِيهِمُ الْأَشَجُّ أَخُو بَنِي عَصَرٍ، فَقَالُوا: يَا نَبِيَّ اللَّهِ، إِنَّا حَيٌّ مِنْ رَبِيعَةَ، وَإِنَّ بَيْنَنَا وَبَيْنَكَ كُفَّارَ مُضَرَ، وَإِنَّا لَا نَصِلُ إِلَيْكَ إِلَّا فِي الشَّهْرِ الْحَرَامِ، فَمُرْنَا بِأَمْرٍ إِذَا عَمِلْنَا بِهِ دَخَلْنَا الْجَنَّةَ، وَنَدْعُو بِهِ مَنْ وَرَاءَنَا؟ فَأَمَرَهُمْ بِأَرْبَعٍ، وَنَهَاهُمْ عَنْ أَرْبَعٍ: أَمَرَهُمْ أَنْ يَعْبُدُوا اللهَ وَلَا يُشْرِكُوا بِهِ شَيْئًا، وَأَنْ يَصُومُوا رَمَضَانَ، وَأَنْ يَحُجُّوا الْبَيْتَ، وَأَنْ يُعْطُوا الْخُمُسَ مِنَ الْمَغَانِمِ، وَنَهَاهُمْ عَنْ أَرْبَعٍ: عَنِ الشُّرْبِ فِي الْحَنْتَمِ، وَالدُّبَّاءِ، وَالنَّقِيرِ، وَالْمُزَفَّتِ، فَقَالُوا: فَفِيمَ نَشْرَبُ يَا رَسُولَ اللَّهِ؟ قَالَ: عَلَيْكُمْ بِأَسْقِيَةِ الْأَدَمِ، الَّتِي يُلَاثُ عَلَى أَفْوَاهِهَا."],"takhrij":"صحيح: رواه أبو داود ( (3694)، وأحمد (3406) والسياق له، كلاهما من طريق أبان بن يزيد العطّار، ثنا قتادة، عن عكرمة وسعيد بن المسيب، عن ابن عباس فذكره. وإسناده صحيح، غير أن ذكر حج البيت في هذا الحديث شاذ، لأنه لم يكن فُرض وقتئذ؛ لذلك لم يرد ذكره في رواية أبي جمرة عن ابن عباس التي في الصحيحين.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3694) and Ahmad (3406), and the wording is his. However, the mention of pilgrimage to the House in this hadith is irregular, because it had not yet been made obligatory at that time. Therefore, it is not mentioned in the narration of Abu Jamrah from Ibn ʿAbbas found in the two authentic collections.","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Ibn ʿAbbas narrated that the delegation of ʿAbd al-Qays came to the Messenger of Allah ﷺ, among them al-Ashajj, the brother of Banu ʿAsr. They said: “O Prophet of Allah, we are a tribe from Rabiʿah, and between us and you are the disbelievers of Mudar. We cannot reach you except in the sacred month. So command us with a command which, if we act upon it, we will enter Paradise, and by which we may call those behind us.” He commanded them with four and forbade them from four. He commanded them to worship Allah and not associate anything with Him, to fast Ramadan, to perform pilgrimage to the House, and to give one fifth of the spoils. He forbade them from four: drinking from green jars, gourds, hollowed palm trunks, and pitch-coated vessels. They said: “Then what should we drink from, O Messenger of Allah?” He said: “Use leather water skins whose mouths are tied.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه أبو داود (3694)، وأحمد (3406) والسياق له، غير أن ذكر حج البيت في هذا الحديث شاذ، لأنه لم يكن فرض وقتئذ؛ لذلك لم يرد ذكره في رواية أبي جمرة عن ابن عباس التي في الصحيحين."},{"num":7502,"demo":false,"sanad":"","matn":["عن سَعِيدِ بْنِ المسيب يَقُولُ: سَمِعْتُ عَبْدَ اللَّهِ بْنَ عُمَرَ يَقُولُ: عِنْدَ هَذَا الْمِنْبَرِ، وَأَشَارَ إِلَى مِنْبَرِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ،  قَدِمَ وَفْدُ عَبْدِ الْقَيْسِ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَسَأَلُوهُ عَنِ الْأَشْرِبَةِ، فَنَهَاهُمْ عَنِ الدُّبَّاءِ، وَالنَّقِيرِ، وَالْحَنْتَمِ، فَقُلْتُ لَهُ: يَا أَبَا مُحَمَّدٍ، وَالْمُزَفَّتِ؟ وَظَنَنَّا أَنَّهُ نَسِيَهُ فَقَالَ: لَمْ أَسْمَعْهُ يَوْمَئِذٍ مِنْ عَبْدِ اللَّهِ بْنِ عُمَرَ، وَقَدْ كَانَ يَكْرَهُ."],"takhrij":"صحيح: رواه مسلم في الأشربة (1997: 58) عن أبي بكر بن أبي شيبة، حدثنا يزيد بن هارون، أخبرنا عبد الخالق بن سلمة، قال: سمعت سعيد بن المسيب يقول: فذكره.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1997:58).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Saʿid ibn al-Musayyib said: I heard ʿAbdullah ibn ʿUmar say near this pulpit — and he pointed to the pulpit of the Messenger of Allah ﷺ: The delegation of ʿAbd al-Qays came to the Messenger of Allah ﷺ and asked him about drinks. He forbade them from gourds, hollowed palm trunks, and green jars. I said to him: “O Abu Muhammad, and pitch-coated vessels?” We thought he had forgotten it. He said: “I did not hear it that day from ʿAbdullah ibn ʿUmar, though he used to dislike it.”"]}},"tuhfa":{},"full":1,"rep":[9770],"tks":"صحيح: رواه مسلم (1997: 58)."},{"num":7503,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ: فِي حَدِيثِهِ هَذَا، أَنَّ أُنَاسًا مِنْ عَبْدِ الْقَيْسِ، قَدِمُوا عَلَى رَسُولِ اللَّهِ.. صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ... الحديث. وفيه: فَفِيمَ نَشْرَبُ يَا رَسُولَ اللهِ؟ قَالَ: فِي أَسْقِيَةِ الْأَدَمِ، الَّتِي يُلَاثُ عَلَى أَفْوَاهِهَا، قَالُوا: يَا رَسُولَ اللهِ، إِنَّ أَرْضَنَا كَثِيرَةُ الْجِرْذَانِ، وَلَا تَبْقَى بِهَا أَسْقِيَةُ الْأَدَمِ، فَقَالَ نَبِيُّ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : وَإِنْ أَكَلَتْهَا الْجِرْذَانُ، وَإِنْ أَكَلَتْهَا الْجِرْذَانُ، وَإِنْ أَكَلَتْهَا الْجِرْذَانُ."],"takhrij":"صحيح: رواه مسلم في الإيمان (18: 26) عن يحيى بن أيوب، ثنا ابن علية، ثنا سعيد بن أبي عروبة، عن قتادة قال: حدثنا من لقي الوفد الذين قدموا على رسول الله صلى الله عليه وسلم من عبدالقيس.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim in the Book of Faith (18:26).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Abu Saʿid al-Khudri narrated that some people from ʿAbd al-Qays came to the Messenger of Allah ﷺ … the hadith. In it: It was said: “What should we drink from, O Messenger of Allah?” He said: “From leather water skins whose mouths are tied.” They said: “O Messenger of Allah, our land has many rats, and leather water skins do not last there.” The Prophet of Allah ﷺ said: “Even if the rats eat them, even if the rats eat them, even if the rats eat them.”"]},"buhuth":{"en":["His statement, “rats,” refers to a type of mouse. His statement, “whose mouths are tied,” means that a cord is wrapped around their mouths and tied with it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (18:26). وقوله: “الجرذان” بكسر الجيم، جمع جرذ، بضم الجيم وفتح الراء، وهو نوع من الفأر. وقوله: “يلاث على أفواهها” أي يلف الخيط على أفواهها ويربط بها."},{"num":7504,"demo":false,"sanad":"","matn":["أَنَّ أَبَا سَعِيدٍ الْخُدْرِيَّ أَخْبَرَهُ،  أَنَّ وَفْدَ عَبْدِ الْقَيْسِ لَمَّا أَتَوْا نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالُوا: يَا نَبِيَّ اللَّهِ، جَعَلَنَا اللهُ فِدَاءَكَ، مَاذَا يَصْلُحُ لَنَا مِنَ الْأَشْرِبَةِ؟ فَقَالَ: لَا تَشْرَبُوا فِي النَّقِيرِ، قَالُوا: يَا نَبِيَّ اللَّهِ، جَعَلَنَا اللهُ فِدَاءَكَ، أَوَتَدْرِي مَا النَّقِيرُ؟ قَالَ: نَعَمْ، الْجِذْعُ يُنْقَرُ وَسَطُهُ، وَلَا فِي الدُّبَّاءِ، وَلَا فِي الْحَنْتَمَةِ، وَعَلَيْكُمْ بِالْمُوكَى."],"takhrij":"صحيح: رواه مسلم في الإيمان (18: 28) عن محمد بن رافع، حدثنا عبد الرزاق –وهو في مصنفه (16929)- أخبرنا ابن جريج، قال: أخبرني أبو قزعة، أن أبا نضرة أخبره، وحسنا أخبرهما أن أبا سعيد الخدري قال: فذكر الحديث.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (18:28).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Abu Saʿid al-Khudri narrated that when the delegation of ʿAbd al-Qays came to the Prophet of Allah ﷺ, they said: “O Prophet of Allah, may Allah make us your ransom, what drinks are suitable for us?” He said: “Do not drink from the hollowed palm trunk.” They said: “O Prophet of Allah, may Allah make us your ransom, do you know what the hollowed palm trunk is?” He said: “Yes, the trunk whose middle is hollowed out. And do not drink from gourds or green jars. Use tied leather water skins.”"]},"buhuth":{"en":["His statement, “use tied leather water skins,” means: make infusion in a thin leather water skin whose mouth is tied with a cord."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (18:28)."},{"num":7505,"demo":false,"sanad":"","matn":["عن ثمامة بن حزن القشيري قَالَ:  لَقِيتُ عَائِشَةَ فَسَأَلْتُهَا عَنِ النَّبِيذِ؟ فَحَدَّثَتْنِي: أَنَّ وَفْدَ عَبْدِ الْقَيْسِ قَدِمُوا عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَسَأَلُوا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ النَّبِيذِ، فَنَهَاهُمْ أَنْ يَنْتَبِذُوا فِي الدُّبَّاءِ، وَالنَّقِيرِ، وَالْمُزَفَّتِ، وَالْحَنْتَمِ."],"takhrij":"صحيح: رواه مسلم في الأشربة (1995: 37) عن شيبان بن فروخ، حدثنا القاسم بن الفضل، حدثنا ثمامة بن حزن القشيري قال: فذكره.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1995:37).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Thumamah ibn Hazn al-Qushayri said: I met ʿA’ishah and asked her about date infusion. She narrated to me that the delegation of ʿAbd al-Qays came to the Prophet ﷺ and asked him about date infusion, so he forbade them from making infusion in gourds, hollowed palm trunks, pitch-coated vessels, and green jars."]}},"tuhfa":{},"full":1,"rep":[9769],"tks":"صحيح: رواه مسلم (1995:37)."},{"num":7506,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الدُّبَّاءِ، وَالْحَنْتَمِ، وَالنَّقِيرِ وَالْمُزَفَّتِ. وَفِي رِوَايَةِ: \"المزفت\" بدل \"المقير\"."],"takhrij":"صحيح: رواه مسلم في الأشربة (1995: 38) عن يعقوب بن إبراهيم، حدثنا ابن علية، حدثنا إسحاق بن سويد، عن معاذة، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1995:38).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["ʿA’ishah said: The Messenger of Allah ﷺ forbade gourds, green jars, hollowed palm trunks, and pitch-coated vessels. In another narration: “pitch-coated vessels (al-muzaffat)” appears in place of “tar-coated vessels (al-muqayyar).”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1995:38)."},{"num":7507,"demo":false,"sanad":"","matn":["عَنْ إِبْرَاهِيمَ، قُلْتُ لِلأَسْوَدِ: هَلْ سَأَلْتَ عَائِشَةَ أُمَّ الْمُؤْمِنِينَ عَمَّا يُكْرَهُ أَنْ يُنْتَبَذَ فِيهِ؟ فَقَالَ نَعَمْ، قُلْتُ: يَا أُمَّ الْمُؤْمِنِينَ عَمَّا نَهَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُنْتَبَذَ فِيهِ، قَالَتْ: نَهَانَا فِي ذَلِكَ أَهْلَ الْبَيْتِ أَنْ نَنْتَبِذَ فِي الدُّبَّاءِ، وَالْمُزَفَّتِ. قُلْتُ أَمَا ذَكَرْتِ الْجَرَّ وَالْحَنْتَمَ قَالَ: إِنَّمَا أُحَدِّثُكَ مَا سَمِعْتُ، أَفَأُحَدِّثُ مَا لَمْ أَسْمَعْ."],"takhrij":"متفق عليه: رواه البخاري في الأشربة (5595)، ومسلم في الأشربة (1995: 35) كلاهما من طريق جرير، عن منصور، عن إبراهيم (هو النخعي) به.","grade":"متفق عليه","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5595) and Muslim (1995:35). In a wording of Muslim: “The Prophet ﷺ forbade gourds and pitch-coated vessels.”","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Ibrahim said: I said to al-Aswad: “Did you ask ʿA’ishah, the Mother of the Believers, about what is disliked for making infusion in?” He said: “Yes.” I said: “O Mother of the Believers, inform me about what the Messenger of Allah ﷺ forbade making infusion in.” She said: “He forbade us, the household, from making infusion in gourds and pitch-coated vessels.” I said to him: “Did she not mention green jars and earthenware jars?” He said: “I only narrate to you what I heard. Should I narrate to you what I did not hear?”"]},"buhuth":{"en":["The word “earthenware jars” refers to vessels made from pottery. Concerning “green jars,” al-Nawawi said in his explanation of Muslim (1/185): “As for green jars, there is disagreement about them, but the soundest and strongest view is that they are green jars.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5595)، ومسلم (1995:35). وفي لفظ لمسلم: “أن النبي ﷺ نهى عن الدباء والمزفت”."},{"num":7508,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لاَ تَنْبِذُوا فِي الدُّبَّاءِ، وَلاَ الْمُزَفَّتِ، وَلاَ النَّقِيرِ، وَكُلُّ مُسْكِرٍ حَرَامٌ."],"takhrij":"صحيح: رواه النسائي (5590) عن أبي داود، ثنا محمد بن سليما، ثنا ابن زبر، عن القاسم بن محمد، عن عائشة قالت: فذكرته.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (5590).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["ʿA’ishah narrated from the Prophet ﷺ that he said: “Do not make infusion in gourds, pitch-coated vessels, or hollowed palm trunks. Every intoxicant is forbidden.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (5590)."},{"num":7509,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  قَالَ لِوَفْدِ عَبْدِ الْقَيْسِ: أَنْهَاكُمْ عَنِ الدُّبَّاءِ، وَالْحَنْتَمِ، وَالنَّقِيرِ، وَالْمُقَيَّرِ، وَالْحَنْتَمُ: الْمَزَادَةُ الْمَجْبُوبَةُ وَلَكِنِ اشْرَبْ فِي سِقَائِكَ وَأَوْكِهِ.","وفي لفظ: \" والحنتم والمزادة المجبوبة\"."],"takhrij":"صحيح: رواه مسلم في الأشربة (1991: 33) عن نصر بن علي الجهضمي، أخبرنا نوح بن قيس، حدثنا ابن عون، عن محمد (هو ابن سيرين)، عن أبي هريرة قال: فذكره. واللفظ الآخر لأبي داود abudawud(3693) من هذا الوجه.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1991:33). The other wording is from Abu Dawud (3693). This is the correct wording, because “water skin” is not an explanation of “green jar”; rather, the green jar is the earthenware jar, and the water skin is the leather container. His statement, “whose top has been cut off,” means one whose top has been removed so that it becomes like a large jar. The root meaning is cutting; its top is cut so that it no longer has a neck that can be tied.","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Abu Hurayrah narrated that the Prophet ﷺ said to the delegation of ʿAbd al-Qays: “I forbid you from gourds, green jars, hollowed palm trunks, and pitch-coated vessels — and the green jar is a water skin whose top has been cut off — but drink from your leather water skin and tie it.” In another wording: “green jars and water skins whose tops have been cut off.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1991:33). واللفظ الآخر لأبي داود abudawud(3693). وهو الصحيح؛ فإن المزادة ليس تفسيرا للحنتم، لأن الحنتم هو الجر، والمزادة هي السقاء. وقوله: “المجبوبة” هي التي قطع رأسها فصارت كهيئة الدن، وأصل الجب: القطع، فيقطع رأسها حتى لا تكون لها رقبة توكى."},{"num":7510,"demo":false,"sanad":"","matn":["عَنْ أَبِي القموص زيد بن عَلِيٍّ قَالَ: قَالَ حَدَّثَنِي أَحَدُ الْوَفْدِ الَّذِينَ وَفَدُوا عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ عَبْدِ الْقَيْسِ قَالَ: وَأَهْدَيْنَا لَهُ فِيمَا يهدى نَوْطًا أَوْ قِرْبَةً مِنْ تَعْضُوضٍ أَوْ بَرْنِيٍّ، فَقَالَ: مَا هَذَا؟ قُلْنَا: هَذِهِ هَدِيَّةٌ. قَالَ: وَأَحْسِبُهُ نَظَرَ إِلَى تَمْرَةٍ مِنْهَا فَأَعَادَهَا مَكَانَهَا وَقَالَ: أَبْلِغُوهَا آلَ مُحَمَّدٍ قَالَ: فَسَأَلَهُ الْقَوْمُ عَنْ أَشْيَاءَ حَتَّى سَأَلُوهُ عَنِ الشَّرَابِ فَقَالَ: لَا تَشْرَبُوا فِي دُبَّاءٍ، وَلَا حَنْتَمٍ، وَلَا نَقِيرٍ، وَلَا مُزَفَّتٍ، اشْرَبُوا فِي الْحَلَالِ الْمُوكَى عَلَيْهِ، فَقَالَ لَهُ قَائِلُنَا: يَا رَسُولَ اللَّهِ! وَمَا يُدْرِيكَ مَا الدُّبَّاءُ وَالْحَنْتَمُ وَالنَّقِيرُ وَالْمُزَفَّتُ؟ قَالَ: أَنَا لأدري ماهيه أَيُّ هَجَرٍ أَعَزُّ؟ قُلْنَا: الْمُشَقَّرُ، قَالَ: فَوَاللهِ لَقَدْ دَخَلْتُهَا وَأَخَذْتُ إِقْلِيدَهَا، قَالَ: وَكُنْتُ قَدْ نَسِيتُ مِنْ حَدِيثِهِ شَيْئًا، فَأَذْكَرَنِيهِ عُبَيْدُ اللَّهِ بْنُ أَبِي جَرْوَةَ، قَالَ: وَقَفْتُ عَلَى عَيْنِ الزَّارَةِ، ثُمَّ قَالَ: اللهُمَّ اغْفِرْ لِعَبْدِ الْقَيْسِ إِذْ أَسْلَمُوا طَائِعِينَ غَيْرَ كَارِهِينَ غَيْرَ خَزَايَا وَلَا مَوْتُورِينَ إِذْ بَعْضُ قَوْمِنَا لَا يسلموا حَتَّى يُخْزَوْا وَيُوتَرُوا قَالَ: وَابْتَهَلَ وَجْهُهُ ههنا مِنَ الْقِبْلَةِ حَتَّى اسْتَقْبَلَ الْقِبْلَةَ، وَقَالَ: إِنَّ خَيْرَ أَهْلِ الْمَشْرِقِ عَبْدُ الْقَيْسِ."],"takhrij":"صحيح: رواه أحمد (17829)، وأبو داود (3695) كلاهما من طريق عوف (هو ابن جميلة)، عن أبي القموص، فذكره. واللفظ لأحمد، وأما أبو داود فذكره مختصرا.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (17829) and Abu Dawud (3695).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Abu al-Qamus Zayd ibn ʿAli said: One of the delegates who came to the Messenger of Allah ﷺ from ʿAbd al-Qays narrated to me. He said: Among the gifts we gave him was a cluster or a water skin containing Taʿdud or Barni dates. He said: “What is this?” We said: “This is a gift.” He said: I think he looked at one date from it, then returned it to its place and said: “Deliver it to the family of Muhammad.” He said: The people asked him about many things until they asked him about drink. He said: “Do not drink from gourds, green jars, hollowed palm trunks, or pitch-coated vessels. Drink from lawful vessels that are tied.” One of us said to him: “O Messenger of Allah, how do you know what gourds, green jars, hollowed palm trunks, and pitch-coated vessels are?” He said: “I do not know what they are. Which place in Hajar is strongest?” We said: “Al-Mushaqqar.” He said: “By Allah, I entered it and took its key.” He said: I had forgotten part of his hadith, then ʿUbaydullah ibn Abi Jarwah reminded me of it. He said: “I stood at the spring of al-Zarah.” Then he said: “O Allah, forgive ʿAbd al-Qays, for they accepted Islam willingly, not unwillingly, neither disgraced nor avenged.” For some of our people do not accept Islam until they are disgraced and avenged. He said: Then he turned his face here toward the direction of prayer until he faced it, and said: “The best of the people of the east are ʿAbd al-Qays.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (17829)، وأبو داود (3695)."},{"num":7511,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ أَنَّهُ أَخْبَرَهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  نَهَى عَنِ الدُّبَّاءِ وَالْمُزَفَّتِ أَنْ يُنْبَذَ فِيهِ."],"takhrij":"متفق عليه: رواه مسلم في الأشربة (1992: 30) عن قتيبة بن سعيد، حدثنا ليث، عن ابن شهاب، عن أنس بن مالك ققال: فذكره.","grade":"متفق عليه","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim (1992:30) and al-Bukhari (5586).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Anas narrated that the Messenger of Allah ﷺ forbade making infusion in gourds and pitch-coated vessels."]},"buhuth":{"en":["The word “gourds” refers to dried gourds. The word “pitch-coated vessels” refers to vessels coated with pitch, which is a type of tar, as mentioned in al-Nihayah."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مسلم (1992:30)، والبخاري (5586). قوله: “الدباء” بضم الدال المهملة وتشديد الباء، وهو القرع اليابس. وقوله: “والمزفت” هو الإناء الذي طلي بالزفت، وهو نوع من القار كما في النهاية."},{"num":7512,"demo":false,"sanad":"","matn":["عَنْ عَلِيٍّ بن أَبِي طَالِبٍ قَالَ: نَهَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الدُّبَّاءِ وَالْمُزَفَّتِ."],"takhrij":"متفق عليه: رواه البخاري في الأشربة (5594)، ومسلم في الأشربة (1194) كلاهما من طريق الأعمش، عن إبراهيم التيمي، عن الحارث بن سويد، عن علي قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5594) and Muslim (1994).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["ʿAli ibn Abi Talib said: The Prophet ﷺ forbade gourds and pitch-coated vessels."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (5594)، ومسلم (1194)."},{"num":7513,"demo":false,"sanad":"","matn":["عن زينب بنت أبي سلمة قالت: نهى رسول الله صلى الله عليه وسلم عن الدباء والحنتم والمقير والمزفت. الحديث."],"takhrij":"صحيح: رواه البخاري في المناقب (3492) عن موسى (هو ابن كليب)، حدثنا عبد الواحد، حدثنا كليب، حدثتني ربيبة النبي صلى الله عليه وسلم وأظنها زينب قالت: فذكرته.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (3492).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Zaynab bint Abi Salamah said: The Messenger of Allah ﷺ forbade gourds, green jars, tar-coated vessels, and pitch-coated vessels. The hadith."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (3492)."},{"num":7514,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عَبَّاسٍ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الدُّبَّاءِ وَالْحَنْتَمِ وَالْمُزَفَّتِ وَالنَّقِيرِ."],"takhrij":"صحيح: رواه مسلم في الأشربة (1995: 40) عن أبي بكر بن أبي شيبة، حدثنا علي بن مُسهر، عن الشيباني، عن حبيب، عن سعيد بن جبير، عن ابن عباس قال: فذكره.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1995:40).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Ibn ʿAbbas said: The Messenger of Allah ﷺ forbade gourds, green jars, pitch-coated vessels, and hollowed palm trunks."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1995:40)."},{"num":7515,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  نَهَى عَنِ الدُّبَّاءِ وَالْحَنْتَمِ، وَالنَّقِيرِ، وَالْمُزَفَّتِ."],"takhrij":"صحيح: رواه مسلم في الأشربة (1996: 44) عن يحيى بن أيوب، حدثنا ابن علية، أخبرنا سعيد بن أبي عروبة، عن قتادة، عن أبي نضرة، عن أبي سعيد الخدري قال: فذكره.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1996:44).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Abu Saʿid al-Khudri narrated that the Messenger of Allah ﷺ forbade gourds, green jars, hollowed palm trunks, and pitch-coated vessels."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1996:44)."},{"num":7516,"demo":false,"sanad":"","matn":["عَنْ سَعِيدِ بْنِ جُبَيْرٍ قَالَ:  أَشْهَدُ عَلَى ابْنِ عُمَرَ، وَابْنِ عَبَّاسٍ أَنَّهُمَا شَهِدَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ الدُّبَّاءِ، وَالْحَنْتَمِ، وَالْمُزَفَّتِ، وَالنَّقِيرِ."],"takhrij":"صحيح: رواه مسلم في الأشربة (1997: 46) من طريق مروان بن معاوية، عن منصور بن حيان، عن سعيد بن جبير قال: فذكره.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1997:46).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Saʿid ibn Jubayr said: I testify concerning Ibn ʿUmar and Ibn ʿAbbas that they testified that the Messenger of Allah ﷺ forbade gourds, green jars, pitch-coated vessels, and hollowed palm trunks."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1997:46)."},{"num":7517,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن عُمَرَ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَطَبَ النَّاسَ فِي بَعْضِ مَغَازِيهِ. قَالَ عَبْدُ اللَّهِ بْنُ عُمَرَ: فَأَقْبَلْتُ نَحْوَهُ، فَانْصَرَفَ قَبْلَ أَنْ أَبْلُغَهُ، فَسَأَلْتُ مَاذَا قَالَ؟ فَقِيلَ لِي: نَهَى أَنْ يُنْبَذَ فِي الدُّبَّاءِ وَالْمُزَفَّتِ.","وفي رواية: \"نهى عن المزفت والقرع\"."],"takhrij":"صحيح: رواه مالك في الأشربة (5) عن نافع، عن عبد الله بن عمر فذكره.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (5), Muslim (1997:48), and the other narration is from al-Nasa’i (5631).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Ibn ʿUmar narrated that the Messenger of Allah ﷺ addressed the people during one of his campaigns. ʿAbdullah ibn ʿUmar said: I came toward him, but he finished before I reached him, so I asked what he had said. It was said to me: “He forbade making infusion in gourds and pitch-coated vessels.” In another narration: “He forbade pitch-coated vessels and gourds.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مالك (5)، ومسلم (1997:48)، والرواية الأخرى للنسائي nasai(5631)."},{"num":7518,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : لَا تَنْتَبِذُوا فِي الدُّبَّاءِ وَ لَا فِي الْمُزَفَّتِ، ثُمَّ يَقُولُ أبوهريرة: وَاجْتَنِبُوا الْحَنَاتِمَ."],"takhrij":"صحيح: رواه مسلم في الأشربة (1993: 31) من طريق عمرو الناقد، حدثنا سفيان بن عيينة، عن الزهري قال: وأخبره أبو سلمة أنه سمع أبا هريرة يقول: فذكره.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1993:31).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Do not make infusion in gourds or pitch-coated vessels.” Then Abu Hurayrah would say: “And avoid green jars.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1993:31)."},{"num":7519,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : أَنَّهُ نَهَى عَنِ الْمُزَفَّتِ وَالْحَنْتَمِ وَالنَّقِيرِ، قَالَ: قِيلَ: لِأَبِي هُرَيْرَةَ: مَا الْحَنْتَمُ؟ قَالَ: الْجِرَارُ الْخُضْرُ. وَزَادَ فِي رِوَايَةِ: \"الدباء\"."],"takhrij":"صحيح: رواه مسلم في الأشربة (1993: 32) عن محمد بن حاتم، حدثنا بهز، حدثنا وهيب، عن سهيل، عن أبيه، عن أبي هريرة قال: فذكره.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1993:32), and the other narration is from al-Nasa’i (5653).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Abu Hurayrah narrated from the Prophet ﷺ that he forbade pitch-coated vessels, green jars, and hollowed palm trunks. He said: It was said to Abu Hurayrah: “What are green jars?” He said: “Green earthenware jars.” In another narration, “gourds” is added."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1993:32)، والرواية الأخرى للنسائي nasai(5653)."},{"num":7520,"demo":false,"sanad":"","matn":["عَنْ ابْنَ عُمَرَ قال: نَهَى رَسُولُ اللهِ صلى الله عليه وسلم عَنِ الْحَنْتَمِ وَالدُّبَّاءِ وَالْمُزَفَّتِ، قَالَ: سَمِعْتُهُ غَيْرَ مَرَّةٍ.","وزاد في رواية قال: وأراه قال: \"والنقير\".","وفي رواية جعل \"الجر\" مكان \"الحنتم\" وزاد: انتبذوا في الأسقية."],"takhrij":"صحيح: رواه مسلم في الأشربة (1997: 54) من طريق محمد بن جعفر، حدثنا شعبة، عن محارب بن دثار قال: سمعت ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1997:54, 55).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar said: The Messenger of Allah ﷺ forbade green jars, gourds, and pitch-coated vessels. He said: I heard him more than once. In another narration, he added: “And I think he said: ‘hollowed palm trunks.’”","In another narration, “earthenware jars” appears in place of “green jars,” and he added: “Make infusion in leather water skins.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1997:54، 55)."},{"num":7521,"demo":false,"sanad":"","matn":["عن زَاذَانَ قَالَ:  قُلْتُ لِابْنِ عُمَرَ، حَدِّثْنِي بِمَا نَهَى عَنْهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنَ الْأَشْرِبَةِ بِلُغَتِكَ، وَفَسِّرْهُ لِي بِلُغَتِنَا، فَإِنَّ لَكُمْ لُغَةً سِوَى لُغَتِنَا. فَقَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْحَنْتَمِ، وَهِيَ الْجَرَّةُ، وَعَنِ الدُّبَّاءِ، وَهِيَ الْقَرْعَةُ، وَعَنِ الْمُزَفَّتِ، وَهُوَ الْمُقَيَّرُ، وَعَنِ النَّقِيرِ، وَهِْيَ النَّخْلَةُ تُنْسَحُ نَسْحًا، وَتُنْقَرُ نَقْرًا، وَأَمَرَ أَنْ يُنْتَبَذَ فِي الْأَسْقِيَةِ."],"takhrij":"صحيح: رواه مسلم في الأشربة (1997: 57) عن عبيد الله بن معاذ، حدثنا أبي، حدثنا شعبة، عن عمرو بن مرة، حدثني زاذان به.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1997:57).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Zadhan said: I said to Ibn ʿUmar: “Narrate to me what the Prophet ﷺ forbade among drinks in your language, and explain it to me in our language, for you have a language different from ours.” He said: The Messenger of Allah ﷺ forbade green jars, which are earthenware jars; gourds, which are dried gourds; pitch-coated vessels, which are coated with tar; and hollowed palm trunks, which are palm trunks stripped and hollowed out. He commanded that infusion be made in leather water skins."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1997:57)."},{"num":7522,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، وَابْنِ عُمَرَ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  نَهَى عَنِ النَّقِيرِ، وَالْمُزَفَّتِ، وَالدُّبَّاءِ."],"takhrij":"صحيح: رواه مسلم في الأشربة (1998: 59) من طريق زهير أبي خيثمة، عن أبي الزبير، عن جابر وابن عمر قالا: فذكراه.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1998:59).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Jabir ibn ʿAbdullah and Ibn ʿUmar narrated that the Messenger of Allah ﷺ forbade hollowed palm trunks, pitch-coated vessels, and gourds."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1998:59)."},{"num":7523,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى أَنْ يُنْبَذَ فِي الدُّبَّاءِ وَالْمُزَفَّتِ."],"takhrij":"حسن: رواه مالك في الأشربة (6) عن العلاء بن عبد الرحمن بن يعقوب، عن أبيه، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Malik (6).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ forbade making infusion in gourds and pitch-coated vessels."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه مالك (6)."},{"num":7524,"demo":false,"sanad":"","matn":["عَنْ عَلِيٍّ بن أَبِي طَالِبٍ قَالَ: نَهَانَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الدُّبَّاءِ وَالْحَنْتَمِ وَالنَّقِيرِ وَالْجِعَةِ."],"takhrij":"صحيح: رواه أبو داود (3697)، والنسائي (5171، 5171) وأحمد (963، 1163) كلهم من طرق عن إسماعيل بن سُميع، ثنا مالك بن عمير، عن علي فذكره.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3697), al-Nasa’i (5171), and Ahmad (963, 1163). The wording is from Abu Dawud.","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["ʿAli ibn Abi Talib said: The Messenger of Allah ﷺ forbade us from gourds, green jars, hollowed palm trunks, and barley beer."]},"buhuth":{"en":["His statement, “barley beer,” refers to an intoxicating drink made from barley, as mentioned in al-Nihayah."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (3697)، والنسائي (5171)، وأحمد (963، 1163). واللفظ لأبي داود."},{"num":7525,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ الدُّبَّاءِ."],"takhrij":"صحيح: رواه النسائي (5624) عن محمود بن غيلان، ثنا أبو داود (هو الطيالسي)، ثنا شعبة، عن إبراهيم بن ميسرة، عن طاوس، عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (5624).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Ibn ʿUmar narrated that the Messenger of Allah ﷺ forbade gourds."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (5624)."},{"num":7526,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ زَيْدٍ، وَعِكْرِمَةَ، أَنَّهُمَا كَانَا يَكْرَهَانِ الْبُسْرَ وَحْدَهُ، وَيَأْخُذَانِ ذَلِكَ عَنِ ابْنِ عَبَّاسٍ. وَقَالَ ابْنُ عَبَّاسٍ أَخْشَى أَنْ يَكُونَ الْمُزَّاءَ الَّذِي نُهِيَتْ عَنْهُ عَبْدُ الْقَيْسِ. فَقُلْتُ لِقَتَادَةَ مَا الْمُزَّاءُ قَالَ النَّبِيذُ فِي الْحَنْتَمِ وَالْمُزَفَّتِ."],"takhrij":"حسن: رواه أبوداود (3709) عن محمد بن بشار، ثنا معاذ بن هشام، قال: حدثني أبي، عن قتادة، عن جابر بن زيد وعكرمة به.","grade":"حسن","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3709). It was also said in explanation of “muzza’” that it is made by mixing unripe dates and dates, as mentioned in al-Nihayah.","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Jabir ibn Zayd and ʿIkrimah disliked making drink from unripe dates alone, and they took that from Ibn ʿAbbas. Ibn ʿAbbas said: “I fear that it may be the muzza’ from which ʿAbd al-Qays were forbidden.” I said to Qatadah: “What is muzza’?” He said: “Infusion made in green jars and pitch-coated vessels.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3709). وقيل في تفسير “المزاء” أيضا أنها من خلط البسر والتمر كما في النهاية."},{"num":7527,"demo":false,"sanad":"","matn":["عَنِ الْفُضَيْلِ بْنِ زَيْدٍ الرَّقَاشِيِّ، قَالَ: كُنَّا عِنْدَ عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ، قَالَ: فَتَذَاكَرْنَا الشَّرَابَ، فَقَالَ: الْخَمْرُ حَرَامٌ. قُلْتُ لَهُ: الْخَمْرُ حَرَامٌ فِي كِتَابِ اللَّهِ عَزَّ وَجَلَّ. قَالَ: فَأَيشْ تُرِيدُ، تُرِيدُ مَا سَمِعْتُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنْهَى عَنِ الدُّبَّاءِ وَالْحَنْتَمِ وَالْمُزَفَّتِ قَالَ: قُلْتُ: مَا الْحَنْتَمُ؟ قَالَ: كُلُّ خَضْرَاءَ وَبَيْضَاءَ. قَالَ: قُلْتُ: مَا الْمُزَفَّتُ؟ قَالَ: كُلُّ مُقَيَّرٍ مِنْ زِقٍّ أَوْ غَيْرِهِ."],"takhrij":"حسن: رواه أحمد (16795) عن يونس بن محمد، ثنا عبد الواحد، ثنا عاصم الأحول، عن الفضيل بن زيد الرقاشي قال: فذكره.","grade":"حسن","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (16795).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Fudayl ibn Zayd al-Raqashi said: We were with ʿAbdullah ibn Mughaffal and discussed drink. He said: “Wine is forbidden.” I said to him: “Wine is forbidden in the Book of Allah, the Mighty and Majestic.” He said: “What do you want? Do you want what I heard from the Messenger of Allah ﷺ? I heard the Messenger of Allah ﷺ forbid gourds, green jars, and pitch-coated vessels.” I said: “What are the green jars?” He said: “Every green or white jar.” I said: “What are pitch-coated vessels?” He said: “Anything coated with pitch, whether a leather water skin or something else.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (16795)."},{"num":7528,"demo":false,"sanad":"","matn":["عَنْ مَيْمُونَةَ، زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَنَّهُ قَالَ: لَا تَنْبِذُوا فِي الدُّبَّاءِ، وَلَا فِي الْمُزَفَّتِ، وَلَا فِي الْحَنْتَمِ، وَلَا فِي النَّقِيرِ، قَالَ عَبْدُ الرَّحْمَنِ: وَلَا فِي الْجِرَارِ، وَكُلُّ مُسْكِرٍ حَرَامٌ."],"takhrij":"حسن: رواه أحمد (26823)، والطبراني في الكبير (23/439) من طريق زهير بن محمد، عن عبد الله بن محمد بن عقيل، عن القاسم بن محمد، عن عائشة.","grade":"حسن","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (26823) and al-Tabarani in al-Kabir (23/439).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Maymunah, the wife of the Prophet ﷺ, narrated that he said: “Do not make infusion in gourds, pitch-coated vessels, green jars, hollowed palm trunks, or earthenware jars. Every intoxicant is forbidden.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (26823)، والطبراني في الكبير (23/439)."},{"num":7529,"demo":false,"sanad":"","matn":["عَنْ أَبِي شِمْرٍ الضُّبَعِيِّ، قَالَ: سَمِعْتُ عَائِذَ بْنَ عَمْرٍو، يَنْهَى عَنِ الدُّبَّاءِ، وَالْحَنْتَمِ، وَالْمُزَفَّتِ، وَالنَّقِيرِ، فَقُلْتُ لَهُ: عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ فَقَالَ: نَعَمْ."],"takhrij":"حسن: رواه أحمد (20638)، والطبراني في الكبير (18/18-19) كلاهما من طريق شعبة، عن أبي شمر الضبعي قال: فذكره.","grade":"حسن","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (20638) and al-Tabarani in al-Kabir (18/18–19).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Abu Shamir al-Dubʿī said: I heard ʿĀ’idh ibn ʿAmr forbidding gourds, green jars, pitch-coated vessels, and hollowed palm trunks. I said to him: “Was this from the Prophet ﷺ?” He said: “Yes.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (20638)، والطبراني في الكبير (18/18-19)."},{"num":7530,"demo":false,"sanad":"","matn":["عن عَبْدِ الرَّحْمَنِ بن جوشن، قَالَ: حَدَّثَنِي أَبِي، قَالَ: كَانَ أَبُو بَكْرَةَ يُنْتَبَذُ لَهُ فِي جَرٍّ، فَقَدِمَ أَبُو بَرْزَةَ مِنْ غَيْبَةٍ كَانَ غَابَهَا، فَنَزَلَ بِمَنْزِلِ أَبِي بَكْرَةَ قَبْلَ أَنْ يَأْتِيَ مَنْزِلَهُ، فَلَمْ يَجِدْ أَبَا بَكْرَةَ فِي مَنْزِلِهِ، فَوَقَفَ عَلَى امْرَأَةٍ لَهُ يُقَالُ لَهَا: مَيْسَةُ، فَسَأَلَهَا عَنْ أَبِي بَكْرَةَ، وَعَنْ حَالِهِ، وَنَظَرَ، فَأَبْصَرَ الْجَرَّةَ الَّتِي فِيهَا النَّبِيذُ، فَقَالَ: مَا فِي هَذِهِ الْجَرَّةِ؟ قَالَتْ: نَبِيذٌ لِأَبِي بَكْرَةَ، فَقَالَ: لَوَدِدْتُ أَنَّكِ جَعَلْتِيهِ فِي سِقَاءٍ! ثُمَّ خَرَجَ، فَأَمَرَتْ بِالنَّبِيذِ، فَحُوِّلَ فِي سِقَاءٍ، ثُمَّ عَلَّقَتْهُ، فَجَاءَ أَبُو بَكْرَةَ، فَأَخْبَرَتْهُ عَنْ أَبِي بَرْزَةَ، وَعَنْ قُدُومِهِ، ثُمَّ أَبْصَرَ السِّقَاءَ فَقَالَ: مَا هَذَا السِّقَاءُ؟ فَقَالَتْ: قَالَ أَبُو بَرْزَةَ كَذَا وَكَذَا، فَحَوَّلْتُ نَبِيذَكَ فِي السِّقَاءِ. فَقَالَ: مَا أَنَا بِشَارِبٍ مِنْهُ شَيْئًا، آللهِ إِنْ جَعَلْتِ الْعَسَلَ فِي جَرٍّ لَيَحْرُمَنَّ عَلَيَّ، وَلَئِنْ جَعَلْتِ الْخَمْرَ فِي سِقَاءٍ لَيَحِلَّنَّ لِي، إِنَّا قَدْ عَرَفْنَا الَّذِي نُهِينَا عَنْهُ، نُهِينَا عَنِ الدُّبَّاءِ وَالنَّقِيرِ، وَالْحَنْتَمِ، وَالْمُزَفَّتِ؛ فَأَمَّا الدُّبَّاءُ فَإِنَّا مَعْشَرَ ثَقِيفَ بِالطَّائِفِ كُنَّا نَأْخُذُ الدُّبَّاءَ، فَنَخْرُطُ فِيهَا عَنَاقِيدَ الْعِنَبِ، ثُمَّ نَدْفِنُهَا، ثُمَّ نَتْرُكُهَا، حَتَّى تَهْدِرَ، ثُمَّ تَمُوتَ، وَأَمَّا النَّقِيرُ فَإِنَّ أَهْلَ الْيَمَامَةِ كَانُوا يَنْقُرُونَ أَصْلَ النَّخْلَةِ فَيَشْدَخُونَ فِيهِ الرُّطَبَ وَالْبُسْرَ، ثُمَّ يَدَعُونَهُ، حَتَّى يَهْدِرَ، ثُمَّ يَمُوتَ، وَأَمَّا الْحَنْتَمُ فَجِرَارٌ كَانَ يُحْمَلُ إِلَيْنَا فِيهَا الْخَمْرُ، وَأَمَّا الْمُزَفَّتُ فَهِيَ هَذِهِ الْأَوْعِيَةُ الَّتِي فِيهَا هَذَا الزِّفْتُ."],"takhrij":"حسن: رواه أبو داود الطيالسي (923)، والبزار (3689)، والبيهقي (17479)، وابن حبان (5407) كلهم من طريق عيينة بن عبد الرحمن بن جوشن، عن أبيه فذكره.","grade":"حسن","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud al-Tayalisi (923), al-Bazzar (3689), al-Bayhaqi (8/309), and authenticated by Ibn Hibban (5407).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["ʿAbd al-Rahman ibn Jawshan said: Infusion used to be made for Abu Bakrah in an earthenware jar. Abu Barzah returned from an absence and stopped at Abu Bakrah’s house before going to his own house. He did not find Abu Bakrah at home, so he came upon a wife of his named Maysah. He asked her about Abu Bakrah and his condition. Then he looked and saw the jar that contained the infusion. He said: “What is in this jar?” She said: “Infusion for Abu Bakrah.” He said: “I wish you had put it in a leather water skin.” Then he left. She ordered that the infusion be transferred into a leather water skin, then she hung it up. Abu Bakrah came, and she told him about Abu Barzah and his arrival. Then he saw the water skin and said: “What is this water skin?” She said: “Abu Barzah said such-and-such, so I transferred your infusion into the water skin.” He said: “I will not drink any of it. By Allah, if I put honey in an earthenware jar, would it become forbidden for me? And if I put wine in a leather water skin, would it become lawful for me? We know what we were forbidden from. We were forbidden from gourds, hollowed palm trunks, green jars, and pitch-coated vessels. As for gourds, we, the people of Thaqif in Ta’if, used to take gourds, strip clusters of grapes into them, bury them, and leave them until they fermented loudly, then settled. As for hollowed palm trunks, the people of Yamamah used to hollow out the base of a palm tree, crush fresh and unripe dates in it, and leave it until it fermented loudly, then settled. As for green jars, they were jars in which wine used to be brought to us. As for pitch-coated vessels, they are these containers that contain this pitch.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود الطيالسي (923)، والبزار (3689)، والبيهقي (17479)، وصححه ابن حبان (5407)."},{"num":7531,"demo":false,"sanad":"","matn":["عَنِ عُيَيْنَةَ بْنِ عَبْدِ الرَّحْمَنِ، حَدَّثَنِي أَبِي، قَالَ: جَاءَ رَجُلٌ إِلَى ابْنِ عَبَّاسٍ، فَقَالَ: إِنِّي رَجُلٌ مِنْ أَهْلِ خُرَاسَانَ، وَإِنَّ أَرْضَنَا أَرْضٌ بَارِدَةٌ، فَذَكَرَ مِنْ ضُرُوبِ الشَّرَابِ، فَقَالَ: اجْتَنِبْ مَا أَسْكَرَ مِنْ زَبِيبٍ، أَوْ تَمْرٍ، أَوْ مَا سِوَى ذَلِكَ، قَالَ: مَا تَقُولُ فِي نَبِيذِ الْجَرِّ؟ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ نَبِيذِ الْجَرِّ."],"takhrij":"حسن: رواه النسائي (5616)، وأحمد (2009) كلاهما عن عيينة بن عبدالرحمن به فذكره. والسياق لأحمد.","grade":"حسن","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (5616) and Ahmad (2009). The wording is from Ahmad.","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["ʿUyaynah ibn ʿAbd al-Rahman narrated from his father: A man came to Ibn ʿAbbas and said: “I am a man from Khurasan, and our land is cold,” then he mentioned different kinds of drink. He said: “Avoid whatever intoxicates, whether from raisins, dates, or anything else.” He said: “What do you say about infusion made in earthenware jars?” He said: “The Messenger of Allah ﷺ forbade infusion made in earthenware jars.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (5616)، وأحمد (2009). والسياق لأحمد."},{"num":7532,"demo":false,"sanad":"","matn":["عَنْ دُلْجَةَ بْنِ قَيْسٍ، أَنَّ الْحَكَمَ الْغِفَارِيَّ، قَالَ لِرَجُلٍ: أَوْ قَالَ لَهُ رَجُلٌ: أَتَذْكُرُ حِينَ نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ النَّقِيرِ، وَالْمُقَيَّرِ، أَوْ أَحَدِهِمَا، وَعَنِ الدُّبَّاءِ، وَالْحَنْتَمِ؟ قَالَ: نَعَمْ، وَأَنَا أَشْهَدُ عَلَى ذَلِكَ."],"takhrij":"حسن: رواه أحمد (17860)، والطبراني في الكبير (3/235) كلاهما من طريق سليمان التيمي، عن أبي تميمة، عن دلجة بن قيس قال: فذكره.","grade":"حسن","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (17860) and al-Tabarani in al-Kabir (3/235).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Duljah ibn Qays narrated that al-Hakam al-Ghifari said to a man — or a man said to him: “Do you remember when the Messenger of Allah ﷺ forbade hollowed palm trunks and pitch-coated vessels — or one of them — as well as gourds and green jars?” He said: “Yes, and I bear witness to that.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (17860)، والطبراني في الكبير (3/235)."},{"num":7533,"demo":false,"sanad":"","matn":["عن عَائِشَةَ قَالَتْ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنْهَى عَنْ شَرَابٍ صُنِعَ فِي دُبُّاءٍ، أَوْ حَنْتَمٍ، أَوْ مُزَفَّتٍ، لاَ يَكُونُ زَيْتًا أَوْ خَلاًّ."],"takhrij":"حسن: رواه النسائي (5636) عن سويد، أنبأنا عبد الله (هو ابن المبارك) عن عون بن صالح البارقي، عن زينب بنت نصر وجميلة بنت عباد، أنهما سمعتا عائشة فذكرته.","grade":"حسن","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (5636).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["ʿA’ishah said: I heard the Messenger of Allah ﷺ forbidding a drink made in a gourd, green jar, or pitch-coated vessel, unless it was oil or vinegar."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (5636)."},{"num":7534,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ بن أَبِي أَوْفَى رَضِيَ اللَّهُ عَنْهُمَا قَالَ: نَهَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْجَرِّ الأَخْضَرِ. قُلْتُ: أَنَشْرَبُ فِي الأَبْيَضِ؟ قَالَ: لاَ."],"takhrij":"صحيح: رواه البخاري في الأشربة (5596) عن موسى بن إسماعيل، حدثنا عبدالواحد، ثنا الشيباني، قال: سمعت عبد الله بن أبي أوفى قال: فذكره.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5596). “Earthenware jar” refers to a vessel made from pottery.","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["ʿAbdullah ibn Abi Awfa said: The Prophet ﷺ forbade green earthenware jars. I said: “May we drink from white ones?” He said: “No.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (5596). والجر والجرار جمع جرة، وهو الإناء المصنوع من الفخار."},{"num":7535,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  نَهَى عَنِ الْجَرِّ أَنْ يُنْبَذَ فِيهِ."],"takhrij":"صحيح: رواه مسلم في الأشربة (1996: 43) من طريق سليمان التيمي، عن أبي نضرة، عن أبي سعيد قال: فذكره.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1996:43).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Abu Saʿid al-Khudri narrated that the Messenger of Allah ﷺ forbade making infusion in earthenware jars."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1996:43)."},{"num":7536,"demo":false,"sanad":"","matn":["عَنْ سَعِيدِ بْنِ جُبَيْرٍ قَالَ:  سَأَلْتُ ابْنَ عُمَرَ عَنْ نَبِيذِ الْجَرِّ؟ فَقَالَ: حَرَّمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَبِيذَ الْجَرِّ، فَأَتَيْتُ ابْنَ عَبَّاسٍ فَقُلْتُ: أَلَا تَسْمَعُ مَا يَقُولُ ابْنُ عُمَرَ؟ قَالَ: وَمَا يَقُولُ؟ قُلْتُ: قَالَ: حَرَّمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَبِيذَ الْجَرِّ. فَقَالَ: صَدَقَ ابْنُ عُمَرَ، حَرَّمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَبِيذَ الْجَرِّ. فَقُلْتُ: وَأَيُّ شَيْءٍ نَبِيذُ الْجَرِّ؟ فَقَالَ: كُلُّ شَيْءٍ يُصْنَعُ مِنَ الْمَدَرِ."],"takhrij":"صحيح: رواه مسلم في الأشربة (1997: 47) عن شيبان بن فروخ، حدثنا جرير بن حازم، حدثنا يعلى بن حكيم، عن سعيد بن جبير قال: فذكره.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1997:47).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Saʿid ibn Jubayr said: I asked Ibn ʿUmar about infusion made in earthenware jars. He said: “The Messenger of Allah ﷺ forbade infusion made in earthenware jars.” I came to Ibn ʿAbbas and said: “Do you not hear what Ibn ʿUmar says?” He said: “What does he say?” I said: “The Messenger of Allah ﷺ forbade infusion made in earthenware jars.” He said: “Ibn ʿUmar has spoken the truth. The Messenger of Allah ﷺ forbade infusion made in earthenware jars.” I said: “What is infusion made in earthenware jars?” He said: “Anything made in clay vessels.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1997:47)."},{"num":7537,"demo":false,"sanad":"","matn":["عَنْ ثَابِتٍ قَالَ:  قُلْتُ لِابْنِ عُمَرَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ نَبِيذِ الْجَرِّ؟ قَالَ: فَقَالَ: قَدْ زَعَمُوا ذَاكَ. قُلْتُ: أَنَهَى عَنْهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: قَدْ زَعَمُوا ذَاكَ.","وفي رواية: أن رجلا جاءه فقال: أ نهى النبي صلى الله عليه وسلم أن ينبذ في الجر والدباء؟ قال: نعم."],"takhrij":"صحيح: رواه مسلم في الأشربة (1997: 50) عن يحيى بن يحيى، أخبرنا حماد بن زيد، عن ثابت فذكره. والرواية الأخرى من طريق ابن جريج، أخبرني ابن طاوس، عن أبيه، عن ابن عمر.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1997:50).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Thabit said: I said to Ibn ʿUmar: “Did the Messenger of Allah ﷺ forbid infusion made in earthenware jars?” He said: “They have claimed that.” I said: “Did the Messenger of Allah ﷺ forbid it?” He said: “They have claimed that.” In another narration: A man came to him and said: “Did the Prophet ﷺ forbid making infusion in earthenware jars and gourds?” He said: “Yes.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1997:50)."},{"num":7538,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الجِرار، والدباء، والظروف المزفتة."],"takhrij":"صحيح: رواه النسائي (5635)، وابن ماجه (3408)، وأحمد (10971) كلهم من طرق عن الأوزاعي، عن يحيى بن أبي كثير، عن أبي سلمة، عن أبي هريرة قال: فذكره.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (5635), Ibn Majah (3408), and Ahmad (10971). The wording is from al-Nasa’i.","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ forbade earthenware jars, gourds, and pitch-coated containers."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (5635)، وابن ماجه (3408)، وأحمد (10971). واللفظ للنسائي."},{"num":7539,"demo":false,"sanad":"","matn":["عَنْ قَتَادَةَ، قَالَ: سَأَلْتُ أَنَسًا عَنْ نَبِيذِ الْجَرِّ، فَقَالَ: لَمْ أَسْمَعْ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِيهِ شَيْئًا، قَالَ: وَكَانَ أَنَسٌ يَكْرَهُهُ."],"takhrij":"صحيح: رواه أحمد (13937)، وأبو يعلى (3241)، والبزار 7161) كلهم من طريق أبي داود (هو الطيالسي)، عن شعبة، عن قتادة فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (13937), Abu Yaʿla (3241), and al-Bazzar (7161).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Qatadah said: I asked Anas about infusion made in earthenware jars. He said: “I did not hear anything from the Messenger of Allah ﷺ concerning it.” He said: Anas used to dislike it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (13937)، وأبو يعلى (3241)، والبزار (7161)."},{"num":7540,"demo":false,"sanad":"","matn":["عَنْ سَمُرَةَ، قَالَ: قَامَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَخَطَبَ، فَنَهَى عَنِ الدُّبَّاءِ، وَالْمُزَفَّتِ."],"takhrij":"حسن: رواه أحمد (20186)، والطبراني في الكبير (7/215) كلاهما من طريق عبد الله بن المبارك، عن وقاء بن إياس، عن علي بن ربيعة، عن سمرة بن جندب قال: فذكره.","grade":"حسن","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (20186) and al-Tabarani in al-Kabir (7/215).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Samurah ibn Jundab said: The Prophet ﷺ stood and delivered a sermon, and he forbade gourds and pitch-coated vessels."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (20186)، والطبراني في الكبير (7/215)."},{"num":7541,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الظُّرُوفِ، فَقَالَتِ الأَنْصَارُ: إِنَّهُ لاَ بُدَّ لَنَا مِنْهَا. قَالَ: فَلاَ إِذًا."],"takhrij":"صحيح: رواه البخاري في الأشربة (5592) عن يوسف بن موسى، حدثنا محمد بن عبد الله أبو أحمد الزبيري، حدثنا سفيان، عن منصور، عن سالم (هو ابن أبي الجعد) عن جابر قال: فذكره.","grade":"صحيح","chapter_ar":"باب ترخيص النبي ﷺ في الأوعية والظروف واجتناب المسكر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5592).","chapter_en":"The Prophet’s ﷺ Permission Concerning Vessels and Containers While Avoiding Intoxicants","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Jabir said: The Messenger of Allah ﷺ forbade certain containers. The Ansar said: “They are necessary.” He said: “Then not, in that case.”"]},"buhuth":{"en":["His statement, “Then not, in that case,” is a response meaning: if it is necessary for you, then do not leave them."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (5592). وقوله: “فلا إذن” جواب وجزاء، أي إذا كان كذلك لا بد لكم منها، فلا تدعوها."},{"num":7542,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: لَمَّا نَهَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الأَسْقِيَةِ، قِيلَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَيْسَ كُلُّ النَّاسِ يَجِدُ سِقَاءً، فَرَخَّصَ لَهُمْ فِي الْجَرِّ غَيْرِ الْمُزَفَّتِ."],"takhrij":"متفق عليه: رواه البخاري في الأشربة (5593)، ومسلم في الأشربة (2000: 66) كلاهما من طريق سفيان (هو ابن عيينة)، عن سليمان بن أبي مسلم الأحول، عن مجاهد، عن أبي عياض، عن عبد الله بن عمرو قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب ترخيص النبي ﷺ في الأوعية والظروف واجتناب المسكر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5593) and Muslim (2000:66).","chapter_en":"The Prophet’s ﷺ Permission Concerning Vessels and Containers While Avoiding Intoxicants","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["ʿAbdullah ibn ʿAmr said: When the Prophet ﷺ forbade certain containers, it was said to the Prophet ﷺ: “Not everyone can find a leather water skin.” So he permitted them to use earthenware jars that were not pitch-coated."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (5593)، ومسلم (2000:66)."},{"num":7543,"demo":false,"sanad":"","matn":["عَنْ سَهْلٍ، قَالَ: لَمَّا عَرَّسَ أَبُو أُسَيْدٍ السَّاعِدِيُّ دَعَا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَصْحَابَهُ، فَمَا صَنَعَ لَهُمْ طَعَامًا وَلاَ قَرَّبَهُ إِلَيْهِمْ إِلاَّ امْرَأَتُهُ أُمُّ أُسَيْدٍ، بَلَّتْ تَمَرَاتٍ فِي تَوْرٍ مِنْ حِجَارَةٍ مِنَ اللَّيْلِ، فَلَمَّا فَرَغَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنَ الطَّعَامِ أَمَاثَتْهُ لَهُ فَسَقَتْهُ، تُتْحِفُهُ بِذَلِكَ."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5182)، ومسلم في الأشربة (2006: 87) كلاهما من طريق سعيد بن أبي مريم، حدثنا محمد أبو غسّان، حدثني أبو حازم، عن سهل بن سعد قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب ترخيص النبي ﷺ في الأوعية والظروف واجتناب المسكر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5182) and Muslim (2006:87).","chapter_en":"The Prophet’s ﷺ Permission Concerning Vessels and Containers While Avoiding Intoxicants","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Sahl ibn Saʿd said: When Abu Usayd al-Saʿidi got married, he invited the Prophet ﷺ and his Companions. No one prepared food for them or served it except his wife, Umm Usayd. She had soaked some dates overnight in a stone vessel. When the Prophet ﷺ finished eating, she dissolved it for him and gave it to him to drink, honoring him with it."]},"buhuth":{"en":["His statement, “dissolved it,” means she mixed it until it dissolved. The “stone vessel” is a known vessel mentioned by the Arabs, from which one drinks and from which one may perform ablution. It may be made of copper or stone, as in this hadith. His statement, “honoring him with it,” is the wording in al-Bukhari; in Sahih Muslim it says: “singling him out with it.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[6533],"tks":"متفق عليه: رواه البخاري (5182)، ومسلم (2006:87). وقوله: “أماثته” أي أذابته."},{"num":7544,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ قَالَ:  كَانَ يُنْتَبَذُ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي سِقَاءٍ، فَإِذَا لَمْ يَجِدُوا سِقَاءً نُبذَ لَهُ فِي تَوْرٍ مِنْ حِجَارَةٍ، فَقَالَ بعضُ الْقَوْمِ- وَأَنَا أَسْمَعُ لِأَبِي الزُّبَيْرِ-: مِنْ بِرَامٍ؟ قَالَ: مِنْ بِرَامٍ. وَزَادَ فِي رِوَايَةِ: \"ونهى رسول اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ الدُّبَّاءِ وَالنَّقِيرِ وَالْمُزَفَّتِ\"."],"takhrij":"صحيح: رواه مسلم في الأشربة (1999: 62) من طريق زهير بن أبي خيثمة، عن أبي الزبير، عن جابر قال: فذكره.","grade":"صحيح","chapter_ar":"باب ترخيص النبي ﷺ في الأوعية والظروف واجتناب المسكر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1999:62). The other narration is from al-Nasa’i (5648).","chapter_en":"The Prophet’s ﷺ Permission Concerning Vessels and Containers While Avoiding Intoxicants","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Jabir said: Infusion used to be made for the Messenger of Allah ﷺ in a leather water skin. If they did not find a leather water skin, it was made for him in a stone vessel. One of the people said — while I was listening to Abu al-Zubayr — “Made of stone pots?” He said: “Made of stone pots.” Another narration adds: “The Messenger of Allah ﷺ forbade gourds, hollowed palm trunks, and pitch-coated vessels.”"]},"buhuth":{"en":["His statement, “stone pots,” is the plural of a pot originally made from stone."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1999:62). والرواية الأخرى للنسائي nasai(5648)."},{"num":7545,"demo":false,"sanad":"","matn":["عَنْ بُرَيْدَةَ بْنِ الحُصيب أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  نَهَيْتُكُمْ عَنِ الظُّرُوفِ، وَإِنَّ الظُّرُوفَ أَوْ ظَرْفًا لَا يحلُّ شَيْئًا وَ لَا يُحَرِّمُهُ، وَكُلُّ مُسْكِرٍ حَرَامٌ."],"takhrij":"صحيح: رواه مسلم في الأشربة (977: 64) عن حجاج بن الشاعر، ثنا ضحاك بن مخلد، عن سفيان، عن علقمة بن مرثد، عن ابن بريدة، عن أبيه قال: فذكره.","grade":"صحيح","chapter_ar":"باب ترخيص النبي ﷺ في الأوعية والظروف واجتناب المسكر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (977:64).","chapter_en":"The Prophet’s ﷺ Permission Concerning Vessels and Containers While Avoiding Intoxicants","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Buraydah ibn al-Husayb narrated that the Messenger of Allah ﷺ said: “I forbade you from certain containers, but containers — or a container — do not make anything lawful or unlawful. Every intoxicant is forbidden.”"]}},"tuhfa":{},"full":1,"rep":[7485],"tks":"صحيح: رواه مسلم (977:64)."},{"num":7546,"demo":false,"sanad":"","matn":["عَنْ بُرَيْدَةَ بْنِ الحصيب قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: :  نَهَيْتُكُمْ عَنِ النَّبِيذِ إِلَّا فِي سِقَاءٍ، فَاشْرَبُوا فِي الْأَسْقِيَةِ كُلِّهَا، وَ لاتشربوا مُسْكِرًا."],"takhrij":"صحيح: رواه مسلم في الأشربة (977: 63) من طريق أبي سنان ضِرار بن مرة، عن محارب بن دثار، عن عبد الله بن بريدة، عن أبيه قال: فذكره.","grade":"صحيح","chapter_ar":"باب ترخيص النبي ﷺ في الأوعية والظروف واجتناب المسكر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (977:63).","chapter_en":"The Prophet’s ﷺ Permission Concerning Vessels and Containers While Avoiding Intoxicants","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Buraydah ibn al-Husayb said: The Messenger of Allah ﷺ said: “I forbade you from date infusion except in a leather water skin. So drink from all leather water skins, but do not drink anything intoxicating.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (977:63)."},{"num":7547,"demo":false,"sanad":"","matn":["عَنْ أَبِيهِ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْنَا هُوَ يَسِيرُ إِذْ حَلَّ بِقَوْمٍ فَسَمِعَ لَهُمْ لَغَطًا، فَقَالَ: مَا هَذَا الصَّوْتُ. قَالُوا: يَا نَبِيَّ اللَّهِ لَهُمْ شَرَابٌ يَشْرَبُونَهُ. فَبَعَثَ إِلَى الْقَوْمِ فَدَعَاهُمْ، فَقَالَ: فِي أَىِّ شَىْءٍ تَنْتَبِذُونَ. قَالُوا: نَنْتَبِذُ فِي النَّقِيرِ وَالدُّبَّاءِ وَلَيْسَ لَنَا ظُرُوفٌ. فَقَالَ: لاَ تَشْرَبُوا إِلاَّ فِيمَا أَوْكَيْتُمْ عَلَيْهِ. قَالَ: فَلَبِثَ بِذَلِكَ مَا شَاءَ اللَّهُ أَنْ يَلْبَثَ، ثُمَّ رَجَعَ عَلَيْهِمْ فَإِذَا هُمْ قَدْ أَصَابَهُمْ وَبَاءٌ وَاصْفَرُّوا. قَالَ: مَا لِي أَرَاكُمْ قَدْ هَلَكْتُمْ. قَالُوا: يَا نَبِيَّ اللَّهِ أَرْضُنَا وَبِيئَةٌ، وَحَرَّمْتَ عَلَيْنَا إِلاَّ مَا أَوْكَيْنَا عَلَيْهِ. قَالَ: اشْرَبُوا، وَكُلُّ مُسْكِرٍ حَرَامٌ."],"takhrij":"حسن: رواه النسائي (5655) عن أبي علي محمد بن يحيى بن أيوب المروزي، ثنا عبد الله بن عثمان، ثنا عيسى بن عبيد الكندي خراساني، قال: سمعت عبد الله بن بريدة، عن أبيه قال: فذكره.","grade":"حسن","chapter_ar":"باب ترخيص النبي ﷺ في الأوعية والظروف واجتناب المسكر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (5655).","chapter_en":"The Prophet’s ﷺ Permission Concerning Vessels and Containers While Avoiding Intoxicants","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Buraydah narrated that while the Messenger of Allah ﷺ was traveling, he stopped among some people and heard loud voices from them. He said: “What is this sound?” They said: “O Prophet of Allah, they have a drink that they drink.” He sent for the people and called them. He said: “In what do you make infusion?” They said: “We make infusion in hollowed palm trunks and gourds, and we do not have other containers.” He said: “Do not drink except from what you can tie closed.” He said: This remained for as long as Allah willed. Then he returned to them, and they had been afflicted by disease and had become yellow. He said: “What is the matter with me that I see you ruined?” They said: “O Prophet of Allah, our land is disease-ridden, and you forbade us from everything except what we can tie closed.” He said: “Drink, but every intoxicant is forbidden.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (5655)."},{"num":7548,"demo":false,"sanad":"","matn":["عَنِ ابْنِ مَسْعُودٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنِّي كُنْتُ نَهَيْتُكُمْ عَنْ نَبِيذِ الأَوْعِيَةِ، أَلاَ وَإِنَّ وِعَاءً لاَ يُحَرِّمُ شَيْئًا، كُلُّ مُسْكِرٍ حَرَامٌ."],"takhrij":"حسن: رواه ابن ماجه (3406)، وصحّحه ابن حبان (5409) كلاهما من طريق ابن وهب، أخبرنا ابن جريج، عن أيوب بن هانئ، عن مسروق الأجدع، عن ابن مسعود فذكره.","grade":"حسن","chapter_ar":"باب ترخيص النبي ﷺ في الأوعية والظروف واجتناب المسكر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (3406), and authenticated by Ibn Hibban (5409).","chapter_en":"The Prophet’s ﷺ Permission Concerning Vessels and Containers While Avoiding Intoxicants","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Ibn Masʿud narrated that the Messenger of Allah ﷺ said: “I had forbidden you from infusions made in vessels. Indeed, a vessel does not make anything forbidden, and every intoxicant is forbidden.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (3406)، وصححه ابن حبان (5409)."},{"num":7549,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنِّي نَهَيْتُكُمْ عَنْ زِيَارَةِ الْقُبُورِ فَزُورُوهَا، فَإِنَّ فِيهَا عِبْرَةً، وَنَهَيْتُكُمْ عَنِ النَّبِيذِ فَاشْرَبُوا، وَلَا أُحِلُّ مُسْكِرًا، وَنَهَيْتُكُمْ عَنِ الْأَضَاحِيِّ فَكُلُوا."],"takhrij":"حسن: رواه أحمد (11329) عن يحيى بن آدم، ثنا ابن المبارك، عن أسامة، عن محمد بن يحيى بن حبّان، عن عمه، عن أبي سعيد الخدري قال: فذكره.","grade":"حسن","chapter_ar":"باب ترخيص النبي ﷺ في الأوعية والظروف واجتناب المسكر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (11329).","chapter_en":"The Prophet’s ﷺ Permission Concerning Vessels and Containers While Avoiding Intoxicants","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Abu Saʿid al-Khudri said: The Messenger of Allah ﷺ said: “I had forbidden you from visiting graves, so visit them, for in them there is a lesson. I had forbidden you from date infusion, so drink, but I do not permit any intoxicant. And I had forbidden you from sacrificial meat, so eat.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[3894],"tks":"حسن: رواه أحمد (11329)."},{"num":7550,"demo":false,"sanad":"","matn":["عن طلق بن عَلِيٍّ قَالَ: جَلَسْنَا عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَجَاءَ وَفْدُ عَبْدِ الْقَيْسِ، فَقَالَ: مَا لَكُمْ قَدِ اصْفَرَّتْ أَلْوَانُكُمْ، وَعَظُمَتْ بُطُونُكُمْ، وَظَهَرَتْ عُرُوقُكُمْ؟ قَالَ: قَالُوا: أَتَاكَ سَيِّدُنَا، فَسَأَلَكَ عَنْ شَرَابٍ كَانَ لَنَا مُوَافِقًا فَنَهَيْتَهُ عَنْهُ، وَكُنَّا بِأَرْضٍ وَخِمَةٍ، قَالَ: فَاشْرَبُوا مَا طَابَ لَكُمْ."],"takhrij":"حسن: رواه ابن أبي شيبة (24368) عن ملازم بن عمرو، عن عُجيبة بن عبد الحميد، عن عمه قيس بن طلق، عن أبيه طلق بن علي قال: فذكره.","grade":"حسن","chapter_ar":"باب ترخيص النبي ﷺ في الأوعية والظروف واجتناب المسكر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Abi Shaybah (24368) and al-Tabarani (8256).","chapter_en":"The Prophet’s ﷺ Permission Concerning Vessels and Containers While Avoiding Intoxicants","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Talq ibn ʿAli said: We were sitting with the Prophet ﷺ when the delegation of ʿAbd al-Qays came. He said: “What is the matter with you that your complexions have turned yellow, your bellies have grown large, and your veins have become prominent?” They said: “Our leader came to you and asked you about a drink that suited us, and you forbade him from it, while we are in a feverish land.” He said: “Then drink what is wholesome for you.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[9771],"tks":"حسن: رواه ابن أبي شيبة (24368)، والطبراني (8256)."},{"num":7551,"demo":false,"sanad":"","matn":["عن المختار بن فلفل قَالَ: سَأَلْتُ أَنَسَ بْنَ مَالِكٍ عَنِ الشُّرْبِ فِي الْأَوْعِيَةِ، فَقَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْمُزَفَّتَةِ، وَقَالَ: كُلُّ مُسْكِرٍ حَرَامٌ، قَالَ: قُلْتُ: وَمَا الْمُزَفَّتَةُ؟ قَالَ: الْمُقَيَّرَةُ. قَالَ: قُلْتُ: فَالرَّصَاصُ وَالْقَارُورَةُ؟ قَالَ: مَا بَأْسٌ بِهِمَا قَالَ: قُلْتُ: فَإِنَّ نَاسًا يَكْرَهُونَهُمَا، قَالَ: دَعْ مَا يَرِيبُكَ إِلَى مَا لَا يَرِيبُكَ، فَإِنَّ كُلَّ مُسْكِرٍ حَرَامٌ. قَالَ: قُلْتُ لَهُ: صَدَقْتَ. السُّكْرُ حَرَامٌ، فَالشَّرْبَةُ وَالشَّرْبَتَانِ، عَلَى طَعَامِنَا. قَالَ: مَا أَسْكَرَ كَثِيرُهُ، فَقَلِيلُهُ حَرَامٌ، وَقَالَ: الْخَمْرُ مِنَ الْعِنَبِ، وَالتَّمْرِ، وَالْعَسَلِ، وَالْحِنْطَةِ، وَالشَّعِيرِ، وَالذُّرَةِ، فَمَا خَمَّرْتَ مِنْ ذَلِكَ فَهِيَ الْخَمْرُ."],"takhrij":"حسن: رواه أحمد (12099)، وأبو يعلى (3966) كلاهما من طريق عبد الله بن إدريس، عن المختار بن فلفل فذكره، والسياق لأحمد.","grade":"حسن","chapter_ar":"باب ترخيص النبي ﷺ في الأوعية والظروف واجتناب المسكر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (12099) and Abu Yaʿla (3966). The wording is from Ahmad.","chapter_en":"The Prophet’s ﷺ Permission Concerning Vessels and Containers While Avoiding Intoxicants","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Al-Mukhtar ibn Fulful said: I asked Anas ibn Malik about drinking from vessels. He said: “The Messenger of Allah ﷺ forbade pitch-coated vessels, and said: ‘Every intoxicant is forbidden.’” I said: “What are pitch-coated vessels?” He said: “Those coated with tar.” I said: “What about vessels made of lead and glass?” He said: “There is no harm in them.” I said: “Some people dislike them.” He said: “Leave what causes you doubt for what does not cause you doubt, for every intoxicant is forbidden.” I said to him: “You have spoken the truth. Intoxication is forbidden, but what about one drink or two drinks with our food?” He said: “Whatever intoxicates in large amounts, a small amount of it is forbidden.” And he said: “Wine is from grapes, dates, honey, wheat, barley, and millet. Whatever ferments from that is wine.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (12099)، وأبو يعلى (3966)، والسياق لأحمد."},{"num":7552,"demo":false,"sanad":"","matn":["عَنْ أَبِي مَالِكٍ الْأَشْجَعِيِّ، عَنْ أَبِيهِ، قَالَ: كَانَ نَبِيذٌ لِرَسُولِ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  فِي تَوْرٍ مِنْ حِجَارَةٍ."],"takhrij":"حسن: رواه الطبراني في الكبير (8182) عن محمد بن عبدوس بن كامل، ثنا أحمد بن إبراهيم الموصلي، ثنا خلف بن خليفة، عن أبي مالك الأشجعي، عن أبيه فذكره.","grade":"حسن","chapter_ar":"باب ترخيص النبي ﷺ في الأوعية والظروف واجتناب المسكر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Kabir (8/379).","chapter_en":"The Prophet’s ﷺ Permission Concerning Vessels and Containers While Avoiding Intoxicants","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Abu Malik al-Ashjaʿi narrated from his father that infusion used to be made for the Messenger of Allah ﷺ in a stone vessel."]},"buhuth":{"en":["The conclusion of the hadiths forbidding making infusion in these vessels is that the prohibition was abrogated, and making infusion in these vessels became permitted because other containers were not available to them. The matter became limited to avoiding intoxicants, and vessels neither make anything lawful nor unlawful. Rather, what is forbidden is the intoxicant itself, however intoxication occurs."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (8182)."},{"num":7553,"demo":false,"sanad":"","matn":["عن ابْنِ عَبَّاسٍ يَقُولُ:  كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُنْتَبَذُ لَهُ أَوَّلَ اللَّيْلِ، فَيَشْرَبُهُ إِذَا أَصْبَحَ يَوْمَهُ ذَلِكَ، وَاللَّيْلَةَ الَّتِي تَجِيءُ، وَالْغَدَ وَاللَّيْلَةَ الْأُخْرَى، وَالْغَدَ إِلَى الْعَصْرِ، فَإِنْ بَقِيَ شَيْءٌ سَقَاهُ الْخَادِمَ أَوْ أَمَرَ بِهِ فَصُبَّ.","وفي لفظ: كَانَ رَسُولُ اللهِ صلى الله عليه وسلم يُنْتَبَذُ لَهُ فِي سِقَاءٍ مِنْ لَيْلَةِ الِاثْنَيْنِ، فَيَشْرَبُهُ يَوْمَ الِاثْنَيْنِ وَالثَّلَاثَاءِ إِلَى الْعَصْرِ، فَإِنْ فَضَلَ مِنْهُ شَيْءٌ سَقَاهُ الْخَادِمَ أَوْ صَبَّهُ."],"takhrij":"صحيح: رواه مسلم في الأشربة (2004: 79) عن عبيد الله بن معاذ العنبري، حدثنا أبي، حدثنا شعبة، عن يحيى بن عبيد أبي عمر البهراني قال: سمعت ابن عباس يقول: فذكره. واللفظ الآخر من رواية محمد بن جعفر، عن شعبة به.","grade":"صحيح","chapter_ar":"باب في المدة التي يُشرب فيها النبيذ","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2004:79).","chapter_en":"The Period During Which Date Infusion May Be Drunk","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["ʿAbdullah ibn ʿAbbas said: Infusion would be made for the Messenger of Allah ﷺ at the beginning of the night, and he would drink it when morning came on that day, and the following night, and the next day, and the following night, and the next day until the afternoon. If anything remained, he would give it to the servant to drink, or he would order it to be poured away.","In another wording: Infusion would be made for the Messenger of Allah ﷺ in a leather water skin from Monday night, and he would drink it on Monday and Tuesday until the afternoon. If anything remained, he would give it to the servant to drink or pour it away."]},"buhuth":{"ar":["المدة المقدرة في هذا الحديث ثلاثة أيام وليلتان، إلى عصر اليوم الثالث، ثم سقاه الخادم، والسبب في ذلك أنه لم يظهر فيه ما يقتضي إراقته وإتلافه، لكن اتقاه في خاصة نفسه، أخذاً بغاية الورع، فسقاه الخادم؛ لأنه حلال جائز."],"en":["The period described in this hadith is three days and two nights, until the afternoon of the third day. Then he gave it to the servant to drink. The reason is that nothing had appeared in it requiring it to be poured away or destroyed, but he avoided it for himself out of the highest caution, and gave it to the servant because it was lawful and permissible."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2004:79)."},{"num":7554,"demo":false,"sanad":"","matn":["عَنْ يَحْيَى أَبِي عُمَرَ النَّخَعِيِّ قَالَ:  سَأَلَ قَوْمٌ ابْنَ عَبَّاسٍ عَنْ بَيْعِ الْخَمْرِ وَشِرَائِهَا وَالتِّجَارَةِ فِيهَا، فَقَالَ: أَمُسْلِمُونَ أَنْتُمْ؟ قَالُوا: نَعَمْ، قَالَ: فَإِنَّهُ لَا يَصْلُحُ بَيْعُهَا، وَلَا شِرَاؤُهَا، وَلَا التِّجَارَةُ فِيهَا، قَالَ: فَسَأَلُوهُ عَنِ النَّبِيذِ فَقَالَ: خَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي سَفَرٍ، ثُمَّ رَجَعَ، وَقَدْ نَبَذَ نَاسٌ مِنْ أَصْحَابِهِ فِي حَنَاتِمَ، وَنَقِيرٍ، وَدُبَّاءٍ، فَأَمَرَ بِهِ فَأُهْرِيقَ، ثُمَّ أَمَرَ بِسِقَاءٍ، فَجُعِلَ فِيهِ زَبِيبٌ وَمَاءٌ، فَجُعِلَ مِنَ اللَّيْلِ، فَأَصْبَحَ، فَشَرِبَ مِنْهُ يَوْمَهُ ذَلِكَ، وَلَيْلَتَهُ الْمُسْتَقْبِلَةَ، وَمِنَ الْغَدِ حَتَّى أَمْسَى، فَشَرِبَ، وَسَقَى، فَلَمَّا أَصْبَحَ، أَمَرَ بِمَا بَقِيَ مِنْهُ فَأُهَرِيقَ."],"takhrij":"صحيح: رواه مسلم في الأشربة (2004: 83) عن محمد بن أحمد بن أبي خلف، حدثنا زكريا بن عدي، حدثنا عبيد الله، عن زيد، عن يحيى أبي عمر النخعي قال: فذكره.","grade":"صحيح","chapter_ar":"باب في المدة التي يُشرب فيها النبيذ","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2004:83).","chapter_en":"The Period During Which Date Infusion May Be Drunk","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["Yahya Abu ʿUmar al-Nakhaʿi said: Some people asked Ibn ʿAbbas about selling wine, buying it, and trading in it. He said: “Are you Muslims?” They said: “Yes.” He said: “Then selling it, buying it, and trading in it are not valid.” He said: Then they asked him about date infusion. He said: The Messenger of Allah ﷺ went out on a journey, then returned, and some of his Companions had made infusion in green jars, hollowed palm trunks, and gourds. He ordered it to be poured away. Then he ordered that a leather water skin be brought, and raisins and water were placed in it at night. In the morning, he drank from it during that day, the following night, and the next day until evening. He drank from it and gave others to drink. Then when morning came, he ordered what remained of it to be poured away."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2004:83)."},{"num":7555,"demo":false,"sanad":"","matn":["عن ثمامة بن حَزْن القُشيري قَالَ: لَقِيتُ عَائِشَةَ، فَسَأَلْتُهَا عَنِ النَّبِيذِ فَدَعَتْ عَائِشَةُ جَارِيَةً حَبَشِيَّةً، فَقَالَتْ: سَلْ هَذِهِ فَإِنَّهَا كَانَتْ تَنْبِذُ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَتِ الْحَبَشِيَّةُ: كُنْتُ أَنْبِذُ لَهُ فِي سِقَاءٍ مِنَ اللَّيْلِ، وَأُوكِيهِ، وَأُعَلِّقُهُ، فَإِذَا أَصْبَحَ شَرِبَ مِنْهُ."],"takhrij":"صحيح: رواه مسلم في الأشربة (2005: 84) عن شيبان بن فروخ، حدثنا القاسم بن الفضل الحُدّاني، حدثنا ثمامة بن حزن القشيري فذكره.","grade":"صحيح","chapter_ar":"باب في المدة التي يُشرب فيها النبيذ","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2005:84).","chapter_en":"The Period During Which Date Infusion May Be Drunk","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["Thumamah ibn Hazn al-Qushayri said: I met ʿA’ishah and asked her about date infusion. ʿA’ishah called an Abyssinian slave girl and said: “Ask this one, for she used to make infusion for the Messenger of Allah ﷺ.” The Abyssinian woman said: “I used to make infusion for him in a leather water skin at night, tie it, and hang it up. When morning came, he would drink from it.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2005:84)."},{"num":7556,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ:  كُنَّا نَنْبِذُ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي سِقَاءٍ يُوكَى أَعْلَاهُ وَلَهُ عَزْلَاءُ، نَنْبِذُهُ غُدْوَةً فَيَشْرَبُهُ عِشَاءً، وَنَنْبِذُهُ عِشَاءً فَيَشْرَبُهُ غُدْوَةً."],"takhrij":"صحيح: رواه مسلم في الأشربة (2005: 85) عن محمد بن المثنى العنزي، حدثنا عبد الوهاب الثقفي، عن يونس (هو ابن عبيد)، عن الحسن (هو البصري)، عن أمه، عن عائشة قالت: فذكرته.","grade":"صحيح","chapter_ar":"باب في المدة التي يُشرب فيها النبيذ","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2005:85).","chapter_en":"The Period During Which Date Infusion May Be Drunk","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["ʿA’ishah said: We used to make infusion for the Messenger of Allah ﷺ in a leather water skin whose top was tied and which had an outlet. We would make it in the morning and he would drink it in the evening, and we would make it in the evening and he would drink it in the morning."]},"buhuth":{"en":["Her statement, “it had an outlet,” means an opening at the bottom of the leather water skin."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2005:85). قوله: “وله عزلاء” أي ثقب من أسفل السقاء."},{"num":7557,"demo":false,"sanad":"","matn":["عَنْ فيروز الديلمي قَالَ: أَتَيْنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْنَا: يَا رَسُولَ اللَّهِ قَدْ عَلِمْتَ مَنْ نَحْنُ؟ وَمِنْ أَيْنَ نَحْنُ؟ فَإِلَى مَنْ نَحْنُ؟ قَالَ: إِلَى اللَّهِ وَإِلَى رَسُولِهِ فَقُلْنَا: يَا رَسُولَ اللَّهِ، إِنَّ لَنَا أَعْنَابًا مَا نَصْنَعُ بِهَا؟ قَالَ: زَبِّبُوهَا قُلْنَا: مَا نَصْنَعُ بِالزَّبِيبِ؟ قَالَ: انْبِذُوهُ عَلَى غَدَائِكُمْ، وَاشْرَبُوهُ عَلَى عَشَائِكُمْ، وَانْبِذُوهُ عَلَى عَشَائِكُمْ، وَاشْرَبُوهُ عَلَى غَدَائِكُمْ، وَانْبِذُوهُ فِي الشِّنَانِ، وَلاَ تَنْبِذُوهُ فِي الْقُلَلِ؛ فَإِنَّهُ إِذَا تَأَخَّرَ عَنْ عَصْرِهِ صَارَ خَلاًّ."],"takhrij":"صحيح: رواه أبو داود (3710)، والنسائي (5736) والبيهقي (17423) كلهم من حديث السيباني، عن عبد الله بن الديلمي، عن أبيه قال: فذكره.","grade":"صحيح","chapter_ar":"باب في المدة التي يُشرب فيها النبيذ","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3710), al-Nasa’i (5736), and al-Bayhaqi (8/300).","chapter_en":"The Period During Which Date Infusion May Be Drunk","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["Fayruz al-Daylami said: We came to the Messenger of Allah ﷺ and said: “O Messenger of Allah, you know who we are, where we are from, and to whom we belong.” He said: “To Allah and to His Messenger.” We said: “O Messenger of Allah, we have grapes. What should we do with them?” He said: “Make them into raisins.” We said: “What should we do with the raisins?” He said: “Soak them for your midday meal and drink them with your evening meal; soak them for your evening meal and drink them with your midday meal. Make the infusion in worn leather water skins, and do not make it in jars, for if it remains beyond its time, it becomes vinegar.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (3710)، والنسائي (5736)، والبيهقي (17423)."},{"num":7558,"demo":false,"sanad":"","matn":["عن ابْنِ عَبَّاسٍ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَا يَشْرَبُ نَبِيذًا فَوْقَ ثَلَاثٍ."],"takhrij":"صحيح: رواه أبو عوانة (8123)، والطبراني في الكبير (10709) من طريق علي بن نصر الجهضمي، ثنا حبان بن هلال، ثنا سفيان بن حبيب، ثنا ابن جريج، عن سعيد بن ميناء، عن القاسم بن محمد، عن ابن عباس قال: فذكره.","grade":"صحيح","chapter_ar":"باب في المدة التي يُشرب فيها النبيذ","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Abu ʿAwanah (8123) and al-Tabarani in al-Kabir (10/357).","chapter_en":"The Period During Which Date Infusion May Be Drunk","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["Ibn ʿAbbas said: The Messenger of Allah ﷺ would not drink date infusion after three days."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو عوانة (8123)، والطبراني في الكبير (10709)."},{"num":7559,"demo":false,"sanad":"","matn":["عَنْ أَبِي حُمَيْدٍ السَّاعِدِيِّ قَالَ: أَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِقَدَحِ لَبَنٍ مِنَ النَّقِيعِ لَيْسَ مُخْمَرًا فَقَالَ:  أَلاَ خَمَرْتَهُ و لو تُعْرَضُ عَلَيْهِ عُودًا."],"takhrij":"صحيح: رواه مسلم في الأشربة (2010: 93) من طرق عن أبي عاصم، عن الضحاك، أخبرنا ابن جريج، أخبرني أبو الزبير، أنه سمع جابر بن عبدالله يقول: أخبرني أبو حميد قال: فذكره.","grade":"صحيح","chapter_ar":"باب إباحة شرب النبيذ إذا لم يشتد، والحث على تخمير الإناء","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2010:93).","chapter_en":"The Permissibility of Drinking Infusion If It Has Not Become Strong, and Encouragement to Cover the Vessel","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["Abu Humayd al-Saʿidi said: I brought the Prophet ﷺ a cup of milk from al-Naqiʿ that was not covered. He said: “Why did you not cover it, even by placing a stick across it?”"]},"buhuth":{"en":["His statement, “not covered,” means uncovered. Covering is called “takhmir,” and wine is so called because it covers the mind.","His statement, “even by placing a stick across it,” means putting a stick over it even crosswise. The meaning is that if he does not cover it fully, then at least he should place something across it, for Satan does not open something closed, as will come in the hadith of Jabir in the higher manners section."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2010:93). وقوله: “ليس مخمرا” أي ليس مغطى. والتخمير التغطية، ومنه الخمر لتغطيتها على العقل."},{"num":7560,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ قَالَ:  كُنَّا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَاسْتَسْقَى، فَقَالَ رَجُلٌ: يَا رَسُولَ اللَّهِ، أَلَا نَسْقِيكَ نَبِيذًا؟ فَقَالَ: بَلَى. قَالَ: فَخَرَجَ الرَّجُلُ يَسْعَى، فَجَاءَ بِقَدَحٍ فِيهِ نَبِيذٌ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَلَّا خَمَّرْتَهُ، وَلَوْ تَعْرُضُ عَلَيْهِ عُودًا؟. قَالَ: فَشَرِبَ."],"takhrij":"صحيح: رواه مسلم في الأشربة (2011: 94) عن أبي بكر بن أبي شيبة وأبي كريب – واللفظ لأبي كريب- قالا: حدثنا أبو معاوية، عن الأعمش، عن أبي صالح، عن جابر بن عبد الله قال: فذكره.","grade":"صحيح","chapter_ar":"باب إباحة شرب النبيذ إذا لم يشتد، والحث على تخمير الإناء","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2011:94).","chapter_en":"The Permissibility of Drinking Infusion If It Has Not Become Strong, and Encouragement to Cover the Vessel","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["Jabir ibn ʿAbdullah said: We were with the Messenger of Allah ﷺ, and he asked for something to drink. A man said: “O Messenger of Allah, shall we give you date infusion to drink?” He said: “Yes.” The man went quickly and brought a cup containing date infusion. The Messenger of Allah ﷺ said: “Why did you not cover it, even by placing a stick across it?” He said: Then he drank."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2011:94)."},{"num":7561,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ:  لَقَدْ سَقَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِقَدَحِي هَذَا الشَّرَابَ كُلَّهُ: الْعَسَلَ، وَالنَّبِيذَ، وَالْمَاءَ، وَاللَّبَنَ."],"takhrij":"صحيح: رواه مسلم في الأشربة (2008: 89) من طريق عفان، حدثنا حماد بن سلمة، عن ثابت، عن أنس قال: فذكره.","grade":"صحيح","chapter_ar":"باب إباحة شرب النبيذ إذا لم يشتد، والحث على تخمير الإناء","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2008:89).","chapter_en":"The Permissibility of Drinking Infusion If It Has Not Become Strong, and Encouragement to Cover the Vessel","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["Anas ibn Malik said: I gave the Messenger of Allah ﷺ all types of drink in this cup of mine: honey drink, date infusion, water, and milk."]}},"tuhfa":{},"full":1,"rep":[7583,9623],"tks":"صحيح: رواه مسلم (2008:89)."},{"num":7562,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: عَلِمْتُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَصُومُ، فَتَحَيَّنْتُ فِطْرَهُ بِنَبِيذٍ صَنَعْتُهُ فِي دُبَّاءٍ ثُمَّ أَتَيْتُهُ بِهِ، فَإِذَا هُوَ يَنِشُّ فَقَالَ: اضْرِبْ بِهَذَا الْحَائِطَ، فَإِنَّ هَذَا شَرَابُ مَنْ لاَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الآخِرِ."],"takhrij":"حسن: رواه أبو داود (3716)، والنسائي (5610)، وابن ماجه (3409) كلهم من حديث زيد بن واقد، عن خالد بن عبدالله بن حسين، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب إباحة شرب النبيذ إذا لم يشتد، والحث على تخمير الإناء","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3716), al-Nasa’i (5610), and Ibn Majah (3409).","chapter_en":"The Permissibility of Drinking Infusion If It Has Not Become Strong, and Encouragement to Cover the Vessel","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["Abu Hurayrah said: I knew that the Messenger of Allah ﷺ was fasting, so I waited for the time of his breaking the fast with an infusion I had made in a gourd. Then I brought it to him, and it was bubbling. He said: “Throw this against the wall, for this is the drink of one who does not believe in Allah and the Last Day.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3716)، والنسائي (5610)، وابن ماجه (3409)."},{"num":7563,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، أَنَّ وَفْدَ عَبْدِ الْقَيْسِ، قَالُوا: يَا رَسُولَ اللَّهِ فِيمَ نَشْرَبُ؟ قَالَ: لاَ تَشْرَبُوا فِي الدُّبَّاءِ وَلاَ فِي الْمُزَفَّتِ وَلاَ فِي النَّقِيرِ وَانْتَبِذُوا فِي الأَسْقِيَةِ. قَالُوا: يَا رَسُولَ اللَّهِ فَإِنِ اشْتَدَّ فِي الأَسْقِيَةِ؟ قَالَ: فَصُبُّوا عَلَيْهِ الْمَاءَ. قَالُوا: يَا رَسُولَ اللَّهِ. فَقَالَ لَهُمْ فِي الثَّالِثَةِ أَوِ الرَّابِعَةِ: أَهْرِيقُوهُ. ثُمَّ قَالَ: إِنَّ اللَّهَ حَرَّمَ عَلَىَّ أَوْ حُرِّمَ الْخَمْرُ وَالْمَيْسِرُ وَالْكُوبَةُ. قَالَ: وَكُلُّ مُسْكِرٍ حَرَامٌ.","قَالَ سُفْيَانُ: فَسَأَلْتُ عَلِيَّ بْنَ بَذِيمَةَ عَنِ الْكُوبَةِ، قَالَ: الطَّبْلُ."],"takhrij":"صحيح: رواه أبو داود (3696)، وأحمد (2476)، وصحّحه ابن حبان (5365) كلهم من طريق أبي أحمد الزبيري، ثنا سفيان (هو الثوري)، عن علي بن بذيمة، ثني قيس بن حَبتر النهشلي، عن ابن عباس قال: فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في إضافة الماء إلى النبيذ إذا اشتد ما لم يصل إلى حدّ الإسكار","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3696), Ahmad (2476), and authenticated by Ibn Hibban (5365).","chapter_en":"Adding Water to Infusion If It Becomes Strong, So Long as It Has Not Reached the Point of Intoxication","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["ʿAbdullah ibn ʿAbbas narrated that the delegation of ʿAbd al-Qays said: “O Messenger of Allah, what should we drink from?” He said: “Do not drink from gourds, pitch-coated vessels, or hollowed palm trunks. Make infusion in leather water skins.” They said: “O Messenger of Allah, what if it becomes strong in the leather water skins?” He said: “Pour water over it.” They repeated, “O Messenger of Allah.” On the third or fourth time, he said: “Pour it away.” Then he said: “Allah has forbidden to me — or He has forbidden — wine, gambling, and the drum.” He said: “Every intoxicant is forbidden.” Sufyan said: I asked ʿAli ibn Badhimah about the drum, and he said: “The drum.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه أبو داود (3696)، وأحمد (2476)، وصححه ابن حبان (5365)."},{"num":7564,"demo":false,"sanad":"","matn":["عَنْ رَجُلٍ من وفد عَبْدِ الْقَيْسِ، عَنْ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لاَ تَشْرَبُوا فِي نَقِيرٍ وَلاَ مُزَفَّتٍ وَلاَ دُبَّاءٍ، وَلاَ حَنْتَمٍ، وَاشْرَبُوا فِي الْجِلْدِ الموكأ عَلَيْهِ، فَإِنِ اشْتَدَّ فَاكْسِرُوهُ بِالْمَاءِ، فَإِنْ أَعْيَاكُمْ فَأَهْرِيقُوهُ."],"takhrij":"حسن: رواه أبو داود (3695)، والبيهقي (8/302) كلاهما من طريق عوف بن أبي جميلة، عن أبي القموص زيد بن علي، قال: حدثني رجل كان من الوفد الذين وفدوا على رسول الله صلي الله عليه وسلم من عبد القيس يحسب عوف أن اسمه قيس بن النعمان قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في إضافة الماء إلى النبيذ إذا اشتد ما لم يصل إلى حدّ الإسكار","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3695) and al-Bayhaqi (8/302).","chapter_en":"Adding Water to Infusion If It Becomes Strong, So Long as It Has Not Reached the Point of Intoxication","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["A man from the delegation of ʿAbd al-Qays narrated from the Prophet ﷺ that he said: “Do not drink from hollowed palm trunks, pitch-coated vessels, gourds, or green jars. Drink from leather that is tied closed. If it becomes strong, weaken it with water. If it overcomes you, pour it away.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3695)، والبيهقي (8/302)."},{"num":7565,"demo":false,"sanad":"","matn":["عن الْمُطَّلِبِ بن أَبِي وداعةأَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أُتِيَ بِإِنَاءِ نَبِيذٍ فَصَبَّ عَلَيْهِ الْمَاءَ حَتَّى تَدَفَّقَ، ثُمَّ شَرِبَ مِنْهُ."],"takhrij":"حسن: رواه الطبراني في الكبير (20/ح 689) عن العباس بن الفضل الأسفاطي، ثنا أحمد بن يونس، ثنا أبو شهاب، عن الأعمش، عن أبي صالح، عن المطلب بن أبي وداعة قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في إضافة الماء إلى النبيذ إذا اشتد ما لم يصل إلى حدّ الإسكار","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Kabir (20/291).","chapter_en":"Adding Water to Infusion If It Becomes Strong, So Long as It Has Not Reached the Point of Intoxication","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["Al-Muttalib ibn Abi Wadaʿah narrated that the Messenger of Allah ﷺ was brought a vessel of date infusion, so he poured water into it until it overflowed, then drank from it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (20/291)."},{"num":7566,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَنَّهُ قَالَ لِوَفْدِ عَبْدِ الْقَيْسِ: لَا تَشْرَبُوا فِي نَقِيرٍ، وَلَا مُقَيَّرٍ، وَلَا دُبَّاءٍ، وَلَا حَنْتَمٍ، وَلَا مَزَادَةٍ، وَلَكِنِ اشْرَبُوا فِي سِقَاءِ أَحَدِكُمْ غَيْرَ مُسْكِرٍ، فَإِنْ خُشِيَ شِرَّتُهُ فَلْيَصُبَّ عَلَيْهِ الْمَاءَ."],"takhrij":"حسن: رواه البيهقي (17430) من طريق أبي الأشعث أحمد بن المقدام، ثنا نوح بن قيس، عن ابن عون، عن محمد بن سيرين، عن أبي هريرة قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في إضافة الماء إلى النبيذ إذا اشتد ما لم يصل إلى حدّ الإسكار","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bayhaqi (8/302).","chapter_en":"Adding Water to Infusion If It Becomes Strong, So Long as It Has Not Reached the Point of Intoxication","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["Abu Hurayrah narrated from the Messenger of Allah ﷺ that he said to the delegation of ʿAbd al-Qays: “Do not drink from hollowed palm trunks, pitch-coated vessels, gourds, green jars, or large water skins whose tops have been cut off. Rather, drink from one of your leather water skins, without intoxication. If one fears its strength, let him pour water over it.”"]},"buhuth":{"en":["The conclusion from these hadiths is that it is permissible to drink infusion as long as it remains sweet. But if it remains for two days or around that and no smell or change is found in it, then do not drink it out of caution. Do as the Prophet ﷺ did: he either gave it to his servant to drink or ordered it to be poured away."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البيهقي (17430)."},{"num":7567,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله قال: نهى النبي صلى الله عليه وسلم عن الزبيب، والتمر، والبسر، والرطب.","وفي رواية: نَهَى رَسُولُ اللَّهِ صلى الله عليه وسلم عَنِ التَّمْرِ وَالزَّبِيبِ، وَنَهَى عَنِ التَّمْرِ وَالْبُسْرِ أَنْ يُنْبَذَا جَمِيعًا."],"takhrij":"متفق عليه: رواه البخاري في الأشربة (5601)، ومسلم في الأشربة (1986: 18) كلاهما من طريق ابن جريج، أخبرني عطاء، أنه سمع جابرا يقول: فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في انتباذ الخليطين من نوع واحد أو من نوعين","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5601) and Muslim (1986:18). The other narration is from al-Nasa’i (5560).","chapter_en":"Making Infusion from Two Mixed Items, Whether of One Type or Two Types","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["Jabir ibn ʿAbdullah said: The Prophet ﷺ forbade mixing raisins with dates, and unripe dates with fresh dates.","In another narration: The Messenger of Allah ﷺ forbade dates and raisins, and he forbade dates and unripe dates from being made into infusion together."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5601)، ومسلم (1986:18). والرواية الأخرى للنسائي nasai(5560)."},{"num":7568,"demo":false,"sanad":"","matn":["عن أَبِي قَتَادَةَ عَنْ أَبِيهِ، قَالَ: نَهَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُجْمَعَ بَيْنَ التَّمْرِ وَالزَّهْوِ، وَالتَّمْرِ وَالزَّبِيبِ، وَلْيُنْبَذْ كُلُّ وَاحِدٍ مِنْهُمَا عَلَى حِدَةٍ.","وفي لفظ: لا تنتبذوا الزهو والرطب جميعا، ولا تنتبذوا الرطب والزبيب جميعا، ولكن انتبذوا كل واحد عل حدته."],"takhrij":"متفق عليه: رواه البخاري في الأشربة (5602)، ومسلم في الأشربة (1988: 24) كلاهما من طريق هشام الدستوائي، أخبرنا يحيى بن أبي كثير، عن عبد الله بن أبي قتادة، عن أبيه قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في انتباذ الخليطين من نوع واحد أو من نوعين","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5602) and Muslim (1988:24). The wording is from al-Bukhari.","chapter_en":"Making Infusion from Two Mixed Items, Whether of One Type or Two Types","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["Abu Qatadah said: The Prophet ﷺ forbade combining dates with unripe dates, and dates with raisins, and commanded that each be made into infusion separately. In another wording: “Do not make infusion from unripe dates and fresh dates together, and do not make infusion from fresh dates and raisins together. Rather, make infusion from each one separately.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5602)، ومسلم (1988:24). واللفظ للبخاري."},{"num":7569,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ يَقُولُ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  نَهَى أَنْ يُخْلَطَ التَّمْرُ وَالزَّهْوُ ثُمَّ يُشْرَبَ، وَإِنَّ ذَلِكَ كَانَ عَامَّةَ خُمُورِهِمْ يَوْمَ حُرِّمَتِ الْخَمْرُ."],"takhrij":"صحيح: رواه مسلم في الأشربة (1981) عن أبي الطاهر أحمد بن عمرو بن سرح، أخبرنا عبد الله بن وهب، أخبرني عمرو بن الحارث، أن قتادة بن دعامة حدثه أنه سمع أنس بن مالك قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في انتباذ الخليطين من نوع واحد أو من نوعين","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1981).","chapter_en":"Making Infusion from Two Mixed Items, Whether of One Type or Two Types","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["Anas ibn Malik said: The Messenger of Allah ﷺ forbade mixing dates and unripe dates and then drinking it, and that was the common wine of the people on the day wine was forbidden."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1981)."},{"num":7570,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ:  نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الزَّبِيبِ وَالتَّمْرِ، وَالْبُسْرِ وَالتَّمْرِ، وَقَالَ: يُنْبَذُ كُلُّ وَاحِدٍ مِنْهُمَا عَلَى حِدَتِهِ."],"takhrij":"صحيح: رواه مسلم في الأشربة (1989) من طريق وكيع، عن عكرمة بن عمار، عن أبي كثير الحنفي، عن أبي هريرة قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في انتباذ الخليطين من نوع واحد أو من نوعين","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1989).","chapter_en":"Making Infusion from Two Mixed Items, Whether of One Type or Two Types","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ forbade mixing raisins with dates, and unripe dates with dates, and said: “Each one should be made into infusion separately.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1989)."},{"num":7571,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  نَهَى عَنِ التَّمْرِ وَالزَّبِيبِ أَنْ يُخْلَطَ بَيْنَهُمَا، وَعَنِ التَّمْرِ وَالْبُسْرِ أَنْ يُخْلَطَ بَيْنَهُمَا.","وفي رواية: من شرب النبيذ منكم فليشربه زبيبا فردا، أو تمرا فردا، أو بُسرا فرداً."],"takhrij":"صحيح: رواه مسلم في الأشربة (1987) عن يحيى بن يحيى، أخبرنا يزيد بن زريع، عن التيمي، عن أبي نضرة، عن أبي سعيد قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في انتباذ الخليطين من نوع واحد أو من نوعين","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1987).","chapter_en":"Making Infusion from Two Mixed Items, Whether of One Type or Two Types","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["Abu Saʿid al-Khudri narrated that the Prophet ﷺ forbade mixing dates and raisins together, and mixing dates and unripe dates together. In another narration: “Whoever among you drinks infusion, let him drink it from raisins alone, or dates alone, or unripe dates alone.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1987)."},{"num":7572,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ:  نَهَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُخْلَطَ التَّمْرُ وَالزَّبِيبُ جَمِيعًا، وَأَنْ يُخْلَطَ الْبُسْرُ وَالتَّمْرُ جَمِيعًا، وَكَتَبَ إِلَى أَهْلِ جُرَشَ يَنْهَاهُمْ عَنْ خَلِيطِ التَّمْرِ وَالزَّبِيبِ."],"takhrij":"صحيح: رواه مسلم (1990) عن أبي بكر بن أبي شيبة، حدثنا علي بن مسهر، عن الشيباني، عن حبيب، عن سعيد بن جبير، عن ابن عباس قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في انتباذ الخليطين من نوع واحد أو من نوعين","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1990).","chapter_en":"Making Infusion from Two Mixed Items, Whether of One Type or Two Types","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["Ibn ʿAbbas said: The Prophet ﷺ forbade mixing dates and raisins together, and mixing unripe dates and dates together. He wrote to the people of Jurash forbidding them from the mixture of dates and raisins."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1990)."},{"num":7573,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ:  نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الدُّبَّاءِ وَالْحَنْتَمِ، وَالْمُزَفَّتِ وَالنَّقِيرِ، وَأَنْ يُخْلَطَ الْبَلَحُ بِالزَّهْوِ."],"takhrij":"صحيح: رواه مسلم في الأشربة (1995: 41) عن أبي بكر بن أبي شيبة، حدثنا محمد بن فضيل، عن حبيب بن أبي عمرة، عن سعيد بن جبير، عن ابن عباس قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في انتباذ الخليطين من نوع واحد أو من نوعين","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1995:41).","chapter_en":"Making Infusion from Two Mixed Items, Whether of One Type or Two Types","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["Ibn ʿAbbas said: The Messenger of Allah ﷺ forbade gourds, green jars, pitch-coated vessels, hollowed palm trunks, and mixing green dates with dates that had begun to ripen and color."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1995:41)."},{"num":7574,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ: أَنَّهُ كَانَ يَقُولُ:  قَدْ نُهِيَ أَنْ يُنْبَذَ الْبُسْرُ وَالرُّطَبُ جَمِيعًا، وَالتَّمْرُ وَالزَّبِيبُ جَمِيعًا."],"takhrij":"صحيح: رواه مسلم في الأشربة (1991: 28) عن محمد بن رافع، حدثنا عبدالرزاق، أخبرنا ابن جريج، أخبرني موسى بن عقبة، عن نافع، عن ابن عمر قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في انتباذ الخليطين من نوع واحد أو من نوعين","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1991:28).","chapter_en":"Making Infusion from Two Mixed Items, Whether of One Type or Two Types","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar used to say: It has been forbidden to make infusion from unripe dates and fresh dates together, and from dates and raisins together."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1991:28)."},{"num":7575,"demo":false,"sanad":"","matn":["عَنْ رَجُلٍ، - قَالَ حَفْصٌ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: نَهَى عَنِ الْبَلَحِ وَالتَّمْرِ، وَالزَّبِيبِ وَالتَّمْرِ."],"takhrij":"صحيح: رواه أبو داود (3705)، والنسائي (5547)، وأحمد (18820) كلهم من طريق شعبة، ثنا الحكم، قال: سمعت ابن أبي ليلى، عن رجل من أصحاب النبي صلى الله عليه وسلم فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في انتباذ الخليطين من نوع واحد أو من نوعين","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3705), al-Nasa’i (5547), and Ahmad (18820).","chapter_en":"Making Infusion from Two Mixed Items, Whether of One Type or Two Types","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["A man from the Companions of the Prophet ﷺ narrated from the Prophet ﷺ that he forbade mixing unripe dates with dates, and raisins with dates."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (3705)، والنسائي (5547)، وأحمد (18820)."},{"num":7576,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: الزَّبِيبُ وَالتَّمْرُ هُوَ الْخَمْرُ. وَزَادَ فِي رِوَايَةِ: \"يَعْنِي إِذَا انتبذ جَمِيعًا\"."],"takhrij":"صحيح: رواه النسائي (5546)، والحاكم (4/141) كلاهما من طريق عبيد الله بن موسى، عن شيبان، عن الأعمش، عن محارب بن دثار، عن جابر قال: فذكره. والزيادة للحاكم، وقال: \"صحيح على شرط الشيخين\".","grade":"صحيح","chapter_ar":"باب ما جاء في انتباذ الخليطين من نوع واحد أو من نوعين","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (5546) and al-Hakim (7218).","chapter_en":"Making Infusion from Two Mixed Items, Whether of One Type or Two Types","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["Jabir narrated from the Prophet ﷺ that he said: “Raisins and dates are wine.” Another narration adds: “Meaning when they are made into infusion together.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (5546)، والحاكم (7218)."},{"num":7577,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُسَيْدٍ الأنصاري قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُجْمَعَ بَيْنَ التَّمْرِ وَالزَّبِيبِ."],"takhrij":"صحيح: رواه الطبراني في الكبير (19/ح 594) عن عبيد العجلي، ثنا محمد بن حاتم المؤدب، ثنا علي بن ثابت الجزري، ثنا عبد الحميد بن جعفر (هو الأنصاري)، حدثني يزيد بن أبي حبيب المصري، عن عراك بن مالك، عن أبي أُسيد الأنصاري قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في انتباذ الخليطين من نوع واحد أو من نوعين","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tabarani in al-Kabir (19/268).","chapter_en":"Making Infusion from Two Mixed Items, Whether of One Type or Two Types","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["Abu Usayd al-Ansari said: The Messenger of Allah ﷺ forbade combining dates and raisins."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الطبراني في الكبير (19/ح 594)."},{"num":7578,"demo":false,"sanad":"","matn":["عَنْ مَعْبَدِ بْنِ كَعْبِ بْنِ مَالِكٍ، عَنْ أُمِّهِ، وَكَانَتْ قَدْ صَلَّتِ الْقِبْلَتَيْنِ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَتْ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنْهَى أَنْ يُنْتَبَذَ التَّمْرُ وَالزَّبِيبُ جَمِيعًا، وَقَالَ: انْتَبِذْ كُلَّ وَاحِدٍ مِنْهَا وَحْدَهُ."],"takhrij":"حسن: رواه أحمد (23932)، والحميدي (356)، والطبراني في الكبير (25/147) كلهم من طريق محمد بن إسحاق، أخبرنا معبد بن كعب به فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في انتباذ الخليطين من نوع واحد أو من نوعين","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (23932), al-Humaydi (356), and al-Tabarani in al-Kabir (25/147).","chapter_en":"Making Infusion from Two Mixed Items, Whether of One Type or Two Types","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["Maʿbad ibn Kaʿb ibn Malik narrated from his mother, who had prayed toward both directions of prayer with the Messenger of Allah ﷺ. She said: I heard the Messenger of Allah ﷺ forbidding dates and raisins from being made into infusion together, and he said: “Make infusion from each one separately.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (23932)، والحميدي (356)، والطبراني في الكبير (25/147)."},{"num":7579,"demo":false,"sanad":"","matn":["عن أَبِي طَلْحَةَ الأنصاريأَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ الْخَلِيطَيْنِ."],"takhrij":"حسن: رواه الطبراني في الكبير (4715) عن زكريا بن يحيى الساجي، ثنا محمد بن عبد الملك بن أبي الشوارب، ثنا عمر بن رديح، عن عطاء بن أبي ميمونة، عن أنس، عن أبي طلحة قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في انتباذ الخليطين من نوع واحد أو من نوعين","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Kabir (5/102).","chapter_en":"Making Infusion from Two Mixed Items, Whether of One Type or Two Types","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["Abu Talhah al-Ansari narrated that the Messenger of Allah ﷺ forbade the two mixed items."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (4715)."},{"num":7580,"demo":false,"sanad":"","matn":["عَنْ أَبِي الْوَدَّاكِ، يَقُولُ: لَا أَشْرَبُ نَبِيذًا بَعْدَ مَا سَمِعْتُ أَبَا سَعِيدٍ يَقُولُ: أُتِيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِرَجُلٍ نَشْوَانَ، فَقَالَ: إِنِّي لَمْ أَشْرَبْ خَمْرًا، إِنَّمَا شَرِبْتُ زَبِيبًا وَتَمْرًا فِي دُبَّاءَةٍ، قَالَ: فَأَمَرَ بِهِ فَنُهِزَ بِالْأَيْدِي، وَخُفِقَ بِالنِّعَالِ، وَنَهَى عَنِ الدُّبَّاءِ، وَنَهَى عَنِ الزَّبِيبِ وَالتَّمْرِ يَعْنِي: أَنْ يُخْلَطَا."],"takhrij":"حسن: رواه أحمد (11279)، والنسائي في الكبرى (5292)، وصحّحه الحاكم (4/374) كلهم من طرق عن شعبة، عن أبي التياح، عن أبي الوداك، عن أبي سعيد الخدري قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في انتباذ الخليطين من نوع واحد أو من نوعين","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (11279), al-Nasa’i in al-Kubra (5292), and authenticated by al-Hakim (8129).","chapter_en":"Making Infusion from Two Mixed Items, Whether of One Type or Two Types","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["Abu al-Waddak said: I will not drink infusion after hearing Abu Saʿid say: A drunken man was brought to the Messenger of Allah ﷺ. He said: “I did not drink wine; I only drank raisins and dates in a gourd.” He said: He ordered that he be pushed with hands and struck with sandals. He forbade gourds, and he forbade raisins and dates, meaning that they be mixed together."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (11279)، والنسائي في الكبرى (5292)، وصححه الحاكم (8129)."},{"num":7581,"demo":false,"sanad":"","matn":["عَنِ امْرَأَةٍ، أَنَّهَا سَمِعَتْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: لَا تَنْتَبِذُوا التَّمْرَ وَالزَّبِيبَ جَمِيعًا، انْبِذُوا كُلَّ وَاحِدٍ مِنْهُمَا وَحْدَهُ."],"takhrij":"حسن: رواه البيهقي (17462) من طريق ابن وهب، أخبرني عبد الرحمن بن سلمان، عن عُقيل بن خالد، عن معبد بن كعب بن مالك، عن أخيه عبد الله بن كعب بن مالك، عن امرأة قالت: فذكرته.","grade":"حسن","chapter_ar":"باب ما جاء في انتباذ الخليطين من نوع واحد أو من نوعين","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bayhaqi (8/307).","chapter_en":"Making Infusion from Two Mixed Items, Whether of One Type or Two Types","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["A woman narrated that she heard the Messenger of Allah ﷺ say: “Do not make infusion from dates and raisins together. Make infusion from each one separately.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البيهقي (17462)."},{"num":7582,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ:  أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سُئِلَ عَنِ الْخَمْرِ تُتَّخَذُ خَلًّا؟ فَقَالَ: لَا."],"takhrij":"صحيح: رواه مسلم في الأشربة (1983) من طريق سفيان (هو الثوري)، عن السدي، عن يحيى بن عباد، عن أنس قال: فذكره.","grade":"صحيح","chapter_ar":"باب في النهي عن اتخاذ الخمر خلاً","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1983). Abu Dawud (3675) narrated it through another route with the wording: Abu Talhah asked the Prophet ﷺ about orphans who had inherited wine. He said: “Pour it away.” He said: “Shall I not make it into vinegar?” He said: “No.”","chapter_en":"The Prohibition of Turning Wine into Vinegar","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":18,"content":{"translation":{"en":["Anas narrated that the Prophet ﷺ was asked about wine being made into vinegar. He said: “No.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1983). ورواه أبو داود (3675) من وجه آخر بلفظ: أن أبا طلحة سأل النبي ﷺ عن أيتام ورثوا خمرا، قال: (( أهريقوها )). قال: أفلا أجعلها خلا؟ قال: (( لا ))."},{"num":7583,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ:  لَقَدْ سَقَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِقَدَحِي هَذَا الشَّرَابَ كُلَّهُ: الْعَسَلَ، وَالنَّبِيذَ، وَالْمَاءَ، وَاللَّبَنَ."],"takhrij":"صحيح: رواه مسلم في الأشربة (2008) من طريق عفان، ثنا حماد بن سلمة، عن ثابت، عن أنس قال: فذكره.","grade":"صحيح","chapter_ar":"باب شرب النبيذ في القدح الذي يشرب فيه الماء وغيره","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2008).","chapter_en":"Drinking Infusion from the Cup Used for Water and Other Drinks","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["Anas said: I gave the Messenger of Allah ﷺ all types of drink in this cup of mine: honey drink, date infusion, water, and milk."]}},"tuhfa":{},"full":1,"rep":[7561,9623],"tks":"صحيح: رواه مسلم (2008)."},{"num":7584,"demo":false,"sanad":"","matn":["عن ابْنِ عُمَرَ يَقُولُ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لُعِنَتِ الْخَمْرُ عَلَى عَشَرَةِ أَوْجُهٍ: بِعَيْنِهَا، وَعَاصِرِهَا، وَمُعْتَصِرِهَا، وَبَائِعِهَا، وَمُبْتَاعِهَا، وَحَامِلِهَا، وَالْمَحْمُولَةِ إِلَيْهِ، وَآكِلِ ثَمَنِهَا، وَشَارِبِهَا، وَسَاقِيهَا."],"takhrij":"حسن: رواه أبوداود (3674)، وابن ماجه (3380)، وأحمد (4787)، وابن أبي شيبة (21625)، والبيهقي (5/327) كلهم من طريق عبد العزيز بن عمر بن عبد العزيز، عن عبد الرحمن بن عبد الله الغافقي وأبي طعمة مولاهم أنهما سمعا ابن عمر يقول: فذكره.","grade":"حسن","chapter_ar":"باب لعن الله الخمر وشاربها وساقيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3674), Ibn Majah (3380), Ahmad (4787), Ibn Abi Shaybah (6/447), and al-Bayhaqi (5/327).","chapter_en":"Allah’s Curse upon Wine, the One Who Drinks It, and the One Who Serves It","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":20,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar said: The Messenger of Allah ﷺ said: “Wine is cursed in ten ways: itself, the one who presses it, the one for whom it is pressed, the one who sells it, the one who buys it, the one who carries it, the one to whom it is carried, the one who consumes its price, the one who drinks it, and the one who serves it.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[5790],"tks":"حسن: رواه أبو داود (3674)، وابن ماجه (3380)، وأحمد (4787)، وابن أبي شيبة (21625)، والبيهقي (5/327)."},{"num":7585,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ: لَعَنَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْخَمْرِ عَشَرَةً: عَاصِرَهَا، وَمُعْتَصِرَهَا، وَشَارِبَهَا، وَحَامِلَهَا، وَالْمَحْمُولَةَ إِلَيْهِ، وَسَاقِيَهَا، وَبَائِعَهَا، وَآكِلَ ثَمَنِهَا، وَالْمُشْتَرِيَ لَهَا، وَالْمُشْتَرَاةَ لَهُ."],"takhrij":"حسن: رواه الترمذي (1295)، وابن ماجه (3381) كلاهما من حديث أبي عاصم، عن شبيب بن بشر، عن أنس بن مالك قال: فذكره. وقال الترمذي: \"حسن غريب\".","grade":"حسن","chapter_ar":"باب لعن الله الخمر وشاربها وساقيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1295) and Ibn Majah (3381). Al-Tirmidhi said: “Hasan gharib.”","chapter_en":"Allah’s Curse upon Wine, the One Who Drinks It, and the One Who Serves It","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":20,"content":{"translation":{"en":["Anas said: The Messenger of Allah ﷺ cursed ten in connection with wine: the one who presses it, the one for whom it is pressed, the one who drinks it, the one who carries it, the one to whom it is carried, the one who serves it, the one who sells it, the one who consumes its price, the one who buys it, and the one for whom it is bought."]}},"tuhfa":{},"full":1,"dr":1,"rep":[5792],"tks":"حسن: رواه الترمذي (1295)، وابن ماجه (3381). وقال الترمذي: “حسن غريب”."},{"num":7586,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن عَبَّاسٍ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: أَتَانِي جِبْرِيلُ فَقَالَ: يَا مُحَمَّدُ إِنَّ اللَّهَ عَزَّ وَجَلَّ قَدْ لَعَنَ الْخَمْرَ، وَعَاصِرَهَا، وَمُعْتَصِرَهَا، وَشَارِبَهَا، وَحَامِلَهَا، وَالْمَحْمُولَةَ إِلَيْهِ، وَبَائِعَهَا، وَمُبْتَاعَهَا، وَسَاقِيَهَا، وَمُسْتَقِيَهَا."],"takhrij":"حسن: رواه أحمد (2897)، والبيهقي في الشعب (5196)، وصححه ابن حبان (5356)، والحاكم (4/145) كلهم من طريق مالك بن خير الزبادي، أن مالك بن سعد التُّجيبي حدّثه، أنه سمع ابن عباس فذكره. قال الحاكم: \"هذا حديث صحيح الإسناد\".","grade":"حسن","chapter_ar":"باب لعن الله الخمر وشاربها وساقيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (2897), al-Bayhaqi in al-Shuʿab (5196), and authenticated by Ibn Hibban (5356) and al-Hakim (7229).","chapter_en":"Allah’s Curse upon Wine, the One Who Drinks It, and the One Who Serves It","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":20,"content":{"translation":{"en":["ʿAbdullah ibn ʿAbbas said: I heard the Messenger of Allah ﷺ say: “Gabriel came to me and said: ‘O Muhammad, Allah, the Mighty and Majestic, has cursed wine, the one who presses it, the one for whom it is pressed, the one who drinks it, the one who carries it, the one to whom it is carried, the one who sells it, the one who buys it, the one who serves it, and the one who asks to be served it.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (2897)، والبيهقي في الشعب (5196)، وصححه ابن حبان (5356)، والحاكم (7229)."},{"num":7587,"demo":false,"sanad":"","matn":["عن عبدالله بن عمرو قَالَ: قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  إِنَّ الْمُقْسِطِينَ عِنْدَ اللَّهِ عَلَى مَنَابِرَ مِنْ نُورٍ عَنْ يَمِينِ الرَّحْمَنِ عَزَّ وَجَلَّ، وَكِلْتَا يَدَيْهِ يَمِينٌ، الَّذِينَ يَعْدِلُونَ فِي حُكْمِهِمْ وَأَهْلِيهِمْ وَمَا وَلُوا."],"takhrij":"صحيح: رواه مسلم في الإمارة (1827: 18) من طريق سفيان بن عيينة، عن عمرو بن دينار، عن عمرو بن أوس، عن عبد الله بن عمرو فذكره.","grade":"صحيح","chapter_ar":"باب فضل من تولى أمر المسلمين وحكم فيهم بالعدل","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1827:18).","chapter_en":"The Virtue of One Who Takes Charge of the Muslims’ Affairs and Judges Among Them with Justice","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["ʿAbdullah ibn ʿAmr said: The Messenger of Allah ﷺ said: “Indeed, the just will be with Allah upon pulpits of light, to the right of the Most Merciful, the Mighty and Majestic — and both of His hands are right hands — those who are just in their judgment, with their families, and in what they are entrusted with.”"]}},"tuhfa":{},"full":1,"rep":[6705,13347],"tks":"صحيح: رواه مسلم (1827:18)."},{"num":7588,"demo":false,"sanad":"","matn":["عن أبي هريرة أنّ رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قال: سَبْعَةٌ يُظِلُّهُمُ الله فِى ظِلِّهِ يَوْمَ لاَ ظِلَّ إِلاَّ ظِلُّهُ: إِمَامٌ عَادِلٌ، وَشَابٌّ نَشَأَ بِعِبَادَةِ الله، وَرَجُلٌ قَلْبُهُ مُعَلَّقٌ فِى المَسَاجِدِ، وَرَجُلاَنِ تَحَابَّا فِى الله اجْتَمَعَا عَلَيْهِ وَتَفَرَّقَا عَلَيْهِ، وَرَجُلٌ دَعَتْهُ امْرَأَةٌ ذَاتُ مَنْصِبٍ وَجَمَالٍ فَقَالَ: إِنِّى أَخَافُ الله، وَرَجُلٌ تَصَدَّقَ بِصَدَقَةٍ فَأَخْفَاهَا حَتَّى لاَ تَعْلَمَ شِمَالُهُ مَا تُنْفِقُ يَمِينُهُ، وَرَجُلٌ ذَكَرَ الله خَالِيًا فَفَاضَتْ عَيْنَاهُ."],"takhrij":"متفق عليه: رواه مالك في الشعر (14) عن خبيب بن عبدالرحمن الأنصاريّ، عن حفص بن عاصم، عن أبي سعيد أو عن أبي هريرة، فذكره.","grade":"متفق عليه","chapter_ar":"باب فضل من تولى أمر المسلمين وحكم فيهم بالعدل","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (14), Muslim (1031), and al-Bukhari (660).","chapter_en":"The Virtue of One Who Takes Charge of the Muslims’ Affairs and Judges Among Them with Justice","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ said: “There are seven whom Allah will shade in His shade on the Day when there is no shade except His shade: a just leader; a young person who grew up in the worship of Allah; a man whose heart is attached to the mosques; two men who love one another for the sake of Allah, meeting upon that and parting upon that; a man whom a woman of status and beauty calls, but he says, ‘I fear Allah’; a man who gives charity and conceals it so much that his left hand does not know what his right hand spends; and a man who remembers Allah in private, so his eyes overflow with tears.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (14)، ومسلم (1031)، والبخاري (660)."},{"num":7589,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ: عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  إِنَّمَا الْإِمَامُ جُنَّةٌ، يُقَاتَلُ مِنْ وَرَائِهِ وَيُتَّقَى بِهِ، فَإِنْ أَمَرَ بِتَقْوَى اللَّهِ عَزَّ وَجَلَّ وَعَدَلَ، كَانَ لَهُ بِذَلِكَ أَجْرٌ، وَإِنْ يَأْمُرْ بِغَيْرِهِ، كَانَ عَلَيْهِ مِنْهُ."],"takhrij":"متفق عليه: رواه البخاري في الجهاد والسير (2957)، ومسلم في الإمارة (1841) كلاهما من حديث أبي الزناد، عن الأعرج، عن أبي هريرة فذكره. والسياق لمسلم.","grade":"متفق عليه","chapter_ar":"باب فضل من تولى أمر المسلمين وحكم فيهم بالعدل","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2957) and Muslim (1841). The wording is from Muslim.","chapter_en":"The Virtue of One Who Takes Charge of the Muslims’ Affairs and Judges Among Them with Justice","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah narrated from the Prophet ﷺ that he said: “The leader is only a shield behind whom fighting is done and through whom protection is sought. If he commands mindfulness of Allah, the Mighty and Majestic, and acts justly, he will have reward for that. But if he commands something other than that, then it will be against him.”"]}},"tuhfa":{},"full":1,"rep":[7613],"tks":"متفق عليه: رواه البخاري (2957)، ومسلم (1841). والسياق لمسلم."},{"num":7590,"demo":false,"sanad":"","matn":["عَنْ سَعْدٍ بن تميم الأشعري قَالَ: قِيلَ: يَا رَسُولَ اللهِ، مَا لِلْخَلِيفَةِ مِنْ بَعْدَكِ؟ قَالَ: مِثْلُ الَّذِي لِي مَا عَدَلَ فِي الْحُكْمِ، وَأَقْسَطَ فِي الْقِسْطِ، وَرَحِمَ ذَا الرَّحِمَ، فَمَنَ فَعَلَ غير ذَلِكَ فَلَيْسَ مِنِّي، وَلَسْتُ مِنْهُ."],"takhrij":"حسن: رواه الطبراني في الكبير (6/55)، والبخاري في التاريخ الكبير (4/46)، وابن زنجويه في الأموال (39) كلهم من طريق أبي أيوب سليمان بن عبد الرحمن الدمشقي، حدثنا الوليد بن مسلم، حدثنا عبد الله بن العلاء، وغيره أنهما سمعا بلال بن سعد يحدث عن أبيه سعد فذكره. والسياق لابن زنجويه.","grade":"حسن","chapter_ar":"باب فضل من تولى أمر المسلمين وحكم فيهم بالعدل","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Kabir (6/55), al-Bukhari in al-Tarikh al-Kabir (4/46), and Ibn Zanjawayh in al-Amwal (39).","chapter_en":"The Virtue of One Who Takes Charge of the Muslims’ Affairs and Judges Among Them with Justice","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Saʿd ibn Tamim al-Ashʿari said: It was said: “O Messenger of Allah, what belongs to the successor after you?” He said: “The same as what belongs to me, as long as he is just in judgment, fair in distributing justice, and merciful toward relatives. Whoever does otherwise is not of me, and I am not of him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (6/55)، والبخاري في التاريخ الكبير (4/46)، وابن زنجويه في الأموال (39)."},{"num":7591,"demo":false,"sanad":"","matn":["عَنْ قَيْسِ بْنِ أَبِي حَازِمٍ قَالَ: دَخَلَ أَبُو بَكْرٍ عَلَى امْرَأَةٍ مِنْ أَحْمَسَ يُقَالُ لَهَا زَيْنَبُ، فَرَآهَا لَا تَكَلَّمُ، فَقَالَ: مَا لَهَا لَا تَكَلَّمُ؟ قَالُوا: حَجَّتْ مُصْمِتَةً، قَالَ لَهَا: تَكَلَّمِي فَإِنَّ هَذَا لَا يَحِلُّ، هَذَا مِنْ عَمَلِ الجَاهِلِيَّةِ، فَتَكَلَّمَتْ، فَقَالَتْ: مَنْ أَنْتَ؟ قَالَ: امْرُؤٌ مِنْ المُهَاجِرِينَ، قَالَتْ: أَيُّ المُهَاجِرِينَ؟ قَالَ: مِنْ قُرَيْشٍ. قَالَتْ: مِنْ أَيِّ قُرَيْشٍ أَنْتَ؟ قَالَ: إِنَّكِ لَسَئُولٌ، أَنَا أَبُو بَكْرٍ. قَالَتْ: مَا بَقَاؤُنَا عَلَى هَذَا الْأَمْرِ الصَّالِحِ الَّذِي جَاءَ الله بِهِ بَعْدَ الجَاهِلِيَّةِ؟ قَالَ: بَقَاؤُكُمْ عَلَيْهِ مَا اسْتَقَامَتْ بِكُمْ أَئِمَّتُكُمْ. قَالَتْ: وَمَا الْأَئِمَّةُ؟ قَالَ: أَمَا كَانَ لِقَوْمِكِ رُؤوسٌ وَأَشْرَافٌ يَأْمُرُونَهُمْ فَيُطِيعُونَهُمْ. قَالَتْ: بَلَى. قَالَ: فَهُمْ أُولَئِكِ عَلَى النَّاسِ."],"takhrij":"صحيح: رواه البخاري في مناقب الأنصار (3834) عن أبي النعمان، حدثنا أبو عوانة، عن بيانٍ أبي بشر، عن قيس بن أبي حازم قال: فذكره.","grade":"صحيح","chapter_ar":"باب فضل من تولى أمر المسلمين وحكم فيهم بالعدل","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (3834).","chapter_en":"The Virtue of One Who Takes Charge of the Muslims’ Affairs and Judges Among Them with Justice","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Qays ibn Abi Hazim said: Abu Bakr entered upon a woman from Ahmas named Zaynab and saw that she was not speaking. He said: “What is wrong with her that she does not speak?” They said: “She performed pilgrimage while keeping silent.” He said to her: “Speak, for this is not lawful. This is from the practice of the pre-Islamic period.” So she spoke and said: “Who are you?” He said: “A man from the emigrants.” She said: “Which emigrants?” He said: “From Quraysh.” She said: “From which branch of Quraysh are you?” He said: “You ask many questions. I am Abu Bakr.” She said: “How long will we remain upon this righteous matter that Allah brought after the pre-Islamic period?” He said: “You will remain upon it as long as your leaders remain upright over you.” She said: “And what are the leaders?” He said: “Did your people not have chiefs and nobles who commanded them and they obeyed them?” She said: “Yes.” He said: “Those are the ones over the people.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (3834)."},{"num":7592,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ الرَّحْمَنِ بْنِ شَُمَاسَةَ قَالَ:  أَتَيْتُ عَائِشَةَ أَسْأَلُهَا عَنْ شَيْءٍ فَقَالَتْ: مِمَّنْ أَنْتَ؟ فَقُلْتُ: رَجُلٌ مِنْ أَهْلِ مِصْرَ، فَقَالَتْ: كَيْفَ كَانَ صَاحِبُكُمْ لَكُمْ فِي غَزَاتِكُمْ هَذِهِ؟ فَقَالَ: مَا نَقَمْنَا مِنْهُ شَيْئًا، إِنْ كَانَ لَيَمُوتُ لِلرَّجُلِ مِنَّا الْبَعِيرُ فَيُعْطِيهِ الْبَعِيرَ، وَالْعَبْدُ فَيُعْطِيهِ الْعَبْدَ، وَيَحْتَاجُ إِلَى النَّفَقَةِ فَيُعْطِيهِ النَّفَقَةَ، فَقَالَتْ: أَمَا إِنَّهُ لَا يَمْنَعُنِي الَّذِي فَعَلَ فِي مُحَمَّدِ بْنِ أَبِي بَكْرٍ أَخِي أَنْ أُخْبِرَكَ مَا سَمِعْتُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَقُولُ فِي بَيْتِي هَذَا: اللَّهُمَّ مَنْ وَلِيَ مِنْ أَمْرِ أُمَّتِي شَيْئًا فَشَقَّ عَلَيْهِمْ فَاشْقُقْ عَلَيْهِ، وَمَنْ وَلِيَ مِنْ أَمْرِ أُمَّتِي شَيْئًا فَرَفَقَ بِهِمْ فَارْفُقْ بِهِ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1828) عن هارون بن سعيد الأيلي، حدثنا ابن وهب، حدثني حرملة، عن عبد الرحمن بن شمامة قال: فذكره.","grade":"صحيح","chapter_ar":"باب الترغيب في الرفق بالرعية","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1828).","chapter_en":"Encouragement to Be Gentle with the Subjects","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["ʿAbd al-Rahman ibn Shumasah said: I came to ʿA’ishah to ask her about something. She said: “Where are you from?” I said: “A man from the people of Egypt.” She said: “How was your governor toward you in this campaign of yours?” He said: “We found nothing to criticize in him. If a man’s camel died, he would give him another camel; if a man’s servant died, he would give him another servant; and if someone needed expenses, he would give him expenses.” She said: “What was done to my brother Muhammad ibn Abi Bakr does not prevent me from telling you what I heard from the Messenger of Allah ﷺ in this house of mine. He said: ‘O Allah, whoever is appointed over any matter of my nation and makes things difficult for them, make things difficult for him; and whoever is appointed over any matter of my nation and is gentle with them, be gentle with him.’”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1828)."},{"num":7593,"demo":false,"sanad":"","matn":["عَنْ أَبِي وَائِلٍ قَالَ: قَالَ عَبْدُ الله بن مسعود: لَقَدْ أَتَانِي الْيَوْمَ رَجُلٌ، فَسَأَلَنِي عَنْ أَمْرٍ مَا دَرَيْتُ مَا أَرُدُّ عَلَيْهِ، فَقَالَ: أَرَأَيْتَ رَجُلًا مُؤْدِيًا نَشِيطًا يَخْرُجُ مَعَ أُمَرَائِنَا فِي المَغَازِي، فَيَعْزِمُ عَلَيْنَا فِي أَشْيَاءَ لَا نُحْصِيهَا؟ فَقُلْتُ لَهُ: وَاللهِ مَا أَدْرِي مَا أَقُولُ لَكَ، إِلَّا أَنَّا كُنَّا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَعَسَى أَنْ لَا يَعْزِمَ عَلَيْنَا فِي أَمْرٍ إِلَّا مَرَّةً حَتَّى نَفْعَلَهُ، وَإِنَّ أَحَدَكُمْ لَنْ يَزَالَ بِخَيْرٍ مَا اتَّقَى الله، وَإِذَا شَكَّ فِي نَفْسِهِ شَيْءٌ سَأَلَ رَجُلًا فَشَفَاهُ مِنْهُ، وَأَوْشَكَ أَنْ لَا تَجِدُوهُ، وَالَّذِي لَا إِلَهَ إِلَّا هُوَ، مَا أَذْكُرُ مَا غَبَرَ مِنْ الدُّنْيَا إِلَّا كَالثَّغْبِ، شُرِبَ صَفْوُهُ، وَبَقِيَ كَدَرُهُ."],"takhrij":"صحيح: رواه البخاري في الجهاد (2964) عن عثمان بن أبي شيبة حدثنا جرير عن منصور عن أبي وائل قال: فذكره.","grade":"صحيح","chapter_ar":"باب عزم الإمام على الناس فيما يطيقون","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2964).","chapter_en":"The Leader’s Firm Command to the People Regarding What They Are Able to Bear","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Abu Wa’il said: ʿAbdullah ibn Masʿud said: Today a man came to me and asked me about a matter, and I did not know what to answer him. He said: “What do you think of a well-equipped, energetic man who goes out with our commanders in military campaigns, and they impose upon us things that we cannot bear?” I said to him: “By Allah, I do not know what to say to you, except that we were with the Prophet ﷺ, and perhaps he would not command us firmly in any matter more than once before we did it. One of you will continue to be upon good as long as he remains mindful of Allah. If something troubles him, he asks a man who removes that trouble from him; but soon you may not find such a person. By the One besides whom there is no god, I do not remember what has passed of this world except like a small pool: its clear part has been drunk, and its muddy part remains.”"]},"buhuth":{"en":["His phrase “well-equipped” means possessing complete equipment for war. His phrase “impose upon us” means to make matters difficult for us. His phrase “we cannot bear them” means we are unable to endure them. The “small pool” is stagnant water gathered in a low place."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (2964)."},{"num":7594,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى قَالَ:  كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا بَعَثَ أَحَدًا مِنْ أَصْحَابِهِ فِي بَعْضِ أَمْرِهِ قَالَ: بَشِّرُوا وَلَا تُنَفِّرُوا، وَيَسِّرُوا وَلَا تُعَسِّرُوا."],"takhrij":"صحيح: رواه مسلم في الجهاد (1732) من طرق عن أبي أسامة، عن بُريد بن عبد الله، عن أبي بُردة، عن أبي موسى فذكره.","grade":"صحيح","chapter_ar":"باب توصية الإمام لولاته وعماله بالتيسير على رعيتهم","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1732).","chapter_en":"The Leader’s Instruction to His Governors and Workers to Make Things Easy for Their Subjects","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Abu Musa said: Whenever the Messenger of Allah ﷺ sent one of his Companions on some task, he would say: “Give glad tidings and do not repel people; make things easy and do not make things difficult.”"]}},"tuhfa":{},"full":1,"rep":[12812],"tks":"صحيح: رواه مسلم (1732)."},{"num":7595,"demo":false,"sanad":"","matn":["عَنْ سَعِيدِ بْنِ أَبِي بُرْدَةَ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعَثَ مُعَاذًا وَأَبَا مُوسَى إِلَى الْيَمَنِ قَالَ: يَسِّرَا وَلاَ تُعَسِّرَا، وَبَشِّرَا وَلاَ تُنَفِّرَا، وَتَطَاوَعَا وَلاَ تَخْتَلِفَا."],"takhrij":"متفق عليه: رواه البخاري في الجهاد والسير (3038)، ومسلم في الجهاد (1733) كلاهما من طريق وكيع، عن شعبة، عن سعيد بن أبي بردة، عن أبيه، عن جده (وهو أبو موسى الأشعري) فذكره.","grade":"متفق عليه","chapter_ar":"باب توصية الإمام لولاته وعماله بالتيسير على رعيتهم","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3038) and Muslim (1733).","chapter_en":"The Leader’s Instruction to His Governors and Workers to Make Things Easy for Their Subjects","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Saʿid ibn Abi Burdah narrated from his father, from his grandfather, that the Prophet ﷺ sent Muʿadh and Abu Musa to Yemen and said: “Make things easy and do not make things difficult; give glad tidings and do not repel people; cooperate with one another and do not differ.”"]}},"tuhfa":{},"full":1,"rep":[14704],"tks":"متفق عليه: رواه البخاري (3038)، ومسلم (1733)."},{"num":7596,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلِّي اللَّهُ عَلَيْهِ وَسَلَّمَ: يَسِّرُوا وَلاَ تُعْسِرُوا، وَسَكَنُوا وَ لاتَّنْفِرُوا."],"takhrij":"متفق عليه: رواه البخاري في العلم (69)، ومسلم في الجهاد (1734) كلاهما من طرق عن شعبة، عن أبي التياح قال: سمعت أنس بن مالك يقول: فذكره.","grade":"متفق عليه","chapter_ar":"باب توصية الإمام لولاته وعماله بالتيسير على رعيتهم","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (69) and Muslim (1734).","chapter_en":"The Leader’s Instruction to His Governors and Workers to Make Things Easy for Their Subjects","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Anas ibn Malik said: The Messenger of Allah ﷺ said: “Make things easy and do not make things difficult; calm people and do not repel them.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (69)، ومسلم (1734)."},{"num":7597,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَلاَ كُلُّكُمْ رَاعٍ، وَكُلُّكُمْ مَسْئُولٌ عَنْ رَعِيَّتِهِ، فَالإِمَامُ الَّذِي عَلَى النَّاسِ رَاعٍ، وَهْوَ مَسْئُولٌ عَنْ رَعِيَّتِهِ، وَالرَّجُلُ رَاعٍ عَلَى أَهْلِ بَيْتِهِ، وَهْوَ مَسْئُولٌ عَنْ رَعِيَّتِهِ، وَالْمَرْأَةُ رَاعِيَةٌ عَلَى أَهْلِ بَيْتِ زَوْجِهَا وَوَلَدِهِ، وَهِيَ مَسْئُولَةٌ عَنْهُمْ، وَعَبْدُ الرَّجُلِ رَاعٍ عَلَى مَالِ سَيِّدِهِ وَهْوَ مَسْئُولٌ عَنْهُ، أَلاَ فَكُلُّكُمْ رَاعٍ، وَكُلُّكُمْ مَسْئُولٌ عَنْ رَعِيَّتِهِ."],"takhrij":"متفق عليه: رواه البخاري في الأحكام (7138) من طريق مالك، عن عبدالله بن دينار، عن عبد الله بن عمر فذكره. وليس الحديث في الموطأ برواية الليثي.","grade":"متفق عليه","chapter_ar":"باب مسؤولية الراعي عن رعيته","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (7138) and Muslim (1829:20).","chapter_en":"The Shepherd’s Responsibility for His Flock","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar narrated that the Messenger of Allah ﷺ said: “Indeed, each of you is a shepherd, and each of you is responsible for his flock. The leader over the people is a shepherd, and he is responsible for his flock. A man is a shepherd over the people of his household, and he is responsible for his flock. A woman is a shepherd over the household of her husband and his child, and she is responsible for them. A man’s servant is a shepherd over his master’s wealth, and he is responsible for it. Indeed, each of you is a shepherd, and each of you is responsible for his flock.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (7138)، ومسلم (1829:20)."},{"num":7598,"demo":false,"sanad":"","matn":["عَنْ مَعْقِلِ بن يَسَارٍ الْمُزَنِيِّ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَا مِنْ عَبْدٍ اسْتَرْعَاهُ اللَّهُ رَعِيَّةً فَلَمْ يَحُطْهَا بِنَصِيحَةٍ إِلاَّ لَمْ يَجِدْ رَائِحَةَ الْجَنَّةِ.","وفي رواية: فيموت وهو غاش لهم إلا حرّم الله عليه الجنة."],"takhrij":"متفق عليه: رواه البخاري في الأحكام (7150)، ومسلم في الإمارة (142: 21) كلاهما من طريق أبي الأشهب، عن الحسن، أن عبيد الله بن زياد عاد معقل بن يسار في مرضه الذي مات فيه، فقال له معقل: إني محدثك حديثا سمعته من رسول الله صلى الله عليه وسلم، سمعت النبي صلى الله عليه وسلم يقول: فذكره. والسياق للبخاري.","grade":"متفق عليه","chapter_ar":"باب مسؤولية الراعي عن رعيته","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (7150, 7151) and Muslim (142:21).","chapter_en":"The Shepherd’s Responsibility for His Flock","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Maʿqil ibn Yasar al-Muzani said: I heard the Prophet ﷺ say: “There is no servant whom Allah places in charge of a people, and he does not surround them with sincere care, except that he will not find the fragrance of Paradise.” In another narration: “If he dies while deceiving them, Allah will forbid Paradise for him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (7150، 7151)، ومسلم (142:21)."},{"num":7599,"demo":false,"sanad":"","matn":["عن الْحَسَنِ أن عائذ بن عمرو -وَكَانَ من أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - دَخَلَ على عبيد اللَّهِ بن زِيَادٍ فَقَالَ: أَيْ بُنَيَّ: إِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّ شَرَّ الرِّعَاءِ الْحُطَمَةُ. فَإِيَّاكَ أَنْ تَكُونَ مِنْهُمْ، فَقَالَ لَهُ: اجْلِسْ، فَإِنَّمَا أَنْتَ مِنْ نُخَالَةِ أَصْحَابِ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: وَهَلْ كَانَتْ لَهُمْ نُخَالَةٌ! إِنَّمَا كَانَتِ النُّخَالَةُ بَعْدَهُمْ وَفِي غَيْرِهِمْ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1830) عن شيبان بن فروخ، حدثنا جرير بن حازم، حدثنا الحسن به فذكره.","grade":"صحيح","chapter_ar":"باب مسؤولية الراعي عن رعيته","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1830).","chapter_en":"The Shepherd’s Responsibility for His Flock","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Al-Hasan narrated that ʿA’idh ibn ʿAmr, who was one of the Companions of the Messenger of Allah ﷺ, entered upon ʿUbaydullah ibn Ziyad and said: “My son, I heard the Messenger of Allah ﷺ say: ‘The worst shepherds are the harsh ones, so beware of being one of them.’” He said to him: “Sit down. You are only from the leftovers of the Companions of Muhammad ﷺ.” He replied: “Were there leftovers among them? Leftovers only came after them and among others.”"]},"buhuth":{"en":["The phrase “the harsh ones” refers to those who are violent with their subjects and do not show gentleness toward them. His phrase “from the leftovers” means: you are not from the virtuous Companions of the Messenger of Allah ﷺ, nor from their scholars and people of high rank, but from their lower class. “Leftovers” refers to the husks of flour."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1830)."}]);